/* 平成16年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h16.committeeSessions.push(...[{"id":"h16-20041129-6","meetingId":"h16-cm11","date":"2004年11月29日","dateIso":"2004-11-29","committee":"区民委員会","time":"午前１０時０５分～午前１１時５８分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"井上委員","kind":"質問","question":"最初に、幾つか質問なんですけれども、店頭回収のところで、収集運搬はどのぐらいの頻度で行われているかということが一つと、(1)と(2)の処理の仕方というのがバイパス的な発想で違うということはわかるんですけれども、(3)の拠点回収がこの流れになっているということは、どういう理由でなっているのかということで、拠点回収の場合に、ラベルはがしだとかそういったことを、拠点回収の中で。","respondent":"中山清掃リサイクル課長","answer":"確かに、流れからすると、なるべくシンプルにしていく、１本にしていくのが望ましいというふうには我々も認識しておりますけれども、ペットボトルの拠点の扱いは確かに課題だと考えていますけれども、ポイントとしては、圧縮、とりあえず拠点に集まった以降については。","voiceIndex":5,"id":"exchange-001"},{"speaker":"井上委員","kind":"意見","question":"そこに、なぜそういう作業をここにいつまでも発生させておくのかなということ、拠点回収のところというのは、資源回収を啓発する意味では重要なポイントだと思うんですけれども、だけど、そういう作業が本当に必要かどうかという見直しも必要なんじゃないかということと、あと、１本化していくということでは、どういうふうに、どこに持っていこうとしている方向があるのかということを。","respondent":"中山清掃リサイクル課長","answer":"それで、容器包装リサイクル法の改正、これは１７年度は一番佳境に入るのではないかというふうに言われておりますけれども、現在、区としてというよりは、２３区としての容器包装リサイクル法改正に向けて、東京都を通じて、統制していこうという中で。","voiceIndex":7,"id":"exchange-002"},{"speaker":"井上委員","kind":"質問・要望","question":"最後なんですけれども、ペットボトルの回収量がこういうふうにふえているということが、百ある中の回収量がふえているということじゃなくて、それと同じように生産量がふえているだけという問題も、一方では便利なペットボトルがふえているということも基本的にあるわけで、さらに発生抑制という部分で、やっぱり行政として、出すものを集めるだけで、一生懸命税金を使うよりも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"},{"speaker":"原委員","kind":"質問・要望","question":"１点だけ、確認をさせていただきたいんですけれども、収集された後の今のご説明にあった大井ストックヤード、民間処理の施設ですね。片方は、容器包装リサイクル法で、指定法人ルートで引き取ってもらっていると。結局、片方は１キロ10円で売却をしていながら、片方は容器包装リサイクル法の肩書きで引き取ってもらっているというふうになるわけですよね、そこら辺のところをもう少し。","respondent":"中山清掃リサイクル課長","answer":"ストックヤードの整備というのは、そういうふうな方向で検討をですけれども、当然、整備にそれなりのコストがかかるということで、予算化の問題が幾つか出てまいります。","voiceIndex":11,"id":"exchange-004"},{"speaker":"菊地委員","kind":"質問","question":"１点だけお聞かせ願いたいんですけど、店頭回収のところなんですけれども、今、常設箱を１９８カ所置いてありますけれども、区内のスーパー、コンビニのたぐいですけれども、実際に何割ぐらい、これが設置をされているのかというところと、それから、ここで回収をされたのは、昨年度で５３３トンですか、区内で実際に年間発生している総量、実際に回収された部分から、一定程度予測をされるのかどうか。","respondent":"中山清掃リサイクル課長","answer":"品川区内で消費されているペットボトルの量がどれだけなのかというのは、非常に把握は基本的に難しいと考えていますが、例えば我が国全体で生産されているペットボトルを人口で案分すれば、そんなに。","voiceIndex":17,"id":"exchange-005"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"原委員の質問にも関連しますけど、民間処理施設は民間会社がやっているんだろうと思いますけど、成果物がキロ１０円で、品川全量行っても５０万トンですから、５００万円の売り上げということで、ほかの区からも、ほかの施設からも、１０倍にしても５,０００万円の売り上げで、設備、その他で、どうやってこれは経営が成り立つのかなという感じがするんですけれども。","respondent":"中山清掃リサイクル課長","answer":"ですから、先ほど申し上げた安定的にこの後も売却が続くのかということについては、当然、採算が合わなくなれば、これは買ってやれないという形になる可能性がありますので、その辺の見きわめも必要かなというふうに申し上げておりますけれども、現段階では、少なくともこういう。","voiceIndex":21,"id":"exchange-006"},{"speaker":"塚本副委員長","kind":"質問","question":"そのときには、民間側がこの段階でどれだけコストをかけているか、どういう経営内容になっているかということを知らないと、我々は比較しようがないわけですね。行政側がやることで、これがいいか悪いかという部分、そういうところまで比べなきゃいけない時代にきているわけですから、今の質問に答えられないのは、ちょっと困っちゃうということがあると思うんだけど、その点はどうなんですか。","respondent":"中山清掃リサイクル課長","answer":"個別の施設についての把握はなかなか難しいというふうに申し上げたんですけれども、今、確かに井上委員からもあった、容器包装リサイクル法の検討の中で、事業者の負担とか、行政との関係がどうなっているかというのも問われてきているわけですけれども。","voiceIndex":23,"id":"exchange-007"},{"speaker":"塚本副委員長","kind":"質問","question":"先ほど井上委員が質問した際の大井ストックヤードの充実ということは、行政主導型の方向で、品川区はとりあえず考えていますよというメッセージをもらったんだと思うんだけれども、そうじゃない選択があるわけですから、民間がどこまでできるかということで、コストパフォーマンスというか、それでも税金が入っているか、私にはわかりませんけれども、何しろ種ができて、それを育てたほうが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-008"}]},{"id":"topic-02","title":"１番目の専決処分の報告について第２５号","agenda":"１番目の専決処分の報告について第２５号","exchanges":[{"speaker":"原委員","kind":"確認","question":"１点だけ、確認させてください。平成１３年３月から３年かかっているわけなんですよね。なぜそんなにかかったかという経過、経緯をお話しいただければと思います。","respondent":"冨岡品川清掃事務所長","answer":"事件発生から３年余がかかっているわけですが、さまざまな事情が重なりまして、示談の交渉におくれが生じ時間を要したというところが原因でございまして、ご報告が遅くなって申しわけないと考えています。","voiceIndex":31,"id":"exchange-009"},{"speaker":"原委員","kind":"意見","question":"非常にさまざまなというのはわかりますけれども、一つは、通常、こういった事件の場合に、大体、後からいろいろ和解したりなんかするわけですけれども、３年というのはあまりかからないですよね、状況的に。それともう一つ、この２００万というのは、保険の補てんはどのぐらいのところでされているんでしょうね。その辺のところを、ちょっとお願いします。","respondent":"冨岡品川清掃事務所長","answer":"過去の事例によりますと、ほとんど１年ぐらいの間で落ちつくという状況があります。それで、２００万の保険ですけれども、人身分につきましては、自賠責の範囲内でおさまっているです。","voiceIndex":33,"id":"exchange-010"},{"speaker":"原委員","kind":"質問","question":"それで、今、１年が大体基準だというんですが、こういう場合は、区のほうも例えば弁護士を立てるとか、向こうは弁護士を立てられたわけですよね。そうすると、窓口は弁護士同士になったんですか、それとも弁護士を向こうだけで、こっちはそうじゃないと、どういう形になっていたんですか、ここのところの経過は。","respondent":"中山清掃リサイクル課長","answer":"平成１３年の事故ということで、前任所長のときの事故ということがありまして、要は今、品川清掃所長が申し上げたとおり、途中から、お知り合いだという弁護士が入ってきて、我々も任意保険を契約しておりますけれども、そこに示談交渉を委任しておりますから。","voiceIndex":37,"id":"exchange-011"},{"speaker":"菊地委員","kind":"質問","question":"一つだけお聞きしたいと思います。先ほど、報告をされたときに、研修ですとか講習という話をされていまして、事故そのものは、いろんな要因が重なって防げない場合もあるんでしょうけれども、通常、清掃事業車にしても、公用車にしても、どういうふうに研修、講習というのが日常的に行われているのか、そこだけ教えてくれませんか。","respondent":"冨岡品川清掃事務所長","answer":"月に３回ほど、平素の会議というものがありますが、そのところで、まず事故等の簡単な研修を行って、発生状況を説明し、こういうことのないようにということと、警察に年２回来ていただきまして、安全運転の講習会というものを行っております。","voiceIndex":40,"id":"exchange-012"},{"speaker":"菊地委員","kind":"意見","question":"通常、トラックの運送なんかですと、日々の安全点検なんかもそうですし、技能的な講習、そういうものをやるところが民間の会社でもあるみたいですけど、通常、清掃のところでは、あまり技能的な講習みたいなものというのはあまりやらないものなんですよね。","respondent":"冨岡品川清掃事務所長","answer":"専門の場所に参りまして、茨城なんですけれども、そちらのほうで研修を行うということもあるんですが、運転手は大体、年に１名ぐらいずつ研修のほうを行っているという状況です。","voiceIndex":42,"id":"exchange-013"},{"speaker":"塚本副委員長","kind":"質問","question":"任意の保険の入り方ですけど、自治体、２３区は共通でしたっけ。その辺の仕組みをもう一度教えてほしいのと、それから、清掃事業の場合は、東京都から移管になったときに保険会社とのかかわり方が違って来たかどうか、変化があるのかないのか教えてください。","respondent":"冨岡品川清掃事務所長、中山清掃リサイクル課長","answer":"東京都の事例のことですけれども、平成７年までは自賠責だけで、任意保険や何かも加入をしていなくて、それぞれの清掃事務所の担当の技能長が示談の交渉に当たっていたというようなことを聞いております。若干補足がありますけど、最初の保険の入り方ですが、基本的には、先ほど所長が申し上げた２３区で入っている、いわゆる自治体賠償、これは、車両に起因する保険は除かれますので、わかりやすく言えば、交通事故は任意保険に加入し。","voiceIndex":45,"id":"exchange-014"}]},{"id":"topic-03","title":"なければ、本件については、以上で終了いたします。 (2) 中学生の主張大会について 次に、２番目ですが、中学生の主張大会","agenda":"なければ、本件については、以上で終了いたします。 (2) 中学生の主張大会について 次に、２番目ですが、中学生の主張大会","exchanges":[{"speaker":"山村委員","kind":"質問・要望","question":"発表者の選定はどういうふうに行っておられるのか。基本的に私はこの大会に行くことにちょっと、大体、この大会に見に来ているのは、中学校の生徒とかは来ているのか。先生はどうか、そこら辺を教えていただきたいと思います。","respondent":"田村地域活動課長","answer":"それと参加者、これはあくまで地区委員会の事業ですから、基本的にそれぞれ地区委員会、９００人弱が品川区内にいますので、その方と各中学校の、全校全員来ると入れないので、大体人数を５名から１０名程度に絞って、全校参加しています。","voiceIndex":54,"id":"exchange-015"},{"speaker":"山村委員","kind":"質問","question":"中学生の主張大会というのは、これは何のためにやっていると思えばよろしいんでしょうか。目的が読めないのですが。","respondent":"田村地域活動課長","answer":"それで、まして地域と私のかかわりを強く持ってもらいたいというような、あくまで目的は中学生の社会参加という事業を新たに打ち出して実施した、そういう経緯があります。","voiceIndex":56,"id":"exchange-016"},{"speaker":"山村委員","kind":"質問","question":"ほかに何かあるんでしょうか。社会参加と言えるのか、ちょっと疑問なんですけれども。","respondent":"田村地域活動課長","answer":"それを、地域の絆を高めるということで、中学生の地域と私を、どういうふうに中学生がとらえているかということを、中学校と地域の方々の前で、自分の考え方を発表するということが、やはり地域に関心を持つ大きなきっかけになるんじゃないかということで開催しているものです。","voiceIndex":58,"id":"exchange-017"},{"speaker":"山村委員","kind":"質問・要望","question":"地区委員長と町会長たちの自己満足的な大会に終わらないことを要望しておきます。自己満足なんじゃないかなと僕は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-018"},{"speaker":"山路委員","kind":"質問・要望","question":"将来に人材として育っていく方が、こういう機会で発表をして、それを経て社会の大きな人材に育っていくということを、やっぱり区もそれを支援していくというは、こういうことに関してどういうかかわりをやられているのかなと。講演ということですけど、そのほかにかかわりというのは、どういう形でかかわっているか、ちょっと聞かせていただきたいと思います。","respondent":"田村地域活動課長","answer":"それと、区とのかかわりですけど、難しいのが、実際に私が連合会事業の事務局をやっています。そうすると、ほかのニュースポーツ大会にしても、ほかの講演会にしても、アドバイス、議論できる素材はうちのほうでいろいろ調べたり、他区の状況だとか調べてお出しします。","voiceIndex":66,"id":"exchange-019"},{"speaker":"山路委員","kind":"質問・要望","question":"ありがとうございました。目立たないんですけど、社会の構成、地域の構成上、非常に重要な一面も持っていると思うんですね。１８名の方を最大に激励してあげていただきたいことを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-020"},{"speaker":"塚本副委員長","kind":"質問","question":"コンセプトはわかりました。類似の中学生の弁論大会ですとか、英語で何かやったり、いろんなのがあるかと思うんですけど、その辺の競合と言ったらいいんですか、それがどうなっているのかわかりますか。","respondent":"田村地域活動課長","answer":"そうすると、第４回の主張大会を見ても、地域と私というとらえ方が、全く個々人によって違います。","voiceIndex":71,"id":"exchange-021"},{"speaker":"塚本副委員長","kind":"提案","question":"ぜひ競合箇所との位置づけを考えながらやっていただきたいのと、それから、提案ですけど、裏面に地域と私と書いてありますけど、せっかく５回終わるわけですから、次回からは、初回の入賞者とテーマとかそういうものを載せていったら、歴史がわかるようになると思うし、また、地域と私の大タイトルのほかに、年度によって小タイトル。","respondent":"田村地域活動課長","answer":"ですから、趣旨は十分理解できますので、私のほうがやるというよりも、そういうようなご提案があったので、青少年の連合会の打ち合わせの中で、そういうことも踏まえて検討してもらうような形にしたいと考えております。","voiceIndex":73,"id":"exchange-022"},{"speaker":"山村委員","kind":"質問","question":"塚本委員の関連で、冊子みたいなのがありますということですけれども、テーマを前に持ってきて、後援とか協賛とかは後ろに持ってこないと、どっちが重要なのかですので、こういうところにも、自己満足的なところが出ているのではないでしょうか。","respondent":"田村地域活動課長","answer":"その辺も含めて、先ほども申し上げましたけど、私のほうでこうしたいというんじゃなく、毎年、例年５年にわたってこういう形になっているので、それなりの経過があってこういうふうな形になっていると思いますから、ですから、今、山村委員のご提案のあったこと。","voiceIndex":77,"id":"exchange-023"},{"speaker":"井上委員","kind":"質問","question":"私は、本当に子どもたちが意見表明をする場はたくさんあっていいと思うので、とてもいいことだと思いますから、サポートしていってほしい企画だと思うんですけど、５回の入場者数というのは、どのような実績になっているのかおわかりになりますでしょうか。","respondent":"田村地域活動課長","answer":"実は、第４回はきゅりあんのほうでやっていて、今回は荏原文化センターということで、若干、会場が違っています。大体、例年の過去のを見ますと、３００から４００名程度、先ほど、昨年度で４３０ぐらいという形になっておりますので、大体４００前後の人数で参加者がいるです。","voiceIndex":79,"id":"exchange-024"},{"speaker":"井上委員","kind":"提案","question":"塚本委員にかぶるんですけど、私も、どうしてテーマが毎年、５年間一緒だということに対して、子どもたちの主張というところでは、もっと子どもたち自身が主張したいことが自由に選べたらいいんじゃないかと思ったときに、主催が青少年対策地区委員会の連合会だということが、今話して、ちゃんと落ちたので、そういう趣旨、目的があるのかもしれないんですけれども。","respondent":"田村地域活動課長","answer":"１点目の、中学生主張大会のテーマなんですけど、これは先ほどもお話ししたように、目的は、中学生の自立性だとか社会性を育てる機会とするということと、地域の青少年の健全育成指導者、いわゆる地区委員ですよね、そういう方が。","voiceIndex":81,"id":"exchange-025"},{"speaker":"井上委員","kind":"質問・要望","question":"区報は、私が気がつかないだけだったら申しわけないんですが、そういうアピールの仕方だとか、１３の地域センターというのは、なかなか用事のない人は訪れる機会が少ないと思いますから、やっぱりもっと積極的に広報ができる体制があるはずですので、取り組んでいただきたいということを、広報のことは、ちょっと気がついてなかったら申しわけないんですが、進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-026"},{"speaker":"井上委員","kind":"質問・要望","question":"実際に、こういうところの人集めというのは、相当大変な思いをされているわけですから、先ほど公募と言って、公募じゃなくて、知らせるというだけの話で、各地域が自分たちの地域で動員をしているというのが、ここの場合にそういうことはわかりませんけれども、そういうケースが多くて、逆の意味で、地区委員の方たちがご苦労されているということを、もうちょっと現状を把握されて。","respondent":"田村地域活動課長","answer":"ちょっと私の説明が悪いのかもしれないですけど、地区委員会の連合会事業の目的は、青少年の健全育成活動の一層の充実と、地区委員会相互の交流を図るための事業を委託する、地区委員会相互なんですよ、大元の連合会事業というのは。","voiceIndex":86,"id":"exchange-027"},{"speaker":"原委員","kind":"質問","question":"単純な質問です。中学生の主張発表者の１２番、日野中学校３年はわかるんですが、大崎第一地区の９年というのは何ですか。","respondent":"田村地域活動課長","answer":"私のほうでも、教育委員会のほうに、いわゆる中学生３年が９年というような見方で記載することが正しいのかということで、私のほうは、そのように教育委員会のほうへ協議し、差し支えないとの見解をもらっています。","voiceIndex":88,"id":"exchange-028"},{"speaker":"原委員","kind":"質問","question":"既にそういったところで、それを公に使い始められるものですか。というのは、開校していないんでしょう。開校して、それが小中一貫校で、ここの子も出て、それでここで９年というのはわかるんだけど、まだ開校する前に９年というのは使えるんですかね。","respondent":"田村地域活動課長","answer":"ただ、原委員がおっしゃっていたように、勇み足じゃないけど、先走ってここを書いちゃっていると。もう一度、これは、まだ一般には配布はしていませんので、再度確認したいと思います。","voiceIndex":90,"id":"exchange-029"},{"speaker":"原委員","kind":"質問・要望","question":"再度確認をしていただきたいのと、これが当日配られるんですよね。そうすると、いや、何だという話に必ずなると思うので、ここだけちょっと訂正をするなどしていただきたいので、よろしくお願いします。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-030"},{"speaker":"原委員","kind":"質問","question":"区民消火隊とミニポンプ隊へ感謝状の贈呈式をやられるんですけど、この辺は毎年何隊かずつに分けてやられているのか、どういう基準になっているのか教えてください。","respondent":"久保田防災課長","answer":"ちょうど、区民消火隊とミニポンプ隊員の感謝状贈呈式は、従来は別な日に設定してやっていたんですけれども、一昨年から、防災フェアの中でぜひともやったほうがいいんじゃないかというふうに考えて実施しているものです。","voiceIndex":96,"id":"exchange-031"},{"speaker":"山村委員","kind":"質問","question":"回収容器等を薬局のほうから配布するということですが、この費用というか、そこら辺のコストとか、回収容器とかの補助とかはどこから薬局に出ているものなのか、教えてください。","respondent":"中山清掃リサイクル課長","answer":"そのほか、この薬局と申しますのは、先ほど説明を飛ばしてしまいましたが、区内全薬局ということじゃなくて、薬剤師会に加入しているところで、約１５０店舗の薬局ということだそうですが、こういう、注射針の回収をする表示の看板、こういったものも薬剤師会で用意いたします。","voiceIndex":102,"id":"exchange-032"},{"speaker":"山村委員","kind":"質問","question":"品川区としては、補助とか、そういうふうなご予定はないんですか。","respondent":"中山清掃リサイクル課長","answer":"基本的には、現段階では予定してございません。以上です。","voiceIndex":104,"id":"exchange-033"},{"speaker":"井上委員","kind":"確認","question":"確認だけです。医療機関で出されたものも、薬局に持っていって回収してもらってもいいということですか。薬局から出たものだけですか。","respondent":"中山清掃リサイクル課長","answer":"あくまでも薬局で販売されたものです。医療機関で出されたものは、医療機関へお戻しするようにということを、医療機関において、患者に対応されるということです。以上です。","voiceIndex":108,"id":"exchange-034"},{"speaker":"井上委員","kind":"質問・要望","question":"これって、知らない人は、ああ、はがすのかなというふうにメッセージになると思うんですけれども、これはこのまま赤く入れておけば、ああ、キャップだけでいいんだなということが、こういうところにちょっとだけ配慮すれば、文章を入れなくても伝わるのになと思うんですけど、もし来年、これはもうでき上がったものになるならば、まだまだうちの近くで出しているところも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":113,"id":"exchange-035"},{"speaker":"川西委員長","kind":"質問・要望","question":"ほかに要望はありますか。エコボックスの配置は、公的施設を中心に配置されているんですか。従来、一般質問や総括質問なんかで、予算・決算特別委員会で申し上げているように、エコボックスの設置場所をもう少し増やせないかという主張をずっとしてきたんですけど、どのように検討、これはできちゃっているものですから要望なんですけど、検討されたかどうかということだけ教えてください。","respondent":"中山清掃リサイクル課長","answer":"拠点とエコボックスを合わせて、少なくとも５００メートル以内には必ずあるようにというような配置でバランスをとってまいりました。","voiceIndex":114,"id":"exchange-036"},{"speaker":"山村委員","kind":"質問","question":"カレンダーに広告が入っているんですが、別にごみと関係ないところで、これは公募したのか、どのぐらいお金を取っているか、そしていつからやり出して、あまり効果はないと思うんですが、収入はどこに入っているのか教えてください。","respondent":"中山清掃リサイクル課長、川西委員長","answer":"これは、事前に募集をいたしました。７月でしたか、広報で募集をして、応募をされたということで、特にごみ、リサイクルに絡む事業者じゃなくても、広告の掲載要件に合っていればということでやっておりますが、１コマ１万円です。以上で終わります。本日の予定は、以上ですべて終了です。これをもちまして、区民委員会を終了いたします。大変ご協力ありがとうございました。","voiceIndex":117,"id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2410#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":33864,"voices":119}},{"id":"h16-20041129-7","meetingId":"h16-cm11","date":"2004年11月29日","dateIso":"2004-11-29","committee":"厚生委員会","time":"午前１０時０２分～午後４時１０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を76件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"右の旧条例２項をご覧ください。深刻な少子化を改善するために、子育て支援の一層の充実が求められています。少子化社会対策基本法では、「少子化の進展に歯どめをかけることが今我等に強く求められている」と述べ、その対策は喫緊の課題と位置づけられています。本条例が実施されれば、子育て世代を励まし、２人目、３人目を持つことへの動機付けになるのではないでしょうか。２３区を調査いたしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":3,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"本会議場において須藤委員からご質問をいただきました件、１点まずお答えをいたしたいと思います。子どもの人数に関して、専業主婦と共働きで働いている方の差があるのかどうかというご質問をいただきましたけれども、先日の次世代育成支援対策推進行動計画の中にいろいろ資料が載っておりましたが、この中に資料がございました。ほとんど変わらないといった状況です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":5,"id":"exchange-002"},{"speaker":"本間委員","kind":"質問・要望","question":"それぞれといいますのは、提出者に求めているんじゃなくて、こちらの理事者のほうですね。どのようになって国のほうの子育て支援策をかなり全国的な規模で地方自治体に対して力を求めながら進めていくという部分が出てきているかと思います。その部分、それから東京都はどのような考え、受けとめ方をして、どのようなことをやっているのか、この２点についてお答え願います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-003"},{"speaker":"本間委員","kind":"質問","question":"一つの新しい時代の中で、エンゼルプランに基づいてさまざまなことが子育て支援を充実する一環として出てきているわけですが、特にこの中で、保育料についての考え方はどのようになっていますか、教えてください。","respondent":"金子保育課長","answer":"これは従来からの流れでこうなってきたわけですけれども、最近はご案内のとおり三位一体改革によりまして、公立保育所の負担金、国、それから都道府県の負担金がなくなるなど、保育所に通っている子どもだけではなくて。","voiceIndex":11,"id":"exchange-004"},{"speaker":"本間委員","kind":"質問","question":"そうすると、これまでの保育料についての考え方が国の三位一体改革の流れに沿う形で入所しているお子さんのみならず、入所していない、例えば家で預かったりだとかというふうな部分の子どもたちと同じような、特に差をつけない形の考え方にとらえているということでよろしいんでしょうか。","respondent":"金子保育課長","answer":"今現在、まだ具体的にそこまでの検討にはなっていないというふうに考えますが、大きな流れとしては、そういう方向にあるのかなと私は考えております。","voiceIndex":13,"id":"exchange-005"},{"speaker":"本多委員","kind":"質問・要望","question":"先ほど提出者から説明がありました。ちょっと何点かお聞かせいただきたいと思うんですが、よろしいでしょうか。その辺の格差についてはどのようにお考えか、ちょっと教えていただければありがたいんですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問・要望","question":"専業主婦型、この専業主婦はずっと仕事をしていない、専業主婦は１.３１です。この先に行って、１０年、１４年、この先も言ったほうがいいですかね。１５年から１９年、もうちょっと長くなりますと、就業継続型が２.３３、専業主婦型が２.２８です。もともと保育料のところで、そういった格差がついているといったとらえ方をしていますので、このことはご理解をいただきたいなと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-007"},{"speaker":"本多委員","kind":"質問・要望","question":"多子家庭にはいろんな制度も既にあると思うんですが、その現状、生活支援がある内容的なものを区の理事者から現状をお聞かせいただきたいんですが、経済的な、今この内容については議案については保育料の経済的支援ということなんですが、総合的に生活支援として考えていく場合、現状、多子家庭にはどのような支援があるのか、ちょっと教えていただきたい。","respondent":"辻田児童課長","answer":"そういう形で、いろんな形で私どものほうとしては単に経済的支援をするというだけでなく、全体的な子育て支援、それから少子化対策というような形での子育て支援の整備を図っているという状況です。","voiceIndex":17,"id":"exchange-008"},{"speaker":"本多委員","kind":"質問・要望","question":"現状では、いろんな対応がされているというところで、わかりました。それとあと最後に１点ちょっとお聞きしたいんですが、この議案の内容で、条例改正をした場合なんですが、収入減の金額的にはどのぐらいの金額になるのか、また、それに対する何かかかわりといいますか、影響について、区でもしその辺をシミュレーションといいますか、想定ができていれば、ちょっと教えていただきたいと思います。","respondent":"金子保育課長","answer":"２,６００万円の永続的な減収がされた場合には、一般財源でこれを補てんしていかなければならないということから、現在の経済情勢のもとでは非常に厳しいものがあるというふうに考えてあります。","voiceIndex":19,"id":"exchange-009"},{"speaker":"嶋委員","kind":"質問・要望","question":"いわゆる保育所を使っていない、非保育所利用者との格差を区としては縮める意味で在宅支援という形で今頑張って、在宅でも子育てがやっていただけるように、いろんなリフレッシュとか、区で考えていただいていると思うんですが、そういう意味で、利用者と利用していない方たちの格差をどのようにお考えか、お聞かせいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"予算のところなんですが、合計で約２,６００万円ということなんですが、決して少ない額ではないわけですけれども、子育て支援には大変有効なお金で活用されるなと思っているんですが、一つには、今回補正予算も組まれていませんし、予算編成の時期ではないので、今回ここで皆様に十分ご審議をしていただいて、ご支持いただいて、可決をしていただければ、今後十分ちょっと勉強しまして。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-011"},{"speaker":"嶋委員","kind":"質問・要望","question":"わかりました。在宅の方たちは、余裕があって働かないわけではありませんので、全体全部が保育園に入れるならば、すごくこれは納得しますが、現在待機者もいたりとかしますけど、そこら辺に対するお考えをちょっとお聞かせいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった面では、ありとあらゆる面から女性が自ら求めて働く部分もあるし、経済的なもので働かざるを得ないという面もかなり大きい、そういった面では、働く女性の支援というのが一層進むことがこの間言われています合計特殊出生率、これの低下を防いでいるというのが、やっぱり外国の例を見ましても、デンマークとかフランスなどでは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-013"},{"speaker":"嶋委員","kind":"意見","question":"今、ライフスタイルとおっしゃいましたよね。そういう意味では、ある程度決めて、その人のスタイルとして保育園に預ける、預けない部分ですけど、じゃあ、その非保育者のいわゆるお子さんに対して、デンマークとかでなくて、品川区のそういう方たちのお話は聞いたことがありますか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":25,"id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"就労の困難さの中で減っていて、生活が大変であるということは聞いています。でも、この間、在宅の子育てをしていらっしゃる方々の支援を求めている中身というのは、どちらかというと、ほんとうに孤立した子育て、あと、夫がほんとうに１０時とか１１時とか、残業でおそく帰ってきて、子育ての悩みを相談する相手がいないとか、そういった支えを求めているという声はたくさん伺っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-015"},{"speaker":"嶋委員","kind":"質問・要望","question":"今までいろんな多子家庭に関しては、税金の控除とか、保育料も応能で２６段階になっていると。それなりに収入によって保育料も決まって、品川区は２６段階にやってくださる。ただ、やはり私は保育園に入っている方はもちろんそれだけの恩恵を受けていますが、行っていない方たちに対しての思いももうちょっと調べていただきたいなと思いましたので、お聞かせいただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-016"},{"speaker":"南副委員長","kind":"提案","question":"そういうふうな状況がほんとうに言われている中で、そこをどうしようかということで子育て支援策を国が挙げてつくろうということになっている、その一環の中で品川区の地域の行政として子育て支援をどうするかと、そういうところでの私たちの提案だということをちょっと見ていただきたいなということを、ちょっとあえてお話ししたいと思いました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":28,"id":"exchange-017"},{"speaker":"築舘委員","kind":"提案","question":"それは保育園に行っている人も行っていない人もすべて分け隔てなくやっているわけですよ。だから、そういうことをむしろ全体で考えたらどうですかということを私、皆さん、ほとんどの方が言っているわけで、この提案というのは、そうじゃなくて、保育園に行っている人の第２子、第３子以降の人の無料にしてくださいとか、そういう形だけで矮小化しているわけですよね。その点についてどうですか、提出者。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":29,"id":"exchange-018"},{"speaker":"飯沼委員","kind":"提案","question":"本会議場での一般質問でも、まず子どもを産むという入り口のところの妊婦検診の無料化を拡大してほしいとか、認可の保育園ではなく、認証保育園などに預けていらっしゃる家庭のいろんな形での就労の形を保障するという意味もありますけれども、保育料の負担に対する軽減をしてほしいなど、これからもありとあらゆるところでできることを提案して改善をしていきたいなと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":30,"id":"exchange-019"},{"speaker":"築舘委員","kind":"質問","question":"結局財源にも限りがあるわけですから、やはり何でも政策的にやっていこうということでしたら、やっぱりばらまき福祉というふうに言われてくるわけで、その財源が三位一体でも、どんどん国のほうも削られてくるとか、そういった動きになってくるわけなんで、やはりその支出といいますか、いかに有効であるべきかという施策をもっと考えていかないと、あれもこれもということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-020"},{"speaker":"南副委員長","kind":"質問・要望","question":"今いろいろとばらまき福祉的な発言もありましたけれども、そしたら、私は逆に伺いたいんですけど、品川区の少子化の状況が０.８５とさっき提出者の飯沼委員からありましたけども、その０.８５をどう見るか、自民党のご意見、どういうふうに見て、どういうふうな対策を立てたらいいのかと考えていらっしゃるのか、あるいは具体的にどういう予算要望をされているのか、その辺、ちょっと教えていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-021"},{"speaker":"築舘委員","kind":"質問","question":"ですから、保育園に行っていない家庭も児童センターとか、そういった家庭あんしんセンターとか、そういうところで、家庭だけで悩んだりするんではなくて、やはり区がそういう環境面での支援をしていくべきだと自民党は前から言っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-022"},{"speaker":"本多委員","kind":"意見","question":"経済的については、今年の初めに保育料の料金改定の議案とか、予算特別委員会でうちの意見をさんざん出させていただいたと思うので、そのとおりなんですが、例えば今こちらの議案の中にあるように、３の無料というようなところが出されておりますが、うちの意見としては、保育料の経済的については、例えば２６段階の階層も。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":35,"id":"exchange-023"},{"speaker":"本間委員","kind":"質問・要望","question":"そのために一生懸命このように議論しているわけですから、不公平感はないのか、専業主婦と働く人たちとのあれはどうなのかとか、あるいはお金の使い方をどうしたらいいのか、子育て支援は保育園だけなのか、地域でみんなやるべきことじゃないのかとか、社会保障のあり方とか、さまざまな要素の中の部分で品川区としてはこれまで何ができるかということでやってきたわけですので、話をほかに振ると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-024"},{"speaker":"南副委員長","kind":"提案","question":"あれもこれも一遍にはできないから、一つずつ段階を積み重ねていくことが必要なんじゃないかということで、今回そういう提案をしているというのは、提出者のほうから繰り返し話がありますので、それは私も同じ思いで議論に参加しておりますので、ですから、決して不真面目にやっているつもりはありませんし、それから横に振っている方向を間違って振っているということでもなくて、全体的に議論する中で。","respondent":"金子保育課長、辻田児童課長","answer":"先ほどお尋ねになりましたのは、企画部のほうで所管しております次世代育成支援対策の行動計画策定のための地域協議会、こちらが現在の段階で策定した案で今区民に広くパブリックコメントを求めているというところのものですので。すべての子育て家庭にあまねくサービスが行き渡るような形での施策という形でこれは実施しているです。","voiceIndex":37,"id":"exchange-025"},{"speaker":"南副委員長","kind":"質問・要望","question":"したがって、できたら答弁していただきたいのと、それから、今まで、じゃあパブリックコメントを離れて区民の皆さんの経済的負担の軽減というところについては、担当されていた保育料の部分で、所管の課長としては経済的負担のところについてはどういうふうに認識をお持ちなのか、これを伺いたいと思います。","respondent":"辻田児童課長、金子保育課長","answer":"ただ、私ども全体的な子育て支援を図るための経済的支援ということで、今子育て支援全体が今その方向に行っておりますので、そういうことは必要だというぐあいに考えているため、こういう施策を実施しているです。現在の保育料の水準ですけれども、これは３月の予算特別委員会でもご説明したかと思いますが、私どもとしては、現在国の徴収基準額の６０％が政策的な目標として持っているですので。","voiceIndex":41,"id":"exchange-026"},{"speaker":"南副委員長","kind":"質問","question":"０.８５という品川区の現状に対して、じゃあどういうふうにこれを底上げしていけるか。これについて、ちょっと改めて伺いたいんです。したがって、やっぱりこういう実際の状況をよく調査研究しながら、品川区にも引き当てていく努力をしていくべきじゃないかなというふうに思いますので、改めてその辺についてどういうふうに見解を持っていらっしゃるのか、二つ伺いたいと思います。","respondent":"辻田児童課長","answer":"ただ、今品川区としてできることというのは何かということで、先日医療面、生活における安心感を確保するということで子どもすこやか医療費助成というものを、これも本来ですと経済的支援ということで低所得者対策というような形の福祉的施策が本来ですけど。","voiceIndex":44,"id":"exchange-027"},{"speaker":"南副委員長","kind":"確認","question":"すべての子ども。ですから、そういうことが子どもをもう１人じゃあ産んで、ほんとうは欲しいんだから産みたいよと、そういう気持ちに発展していくというふうに思いますので、この乳幼児医療費と子どもすこやか医療費の助成制度の拡充に代表されるように、保育料の部分でも、あるいはそのほかの経済的支援でも、ほんとうに充実させていく必要があるということを私は強く思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ご審議ありがとうございました。１９７７年が一般会計予算の保育所の運営費のところで０.８３％、これがピークで、その後どんどん下がっているわけです。そういった面では、住民の一番近いところにいる地方自治体が区民の願いである、特に今回は経済的支援、子育ての経済的支援を求めている声を取り上げたわけですけれども、地方が取り上げて国を動かしていく、こういった姿勢が大事だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-029"},{"speaker":"本多委員","kind":"質問","question":"ただ、経済の支援の仕方を公平にしてほしいと我々は主張をしておりまして、まして、格差をなくしてほしいというふうに我々は主張をずっとしているわけで、今までのこのやりとりで明確になったのは、確かに経済的に支援をすると、区の入りの部分が減ってしまうということで先ほどからも答弁いただいて、ということは、保育行政のサービス低下にもつながりかねない、その収入が減ったということは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-030"},{"speaker":"嶋委員","kind":"提案","question":"私たちもずっと提案もさせていただきましたし、先ほども妊婦検診を無料にということもずっと私ども言い続けてまいりましたことですので、しっかりと保育園のいわゆる無料にすることは、先ほども自民党のほうもおっしゃったように、格差を広げていくということになっておりますので、公明党としてもやはりその格差を広げること、公平さに関しては、ちょっとこれには乗れないということで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":50,"id":"exchange-031"},{"speaker":"本間委員","kind":"質問・要望","question":"先ほども申し上げているつもりですけれども、この改正をする条例についてどうかというふうな部分でもっとやっていただきたいということで、先ほど私は不真面目なということを言ったわけでありまして、その辺は焦点はどこにあるのか、そのための周辺の情報をいろいろとらせていただいたということでありますので、誤解のないようにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-032"},{"speaker":"南副委員長","kind":"提案","question":"まだ提案してはおりませんけど、私立保育園だとか、家庭にいらっしゃる方々への乳幼児医療費も８年間にわたって、８回にわたって条例改正提案もしてきましたし、すべての子ども、子育て世帯に対応したサービスの充実を求めてやってきましたので、今回はその一つとして保育料の負担軽減を出しているというところはご理解いただきたいと思います。私としては、ぜひ賛成をしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":52,"id":"exchange-033"}]},{"id":"topic-02","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"築舘委員","kind":"質問","question":"そうしますと、今のご説明を聞いていますと、都の加算補助ですか、あれはほんとうにそのまま別に削減もされないし、それから来年度に向けても改定する予定はないというふうに都は言っているというお話だったんで、そのとおりでよろしいんですかね。","respondent":"金子保育課長","answer":"来年度に向けて改定する予定はないというふうに担当セクションのほうでは申しております。","voiceIndex":59,"id":"exchange-034"},{"speaker":"築舘委員","kind":"質問・要望","question":"そうしますと、第一の存続を求める意見書といっても意味がないわけですね。別に都加算補助はそのまま存続するわけですから、意見書を上げてもしようがないというふうに思うんですけど、この紹介議員にもなっていらっしゃる方は今いませんけれども、どういう理由で、同じ会派の方はいらっしゃるから、もしわかれば教えていただきたい。どういう形で請願されたのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-035"},{"speaker":"南副委員長","kind":"質問","question":"したがって、東京都のところが、来年度が予定がないというそこのところがどれだけのもので聞いたらいいのかなということを私課長のご答弁を伺いながらちょっと感じていたんですけども、ほんとうに具体的に進められているということは事実ですから、そういうレールの上でこの請願は質疑をされたほうがいいんじゃないかなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-036"},{"speaker":"築舘委員","kind":"意見","question":"だから、そこのところがちょっとまだわからないなという、南副委員長のご説明はありましたけれども、わからないなという気がするんですけどね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-037"},{"speaker":"飯沼委員","kind":"質問","question":"今年の５月６日に東京都の児童福祉審議会から都市型保育サービスへの転換と福祉改革という意見具申が出ているんですが、この中にこの都加算のことが載っているんですが、これはまだ意見具申なので、その辺をどう受けとめていらっしゃるのかというのをお伺いしたいのと、東京都のところで我が党の議員の質問に対しては、かなり意見も言っておられるんです。","respondent":"金子保育課長","answer":"ただ、これは東京都の諮問機関が出した見解ですので、これについて東京都がどういう方針を出したというのはまだ聞いていませんので、具体的には来年度についても動きがないということですので、私どもは先ほど申し上げたとおりの現況であるというふうに考えております。","voiceIndex":64,"id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問・要望","question":"延々とまだ続くんですけれども、このところで一つ気になったのは、「都の考えとして、保育所の運営等は基本的に国基準によって必要な水準を確保することができるものと考えています」と、ここに私引っかかったんですが、この都加算の請願のところでは、保育所の運営というのは基本的には国の最低基準があって、そこに東京都の加算があって、今どのくらい残っているかわかりませんが。","respondent":"金子保育課長","answer":"いろいろ長々とお話しいただいて、質問のところは、今東京都の先ほど申し上げた保育所事業実施要綱に基づく部分だとは思いますが、ここでかなり項目数としてはたくさんあります。","voiceIndex":66,"id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問・要望","question":"一つ国基準への考え、東京都においては、これでやれるという見解で、区のほうはこの辺、国基準についてどう考えているのか、もう一回お答えをいただきたいと思います。","respondent":"金子保育課長","answer":"ただ、東京都もおっしゃっているとおりですけれども、都市型の保育というニーズが全国一律のものではないというところから一定の加算というものもまた必要な部分はあるだろうかというふうに考えてあります。","voiceIndex":68,"id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問","question":"ごめんなさい、肝心なところを聞き漏らしました。国基準の考えでやっていけると一定考えを持っているというとらえ方でよろしかったんでしょうか、すみません、もう一回お願いします。","respondent":"金子保育課長","answer":"基本的にはそういう考えを持っています。ただ、先ほど申し上げましたのは、都市型の保育のニーズと、これに適切に対応していかなければならない、ここをどう考えるかということが一つのポイントであるということでご理解いただきたいと思います。","voiceIndex":70,"id":"exchange-041"},{"speaker":"飯沼委員","kind":"意見","question":"このことに対して、進んでいないので見直していくということを具申しているんであって、東京都がこのことについて考えていくという方向を示しているにもかかわらず、品川区が一概に否定はしないという言い方でいいのかどうか、その点が１点と、あと国基準への考えをもうちょっと聞きたいなと思うんですが、国基準の職員配置をもう一回改めて聞きたいと思いますし。","respondent":"金子保育課長","answer":"それから２番目の東京都の補助について、多額のものであるだろうというご指摘でしたけれども、最初のほうで説明申し上げたとおり、この多くの項目のうち、金額的に高い部分というのは、区部では財政調整制度のほうの基準財政需要額の算定項目に組み込まれていますので。","voiceIndex":72,"id":"exchange-042"},{"speaker":"飯沼委員","kind":"質問・要望","question":"特に先ほど１１時間開所のところ、私ここのところの人員と、あと予算のところが膨大な額になると思うんですが、この辺ちょっと人員的なもので国基準と都基準加算のところを対比して、ちょっと大枠でいいんですが、人数的なものを知らせてほしいなと、どのくらいの比重でこの都加算の部分が占められているのか、ちょっとお聞かせをいただきたいと思います。","respondent":"金子保育課長","answer":"２点目のご質問なんですけれども、これはでも、先ほど申し上げたとおり、財調の算定基準の項目に入っている話なので、これを実際に対比でどうのこうのと出してくるのは、議論としてはあまり意味がないことだというふうに私は考えてあります。","voiceIndex":74,"id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問","question":"予算のところで出なくても結構なんですが、特に人員のところなので、人数は明らかに出ているんですよね。区の最低の基準の配置人数と、都の加算と。先ほど０歳児保育のところが大きいのと、１１時間開所という話だったんで、私はこの１１時間開所のところ、昔から特例対策とかいった名目でついていますけれども、国基準というのは、昭和２３年にできた基準なんですね。基本が８時間開所でしたよね。","respondent":"金子保育課長","answer":"０歳児保育と１１時間開所についてのいろいろご意見といいますか、いただきつつ質問になっているのかと思いますが、先ほど申し上げたとおりなんですけれども、これはあくまでも区部では財調に入っているので、直接的にこれが補助として来ているわけではないので。","voiceIndex":76,"id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ちょっとすみません。でも、実際的に人員のところがどうなっているのかと、そこに波及して、子どもたちにとって、どういうことを示唆しているのかなというところも先を読みながらやっていかないと大変なことになるのではないでしょうか。ここの請願者の方々は今回品川区に対してはこの１項目ですが、東京都に対しても請願をされていますよね。","respondent":"金子保育課長","answer":"先ほどから申し上げておりますように、一般財源というのはそういう意味ですので、ですから、これについてどう加算があるのか、どう人員を配置しているかというのは、議論としてあまり意味がないというのは、結果としてこの国基準ベースに対して。","voiceIndex":78,"id":"exchange-045"},{"speaker":"南副委員長","kind":"質問・要望","question":"なければ質問したいと思いますけども、今飯沼委員が質問されていたことは、課長の見解で意味がないというのは、課長の角度の見解で、具体的にどうなっているのかという実態というか、例えば職員配置、そういうものがどうなっているのかという実態を見ていく必要があるということで質問されたと私は理解しているので。","respondent":"金子保育課長","answer":"これに対して、区としての保育士は５３２人いますので１３７人、区として加算の配置をしているというところの数字は意味があるというふうに考えています。","voiceIndex":80,"id":"exchange-046"},{"speaker":"南副委員長","kind":"質問・要望","question":"私も仕組みそのものがあまり理解されていない中での質問をしちゃったので、こういう数字しか教えていただけていないんだなというふうに思ったんですけども、保育園、直接私立の保育園に都から補助金というのはどこかの機構を通じて来るというふうに聞いているんですけれども、その辺のところを含めて教えていただきたいと思います。","respondent":"金子保育課長","answer":"このサービス推進費、改定したということで、私どもが聞いているのは５年間の経過措置を含めて実施しているものだというふうにお聞きしております。","voiceIndex":82,"id":"exchange-047"},{"speaker":"南副委員長","kind":"質問・要望","question":"その実施の状況をもう少し詳しく教えていただきたいというふうに思います。それと、区は承知をしていないという、直接経由していないので承知していないというお話なんですが、多分園長会等々でさまざまな話は出ているんじゃないかなと推測するんですけども、その辺では経営者の皆さんがどういうふうに感じていらっしゃるのか、どういう不安をお持ちなのか、承知している範囲で教えてください。","respondent":"金子保育課長","answer":"確かに今年の４月から実施になっています。私立の園長会には、私直接参加しているわけではないので、特にこれについては園長会からのご意見というのは伺ってはたしかいないと思います。","voiceIndex":84,"id":"exchange-048"},{"speaker":"南副委員長","kind":"質問","question":"公立保育園だけを掌握していればいいんでしょうか。やっぱり認可保育園ですから、それなりの責任は持たなきゃいけないというふうに思うんですね。だって、経営が破綻したらどうするんですか。そこに預けていらっしゃる子どもたちの保育そのものは全部公立保育園で吸収しようというふうに思っているんですか。あるいは、その辺について、一つそのことだけでも大変な問題だと思うんですよ。どうなんでしょうか。","respondent":"金子保育課長","answer":"このサービス推進費につきましては、たしか昨年の１１月だったかと思いますが、東京都から課長会に対して、東京都と東京都社会福祉協議会の間で交渉していて、これについては、言葉がちょっと適切かどうかわりませんが、妥結したというふうにお聞きしています。","voiceIndex":86,"id":"exchange-049"},{"speaker":"南副委員長","kind":"質問・要望","question":"そういう点で、人件費の部分の負担が、不安が大きくなって、そのことがどんなに経営努力されていても、経営そのものが支障を来して破綻してしまった場合には、やっぱりこれは品川区民にとっても、区の行政にとっても大きな損失ではないかなというふうに思うんですが、その辺の認識について伺いたいし、損失をさせないために、じゃあ品川区はどういうふうに、例えば東京都に向けて発言をするのか、求めるのか。","respondent":"小沼児童保健事業部長","answer":"と同時に、やはり、これは都区協議あるいは区のほうでもたしか区長会と議長会が一緒になって東京都のほうにいろんな形でたしか今５２％の財調枠の改定等を含めて申し入れしているさなかですから、一方では、そういうところでの論議も踏まえない限り。","voiceIndex":88,"id":"exchange-050"},{"speaker":"南副委員長","kind":"質問・要望","question":"ですから、この請願の審査については、午後のちょっと日程もありますけども、ちょっともう少し時間をかけて議論する、私はですよ、午後の時間が許せば、委員長のほうにお願いしたいと思うんですが、許せば、ここで採決をとるという形じゃなくて、ちょっと時間をとっていただければということをちょっとお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-051"},{"speaker":"築舘委員","kind":"質問・要望","question":"来年度は都加算に関しても改定する予定はないということもありますし、今意見書を出すということは、まだ決まってもいないことに対して意見書を出すこと自体がおかしいことなので、今採決していただいて、そして結論を出していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-052"},{"speaker":"嶋委員","kind":"質問・要望","question":"私も今皆さんいろんなご意見を聞かせていただきながら、いろんな意味で自助努力をしていかなくてはならない部分はいっぱいあるのかなと思いながらいますが、一応今回の請願項目は、意見書を上げてくださいですので、東京都が来年これを存続して継続していくということでお話がありましたので、採決をとっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-053"},{"speaker":"飯沼委員","kind":"質問・要望","question":"副委員長がまだ不十分。私立保育園の経営のところで、先ほど人件費補助の大幅削減の項目が１個ありましたけれども、このことですごく年間多いところでは５００万円ぐらい経営が大変に、困難に陥っているという話も私は伺っています。行政が先ほどご答弁ありましたけれども、議会のほうでぜひ区民の声として意見を上げていきたいな、届けたいなと思っていますので、採択ということでお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":95,"id":"exchange-054"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"築舘委員","kind":"意見","question":"介護予防のほうなんですが、これはこれからの今年度地域支援事業として行っていくわけですけれども、具体的な地域支援事業を創設するということで、１３地区に分けて今までどおりの形で、具体的なところとしてはどういうところを、場所としてはイメージをすればいいのかということをちょっとお聞かせください。","respondent":"早津高齢福祉課長","answer":"例えば、品川区においては、ふれあい健康塾ですとか、あるいはいきいき脳の健康教室というようなものがメニューとしては想定されるんではないかというふうに考えておりますが、これをどういう地区割でやっていくのかとか、そういうようなことについては。","voiceIndex":102,"id":"exchange-055"},{"speaker":"築舘委員","kind":"質問","question":"これからということでしょうから。介護予防に関しては、そういう意味では早目にやることによって、財政的にもかなり節約される部分も出てくるんじゃないかという話と、あまりどんどん増えてきて、逆に経費がかかり過ぎちゃうんじゃないのかという説もありますけど、予想といいますか、具体的にはどういった形で財政的な部分は考えていらっしゃるか、ちょっと教えてください。","respondent":"早津高齢福祉課長","answer":"財政の関係で言いますと、この予防にかかわるのが大きく先ほどの説明でもありましたけれども、二つあります。一つは、新予防給付と言われるものと、もう一つは先ほど委員お尋ねの地域支援事業、この二つです。","voiceIndex":104,"id":"exchange-056"},{"speaker":"本多委員","kind":"質問・要望","question":"資料３番目の介護予防についてなんですけれども、それぞれ制度の見直しというところで説明が書いてあるんですけれども、3)の新予防給付の中で、低栄養改善というところがあるんですけれども、それで、それの後で次のめくったところの新予防給付のイメージ案というところでも。","respondent":"早津高齢福祉課長","answer":"そのほかに、構想されていますのは、フットケアですとか口腔ケアですとか、幾つかの事業がありますけれども、あまりはっきりした回答でなくて申しわけないんですが、低栄養改善については、そのような指導というふうに理解しています。","voiceIndex":106,"id":"exchange-057"},{"speaker":"本多委員","kind":"質問","question":"その栄養改善と口腔ケアとどのように違うのかなと思って引き続きお聞かせいただこうと思っていたんですが、何となくわかりました。それで、これは新予防給付ということなんですが、当然介護を予防していくということでは、生活習慣のほうもある程度促していくんだと思うんですけれども、その辺が低栄養改善ですとか口腔ケアとか、その辺が重なっているというふうに受け取ればいいんでしょうか。","respondent":"早津高齢福祉課長","answer":"そういう意味では、生活習慣の改善、これは先ほどの低栄養改善なども従来から老健事業の中で取り組まれていたわけですが、これを介護予防という観点から新たに一貫した考えの中で取り組んでいくべきではないかと。","voiceIndex":108,"id":"exchange-058"},{"speaker":"飯沼委員","kind":"意見","question":"今のところの続きなんですが、いま一つ、今までの現状がよくわからないので、何か先ほどの説明だと、地域支援事業も新予防給付の創設、どちらも保険が５０％と、あと税のほうとということなんですけども、すごく単純なんですが、よくわからないんで、今やっているところの、例えば税でやっていたり、介護でやっているのが。","respondent":"早津高齢福祉課長","answer":"この市町村事業、地域支援事業についても、今度は介護保険の制度内に位置づけることによって、財源としても公費全面ではなくて、先ほどと同じように公費半分、保険料半分と、こういう財源構成にしていくと、こういった考え方です。","voiceIndex":110,"id":"exchange-059"},{"speaker":"飯沼委員","kind":"質問","question":"というと、新予防給付、この右のところから切り離されて、左に寄ってきたところのことなんですが、この中身的には、例えば要支援の方の今受けられているホームヘルプサービスとか、デイサービスとか、そういった今受けられている部分に関しては、引き続きここで行われると受けとめていいのかが１点と、もう一つは、保険料のところで５０％、税で５０％というところでは。","respondent":"早津高齢福祉課長","answer":"ホームヘルプの関係では、いろいろと議論あるところですが、少なくても一律に廃止をする、やめるということはないんだというふうに言われております。それから、新しい財源構成になれば、保険料へのはね返りがあるんではないかということですが、先ほど説明したとおりです。","voiceIndex":112,"id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問","question":"先ほど伺ったのは、新予防給付のところと、地域支援事業の、両方５０％、５０％というお答えだったんで、その辺が新しく保険のほうからの持ち出しが増えるのかという意味でお伺いしたんですが。","respondent":"早津高齢福祉課長","answer":"基本的にはそういうことですが、増やさないようにするというのがまた一方で大事なことではないかというふうに考えております。","voiceIndex":114,"id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問・要望","question":"増やさないようにする、ちょっと微妙なお答えだったんですが、増える部分もあるのでしょうか。上は個室なんで現在ないというか、使っていなんですが、この辺がなぜ負担割合が減っているのかなというところと、この辺が介護報酬のほうに影響するのかどうか、その辺を１点お伺いしたいと思います。","respondent":"高橋介護保険担当課長","answer":"新第４段階から第６段階までの多床室、現行と見直し後の１割負担の部分ですが、現行の施設利用サービスの中には、今まで光熱水費分が入っていまして、見直し後はその部分が外出しになるということで、その部分、１割負担が１,０００円で１万円の負担になったと。","voiceIndex":116,"id":"exchange-062"},{"speaker":"飯沼委員","kind":"意見","question":"もう一つ、特別養護老人ホームに今現在入所していらっしゃる低所得者の方々の激変緩和のところの３％、６％になって、今度１０％になる部分のこの方たちが、こういった状況になって支払えないというか、負担が増す問題のところで、どういう状況になるのか。","respondent":"早津高齢福祉課長","answer":"特別養護老人ホームに措置自体、介護保険が始まる前から入っていた方に一定の減額制度というものがつくられております。それが終了するのが、今年度いっぱいですが、食費等につきましても、所得に応じて３段階あるいはもう少し安くしていた方もいらっしゃるわけです。","voiceIndex":118,"id":"exchange-063"},{"speaker":"飯沼委員","kind":"質問","question":"ということは、新しく居住費用と食費の見直しが入っても、低所得者の新しい対策のところでは、それほど変わりのない状況で暮らせるという受けとめ方でよろしいのでしょうか。","respondent":"早津高齢福祉課長、新美福祉高齢事業部長","answer":"ただ、時限を限られた制度でもありますし、こういう形で低所得者に対する軽減措置が従来以上にきめ細かくつくられるという中でご理解をいただきたいというふうに考えているところです。それに対して、新第３段階にどの程度の方がいらっしゃるか、これはちょっと区分してみないとわかりませんが、その方が若干増えるということになりますが、そういう意味では、先ほどから高齢福祉課長が申し上げているように。","voiceIndex":120,"id":"exchange-064"},{"speaker":"本間委員","kind":"質問","question":"平成１２年に始められた介護保険制度なんですけど、５年後の見直しということで大きな段階をまた迎えているわけですね。そして、見直しの具体的な方向がいろいろ出てきておりましたが、大変細かいところまで及んだりしている部分をお聞きしております。まだまだ試算の段階でというふうな話はあろうかと思いますが、その辺についてのご見解はいかがでしょうか。","respondent":"高橋介護保険担当課長","answer":"資料のほうの保険料のほうの図のほうを見ていただければ、今後の考え方、品川区の現行ということで改正後を見ますとですが、今回保険料の第２段階が二つに分かれるというところで、制度改正後の構成比のほうを見ていただきますと、資料１の裏面で。","voiceIndex":123,"id":"exchange-065"},{"speaker":"本間委員","kind":"質問","question":"その辺を今の段階でどうのこうのというのは、非常に早計に過ぎるかもしれませんけども、必ずや受けて立つ自治体としての品川区がこれまでの高いレベルの水準を保ちつつ、今までの料金でいいよというような形になるのかどうかというふうな部分が知りたかったわけで、今の段階ではっきりとした答えにはならないかもしれませんけども、およそ聞く段階では、何とかその方向でということで理解してよろしいですか。","respondent":"新美福祉高齢事業部長","answer":"具体的に、じゃあどの程度かとか、給付費用はどの程度か、先ほどの予防給付にいたしましても、要支援、要介護１の方にどのように新予防給付を用意したり、給付したり、あるいは地域支援事業をどういうふうにするのか、これはまだまだ来年度が検討の時期ということで。","voiceIndex":125,"id":"exchange-066"},{"speaker":"嶋委員","kind":"質問・要望","question":"私は資料２のほうの先ほど施設入所のお話をお聞きしたんですが、一応在宅介護で一番皆さん喜ばれているショートステイなんですが、これに関しての今回の居住費用、光熱水費、それから居住費用では、これは施設入所なので減価償却になってくると思うんですが、ショートステイでは、ちょっと具体的なものがもしあればお聞きしたいことと、それとあと、減価償却となると、施設の建物の耐用年数とか築年数とか。","respondent":"高橋介護保険担当課長、早津高齢福祉課長","answer":"ショートステイの居住費用等についてのものですが、資料２のほうの基本的な考え方の中で、白丸２のほうで、現行の介護保険三施設、ショートステイを含むとなっていますので、保険給付の対象となっている居住費用。これは全国的に見れば、社会福祉法人がそれぞれ別にやっておりますので、それぞれの施設が定めることになるわけですが、品川区の場合は品川区と社会福祉法人とのパートナーシップがありますので、品川区として全体的なものが。","voiceIndex":127,"id":"exchange-067"},{"speaker":"嶋委員","kind":"意見","question":"ショートステイが居住費用、食費が別になることはここに書かれているのでわかります。それなので、具体的にどのぐらいの金額的なものというのは、ちょっと大体とかというのも、全然わかりませんか。","respondent":"新美福祉高齢事業部長","answer":"個室というのは処遇上必要なことでご本人の希望だけで、選択による個室利用ではないというのが基本的な考え方ですので、そういうふうに区分いただきたいと思います。","voiceIndex":130,"id":"exchange-068"},{"speaker":"築舘委員","kind":"意見","question":"資料３のところで、介護予防についてということで、一つの新予防給付ということのあれで、低栄養改善というのがあるんですけど、これを具体的にどういうようなことをイメージしていったらいいのかというのが一つと、それから、予防給付に関することで、筋力向上トレーニングをはじめ、身体的な部分の予防というのはかなり出ているんですけど。","respondent":"早津高齢福祉課長","answer":"低栄養改善についてですけれども、先ほども若干ご説明しましたけれども、個人ごとにタンパク質が不足しているとか、鉄分が不足しているというふうなことをやるんだと思うんですが、実はこれは具体的なところは、私どもまだはっきりしておりません。","voiceIndex":132,"id":"exchange-069"},{"speaker":"南副委員長","kind":"提案","question":"皆さんの質疑を聞いていて改めてなんですが、新しく新第２段階というのを設けたというところなんですけど、ここには先ほど説明があったように、年金収入が８０万円以下であって、それ以外の所得がない者、あと税金が非課税だと、こういう方、今までは含んでいたけども、今度は収入によって１５％と２０％の割合で、割合でというか、たまたま分けたらそういう割合でいらして。","respondent":"新美福祉高齢事業部長","answer":"第２段階についての認識ですが、品川区としても満額徴収になった時点で品川区独自の低所得者対策をこうなったということにおいて、先ほど申し上げたように、高齢者の中に収入が大変少なくても生活保護を受けないでつましく暮らしていらっしゃる方が。","voiceIndex":134,"id":"exchange-070"},{"speaker":"南副委員長","kind":"質問","question":"そうしまして、資料２のところの裏面のそれぞれの費用負担のところをちょっと見ると、先ほどの説明では、例えば低所得者のところで高額介護サービス費、あるいは低所得者への配慮を入れて、負担が遜色ないような、今までの負担とそんなに大きく変わらないようなところに配慮したんだという説明で、数字的に見てもこの範囲ではなるほどなと、そのとおりだなというふうに伺っていたんですが、しかし。","respondent":"早津高齢福祉課長","answer":"３万円の増というのは、負担増だですが、施設入所の方に光熱水費ですとか食費というものをもう少しいただこうということは、冒頭のご説明でもいたしましたけれども、二つの観点ですね、一つは年金給付とそれから介護給付に重なりがある、年金の中にも居住費が出ているし。","voiceIndex":136,"id":"exchange-071"},{"speaker":"南副委員長","kind":"質問・要望","question":"そういう部分がどこまで国のところで検討されたかというのは、ちょっと細かくつかんでいないのであれなんですが、一律的に家庭にいる人との比較で導入するというやり方というのは、何となく安直じゃないかなというふうに思うので、生活の実態だとか、さまざまな状況、社会状況とかを見たときに、やっぱりもう少し配慮があってしかるべきだというふうに思うし。","respondent":"早津高齢福祉課長","answer":"残った４割も、ちょっと今記憶が、資料がぱっと出ないんですけれども、わからないとか、どちらでもよいという方がかなりの数でございまして、この方針に明確に反対だという方は極めて少なかったように記憶しております。","voiceIndex":138,"id":"exchange-072"},{"speaker":"南副委員長","kind":"質問","question":"だから、そういう説明であれば、ちょっと不思議だなというふうに私としては思って伺いました。いずれにしても、これからこういう部分も含んで払っていく中で、サービスが提供されていくということですから、具体的な実態、状況、推移をちょっと見守っていきたいというふうに思って、それで終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":140,"id":"exchange-073"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２点ちょっとお伺いしたいんですが、前回のときに障害者施策のところで支援費との統合のところで、両論併記になっていた部分がその後どうなっているのかが１点と、あと、厳しい介護保険の財政というか、持続可能な制度にしていくためには、国の負担の部分を増やしていく、このことが重要ではないかなと思っているんですが、昨年の１０月に全国市長会の中で意見が出されていました。","respondent":"早津高齢福祉課長","answer":"これについては、市長会として要望したというふうには聞いてありますが、今回の見直しの中には、どうやら俎上には上らなかったです。やむを得ないことかなというような感じがいたしますが。私が言うべきことではありませんが、今回は見送られたというふうに理解しております。","voiceIndex":141,"id":"exchange-074"},{"speaker":"飯沼委員","kind":"質問","question":"支援費のところとの統合に関しては、正式ではないけれども、今回見送られるのでは、その辺、いつごろになったらはっきりするのか、その辺を聞かせてほしいのと、先ほどの国庫負担金とか、調整交付金、この辺のもっと国が負担すべきじゃないかというところは、どういう扱いになるのかというのも大事ですけども、区としての姿勢がどうなのかなというところを一つお伺いします。","respondent":"新美福祉高齢事業部長","answer":"１点目の被保険者の範囲拡大と障害者への適用の問題ですが、これは当初介護保険部会１１月末にこのことについて結論を得るというような予定になっておりましたが。","voiceIndex":143,"id":"exchange-075"},{"speaker":"南副委員長","kind":"提案","question":"ちょっと私もうまくこの部分をまとめきれていないんですが、午前中の質疑の中で、同じように負担軽減をさせていく、公立の認可保育園の保険料負担を軽減させていくという立場で条例改正提案をさせていただいたんですが、そこでも言えるように、やっぱり父母の皆さんが少なからず経済的支援を求めていらっしゃるという、そういうところで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":147,"id":"exchange-076"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3096#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":61722,"voices":150}},{"id":"h16-20041129-8","meetingId":"h16-cm11","date":"2004年11月29日","dateIso":"2004-11-29","committee":"建設委員会","time":"午前１０時０６分～午後３時２７分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成１５年請願第２２号、（仮称）品川区上大崎二丁目計画再開発プロジェクトに関する請願","agenda":"平成１５年請願第２２号、（仮称）品川区上大崎二丁目計画再開発プロジェクトに関する請願","exchanges":[{"speaker":"林（和）委員","kind":"質問","question":"そして委員会でお諮りをしましたところ、本来ならば前期の委員会で結論を出す予定でいたわけですけれども、そういうことであれば、少し様子を見ようじゃないかということになってきておるわけです。それから、これの工事協定というのはどういうふうになっているんですか。","respondent":"浜脇住環境整備課長","answer":"途中では工事協定を結ぼうということでやっていたわけですけれども、まとまらなくて工事協定を結ばないままに工事をしたというふうに聞いております。","voiceIndex":7,"id":"exchange-001"},{"speaker":"林（和）委員","kind":"質問","question":"そうしますと、住民の方々は工事を進めてもいいという容認を、暗黙のうちに認めていたわけですかね。それで、この建築は来年１７年５月に完成の予定になっていますよね。もうほとんどでき上がっちゃっているわけですよ。ですから、もうやはりここら辺で結論を出すべきだと私は思いますけれどもね。","respondent":"浜脇住環境整備課長","answer":"そういった意味では外構的な意味で、出入り口の問題と、それから若干騒音が発生するんじゃないかということで、防音壁といいますか、音を遮るような措置をしてくれないかという話があって、それがちょうど北側のほうの建物の変更図面を見てもらえば。","voiceIndex":9,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"請願の中の汚染土壌については入れ替えをしたということで確認させていただいていいのだろうか、それが１点と、それから、ここのところで井戸水の水量、水質検査を実施するようというふうなことを書いてあるんですけれども、ここのところはされたのかどうかといった部分を。","respondent":"浜脇住環境整備課長","answer":"悪いほうは出した。それから、井戸水については、その後どんなふうな対策をとったかというのは私どものほうでは、この議事録というんですか、その打ち合わせの内容の上では入ってございません。要するにつかんでございません。","voiceIndex":11,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"井戸がある軒数が何軒ぐらいあるかというふうなことがわかったら教えてもらいたいのと、それから今一番ネックになっているのは、西側の通路は使わせないという住民側と、そこの折り合いがつかないというふうなところだと思うんですけれども、東側のほうの道路については警察のほうからは東側から出入りをするというところでは、警察のほうからは許可が出ないということになっているのかどうか。","respondent":"浜脇住環境整備課長","answer":"警察との関係ですけれども、警察の中では一使用者のためのいろんな仕かけをして都道に信号機設置等安全策をとるというのは適切ではないということなので、常設的なというのは不可能だと。やっぱり両方使うような感じで回答をしたと。打ち合わせはそうだということです。","voiceIndex":13,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういうところでは、あそこは都道になるんですよね。あそこの都道のほうは警察のほうでは無理だというふうなことで、住民のほうは西側は使ってほしくないというふうなことで、ここら辺のところというのは、建物を計画した時点でどうなるのかというところでの事前協議のところでは、そういうふうなところは問題にならないんでしょうか。","respondent":"浜脇住環境整備課長","answer":"それで、私どもとしては、それはどちらを使いなさいということを指導するような立場ではございません。やっぱり道路があれば、道路は両方ともどっちとも使えるというふうに考えます。","voiceIndex":15,"id":"exchange-005"},{"speaker":"高星委員","kind":"質問・要望","question":"この１カ月間、そういうやり方をしてきているというふうな状況だそうです。そんなことで、私はいきなり扱いにするのも変な話なんですけれども、先ほど言いましたように、今最終段階にまさしく差しかかっているというような状況なんだそうでございまして、先ほど言った東宝からの回答を待っていただきたいということで、もう少しの間継続していただければありがたいのかな、こんなふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-006"},{"speaker":"高星委員","kind":"質問","question":"そうですね。事前協議の、そういった課題が心配されるときに、そういうことをきちんとした指導ができないのか。だから先ほどほかの方の質問に対しても答えていましたけれども、一般的によくある話だというような言い方だけれども、それじゃやっぱり無責任だろう。こんなふうに思います。その辺の考え方をひとつ。","respondent":"浜脇住環境整備課長","answer":"そういった状況です。ですから、開発協議の関係ですけれども、開発協議の関係は、この敷地に対することをやるのであって、道路計画までをうちのほうが広範囲にわたって計画を持ってこいということはこれまで１回も指導してきたことはございません。","voiceIndex":19,"id":"exchange-007"},{"speaker":"高星委員","kind":"意見","question":"やったことがないんだと、直接建物に対することはやるけれども、取り付けの関係というのはこれはやったことがないんだという、行政としてそれでいいのかどうか、結果として、今も遅かれ早かれ、遅かれというのか、住環境のことをあちこちいろいろと法律上で騒ぎも始めているわけだけれども、行政のあるべき姿ってそれでいいのかなという気がする。","respondent":"岩田管理工事課長","answer":"それで、今回のケースは、私どものほうに具体的に事前にそういう相談が来たかどうかは、ちょっと今ここで即答はできないですけれども、持ち帰って当時の資料を調べてみたいと思います。","voiceIndex":21,"id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"今回の話し合いですか、建築紛争が始まってからの話し合いが住民とほんとうにこれだけよく建築主が対応したのが、また譲歩のほうも一部を除いて、一部を入れますと１０階建て、それが８階建てということで、ここまで譲歩したということは、かなり誠意としては見られるんではないか。それをそこへ建てた。やはり、どなたでも建物を建てる権利はある。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今、高星委員の話を聞いていましたら、初めのときはこの建築主のほうが西側の道路は使わないで東側で行くというふうなことで説明していたということなんですけれども、そこら辺のところはじゃあ建築主の対応ですか、ここはちゃんとした担保もないままそういう説明というのをしていたというふうなことなんでしょうか。そこら辺のところをわかったら教えてください。","respondent":"浜脇住環境整備課長","answer":"お手元に行っています資料の中に変更前というほうの２ページ目にありますけれども、当初からこの計画上は、西側のほうも使うような状況で説明をしている図面です。","voiceIndex":24,"id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうふうなところをきちんと誠意を持った近隣住民への、特にこういうふうな民地のところも含めて利用させていただかざるを得ないという、こういう計画であれば、そういう誠実な対応というのがほんとうに求められたんだと思うんですけれども、そこら辺のところが、この請願の中では繰り返し繰り返しきちんと説明もされないし、誠実な対応ではないというふうな言葉が出てくるんですけれども。","respondent":"浜脇住環境整備課長","answer":"そのときにそういうような話が、住民に不誠実な対応をしたとは言いませんけれども、住民から見れば、そういう言葉遣いとか態度があったかもしれませんけれども、それはいろんな方もいらっしゃいますから、どういうふうにとられたかの問題なんですけれども、ただ。","voiceIndex":26,"id":"exchange-011"},{"speaker":"三上委員","kind":"意見","question":"もともと、先ほど高星委員がちょっと言っていた話で、私がちょっと聞き違えたらあれなんですけれども、過去、撮影所の車の出入りというのは、主に２カ所、もともと出入り口というのは２カ所あったのかどうか。１カ所であったのか、２カ所であったのか、そこのところはどういう車の流れというのは行われていたのか、そこのところはどうなっているか、ちょっとご説明いただけませんか。","respondent":"浜脇住環境整備課長","answer":"ですから、西側のほうに大きな道具が入ったというんですけれども、東宝の。何か立ち入りに関する道路が。そういったことですから、私があそこだと今まで思ってずっととらえておりまして、ほんとうに西側から物を出し入れしたかというのはつかんでございません。","voiceIndex":28,"id":"exchange-012"},{"speaker":"三上委員","kind":"質問","question":"ちょっと申しわけないんですが、紹介議員である高星委員に、そこらあたりがおわかりになったら教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-013"},{"speaker":"高星委員","kind":"質問","question":"私は五反田には３５年いるんだけれども、あそこから出入りしているのは大きいトラック、今言われたところの中にありましたように、大道具を運び込むようなときのトラックのやったのを１度、２度見たことがあります。ほとんど出入りは見たことがないんです。ですから、あとは後ろのほうから出入りしたかというのは、ちょっとあまり見ていないんだけれども、そんなような状況だというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-014"},{"speaker":"三上委員","kind":"質問・要望","question":"それを一度確認を私はしていただきたい。過去の歴史の中でそれがどうなっていたのか。ですから、そこらあたりをもう少し業者にどのように、もうここまで、あそこまで階高がちょっと条件を変えられてきているわけですから、そこのところでもう少し、この本来であれば、私は今日こういうようなことであれば、今後、請願、これはもう取り下げというような話になってきたっていいかもわからない。","respondent":"浜脇住環境整備課長","answer":"それで、やはり建主側から見れば、都道側から入るだけなのか、西側も使っていいのかというのは住む側の人に説明をする義務もありますので、それはもう早晩に結論を出す。","voiceIndex":32,"id":"exchange-015"},{"speaker":"高星委員","kind":"質問・要望","question":"ここに来て、住民の方々も先ほど、視察の中でもちょっと話したわけですが、民地の部分、ありましたけれども、あの部分に養生囲いをつくっちゃうというような、内部でこういう話も出ているんだ。ですから、状況としてはほとんど上り詰めてきているのかなというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-016"},{"speaker":"林（和）委員","kind":"意見","question":"というのは、その前が夏休みに入っていたから、これがずれ込んだんじゃないかなと思うんですけれども、この請願を書いたのが５月か６月のころじゃないかなと思うんですけれども、そのために説明会その他のことがずれ込んできて、こういうふうな結果になったのだというふうに思うわけですけれども、その時点から、もう我が党のほうでは早くこの結論を出してあげたいということで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":37,"id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私も、今話し合いを進めているということですし、今の三上委員のほうの質問に対しても的確なものもわかっていないという状況の中で継続にしていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-018"},{"speaker":"須貝委員","kind":"質問","question":"ただし、道路のところに主眼が移っているというわけですから、道路はちょっと今回の建築紛争の私は主旨とはいささか離れたという感じがしますので、入っているんですけれども、主眼は私はそれに対する我々建築紛争の場合には、日照、風害、電波障害、そういうことがやはり一番大切なことで、区道に対して一般の区民がそこを使えなくなるというのは、私はそれに対して話し合いを待つというのは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-019"}]},{"id":"topic-02","title":"平成１６年請願第３号、戸越１丁目１７番高層ワンルームマンション建築に関する請願","agenda":"平成１６年請願第３号、戸越１丁目１７番高層ワンルームマンション建築に関する請願","exchanges":[{"speaker":"林（和）委員","kind":"質問・要望","question":"前回の委員会において、これは裁判中ということで、様子を見るということで継続になっております。それで、今の説明を聞きますと、これは裁判は却下されたということでございまして、その後、今のお話では工事協定も結ばれたですので、大体目安がついてきたというふうに思いますので、結論を出していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-020"},{"speaker":"須貝委員","kind":"質問","question":"ちょっとお聞きしたいんですけれども、裁判の中身というのはどういうものだったのか、今回の建築紛争とかかわっている、何かそういう裁判だったのか。それから第２点が、双方、地元の方初め、まだちょっと話し合い、継続として話し合いの余地がまだ残っているのかどうか。","respondent":"浜脇住環境整備課長","answer":"私どもとすれば、工事協定が結ばれて工事をやっているのですけれども、まだ代表の方、何人かとのお話し合いが、何人かがご署名なさって、そういった運動をしているということですが、なかなか全員の方がこれでもって解決したというふうな形で。","voiceIndex":49,"id":"exchange-021"},{"speaker":"須貝委員","kind":"質問","question":"その方向性として、和解のほうは我々詳しくはまだわからないんですけれども、かなり進む方向で進んでいて、それで、もうちょっとで終わるんでしょうか。それともまだ長期にわたるような可能性があるんですか、そこをちょっと個人的なあれで結構ですが。","respondent":"浜脇住環境整備課長","answer":"ただ、先ほど申しましたように、一応請願についての見解については、建主のほうは見解を話したというふうになってございまして、そういうところはどのように交渉されたのかということは、議事録上は出てきていませんので。","voiceIndex":51,"id":"exchange-022"},{"speaker":"須貝委員","kind":"質問","question":"もう１回だけすみません、そうすると、今建築主と代表者の方は、今、請願者が話し合いとして、建築主のほうに投げかけはしているんですか。まだそれは正確に来ないということですね。","respondent":"浜脇住環境整備課長","answer":"こういうことを言っていいか、ずっと私どもとは違ったところで、いわば先ほどの言ったように何回何々をやったというような議事録が出せる部分と、議事録ではなくて個人的に調停といいますか、そういったものがあるのかもしれませんが。","voiceIndex":53,"id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"先ほど店舗のほうはできないけれども、４項目についてはオーケーだというのは、４項目というのは、この請願に出されている項目というふうなことじゃなくて、商店街のほうから出された４項目ということなんですか。それともう一つ、ちょっとここはワンルーム形式ということなんですけれども、戸数は何戸あるのか、ちょっと教えていただけますでしょうか。","respondent":"浜脇住環境整備課長","answer":"商店街のほうから出された要望に対しては、先ほどの私が冒頭計画の中で説明したことは、あれは請願者に対する請願に対する答えが欲しいということであって、それから後から言ったのは商店街から出た内容について一致する項目があったと。","voiceIndex":55,"id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"さっき視察をしたときに、ご近所の方からいろいろと騒音や振動も大変だし、また隣の建物との間隔が５０cmぐらいしかなくてすごい大変だというふうな話をお店の方がされていたんですけれども、ここの請願主旨のところにも安全ネットの設置とかあるんですけれども、そこら辺のところで、防音壁ですか、後ろ側はしてあるけれども、両脇に防音壁というふうなのがされていないというふうなところで、騒音も。","respondent":"浜脇住環境整備課長","answer":"先ほどの経過の中で説明をしましたんですけれども、防風壁については植栽とか部屋の手すりで対応するように説明をいたしましたということで、安全ネットについては隣地との間隔が狭いので、そういう意味がないでしょうということをお話ししています。","voiceIndex":57,"id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そこのところの間隔をあけてほしいというのが、あけて避難のときに、今は通れているそうなんですね。騒音、振動が今工事をやられているということで、すごく大変で防音壁をやってほしいのにやってくれないというふうなことをおっしゃっていたんですけれども、そこら辺のところがどうなっているのかというところを教えてください。","respondent":"浜脇住環境整備課長","answer":"たまたま今日そういう話があったんですけれども、その方が今工事をめぐって言ったという話で、そういう苦情は、私の耳には聞いてございませんので、ちゃんといらっしゃれば、またそれなりにこういうご迷惑をかけていて。","voiceIndex":59,"id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうふうなところで、ぜひ住民の方から指導をしてほしいということで要望があって、指導していただける分には、今もおっしゃっていただきましたけれども、ぜひ業者のほうに誠意を持った対応でないというところが地域の方からの声としてかなりの方から出ていましたので、そういう誠意を持ったできる限りの対応をしていくようにというご指導をしていただきたいなというふうに思います。","respondent":"浜脇住環境整備課長","answer":"工事でありますから、そういった意味では、近隣と、そういった振動等、そういったものがあるわけで、やはり十分注意してやるように、改めて私どものほうから今日そういうご意見があったということで、建築主のほうには要望があったと。","voiceIndex":63,"id":"exchange-027"},{"speaker":"三上委員","kind":"質問・要望","question":"当初４０ｍだったのを３０までですか、３１ｍ、１０ｍぐらい下げたというようなことは、それは説明でわかったわけですけれども、もう一つ、太陽採光システムの導入、こういうことが住民の皆さんは要求をされているわけですけれども、この仕組みについてはどういうふうにこの当事者間では、こういうことを要求しているんだ、それについてはこうなんだという、それが具体的にちょっとわからないんですけれども。","respondent":"浜脇住環境整備課長","answer":"太陽採光システムというのは今後いろいろな形というか、あるそうで、形とかいろんな関連があるそうですけれども、なかなか一般的にはなっていないというのがあるようなことでして、今回は予算というふうなことでできないそうだというふうな話です。","voiceIndex":65,"id":"exchange-028"},{"speaker":"三上委員","kind":"質問・要望","question":"やりとりがどうあるのか。防風壁という。３番目については隣の建物との間隔をあけろということですから、これは多少なりともどうあけるかというものの間隔の問題でしかありませんので、これは当事者間で話し合って、これはお互いに納得する話しかないかもわかりませんが、この１番目、２番目というのは高さを別として、ちょっとほかの要件というのはわからないんですけれども、もう少しお知らせいただきたい。","respondent":"浜脇住環境整備課長","answer":"私ども、請願があった後、こっちの代表の方とお会いして、この辺を聞いたんですが、この方もあまり、建築的には初めてこういうことをやったんで、必ずしも説明が私のほうはどういうことを要求している、こんなことだということはありませんでした。","voiceIndex":67,"id":"exchange-029"},{"speaker":"三上委員","kind":"質問","question":"話し合ったということであれば話し合ったなりに、どういう回答があったのか、それが説明できれば、それが進んでいるんですよ、もう少し技術的な部分でお金の関係もあるから、それについてもう少し詰めているんですというのであれば、それはそれの説明にはなるかもわかりませんが、そうでない限り、ちょっとこれについてはどうなっているかというのは非常に曖昧で。","respondent":"浜脇住環境整備課長","answer":"私どものほうも代表の方から１回そういう相談があって、こういう請願をしているんだということで、これをどういうふうにとらえたらいいかということでありましたので、一般論として説明しました。","voiceIndex":69,"id":"exchange-030"},{"speaker":"三上委員","kind":"質問・要望","question":"改めて途中であるという課長の答弁ですから、またそれについて確認をして、この委員会にご報告をいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-031"},{"speaker":"高星委員","kind":"質問","question":"ただ、先ほどの三上委員もおっしゃっていましたけれども、現況、見切り工事に入っちゃっていて、重機も動いていたけれども、近隣の商店ですか、ほんとうに壁もろ出しになって工事をやっていて、非常に後ろのアパートのほうも、アパートがあるんだけれども、うるさくてしようがないんだというような愚痴をこぼしたりしておりましたけれども、ああいうのを現実に目の当たりに見て。","respondent":"片田建築課長","answer":"ただ、工事をやる上でも、当然今地下とか杭とかやっていく中で、立ち上がると同時に周辺への防護壁とか通常そういうことをやるような動きも行うわけですが、その辺も含めて一応確認して、それについてはきちっと指導していきたいということで考えてあります。","voiceIndex":72,"id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"普通このマンション建設の説明のときには大体自前のところに平面図で、ここにこんな大きな木を植えて、小さい木を植えるというような、大体説明会のときに資料として出されるんですが、ここには全然そういうふうなのが、植栽に関しての記述が全然ないんですけれども、地域の方に聞いても、そういう緑をどういうふうにしていくのかというふうな話は一切説明がないというんですけれども、区のほうで、その植栽。","respondent":"浜脇住環境整備課長","answer":"こういうふうに回答をしたということでございまして、それに対して住民がじゃあそれではどうだろう云々かんぬんということは、そういうのも議事録になってうちのほうに来ていませんので、その辺のほうはちょっとつかみかねるです。","voiceIndex":74,"id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ここの中高層建築の開発指導要綱の中でも、緑の部分では緑化の促進というところでありますよね。この緑の条例に基づいてということで。そういうところでは、品川区に対しても緑の計画というふうなのはこういう場合に出すんじゃないんでしょうか。","respondent":"浜脇住環境整備課長","answer":"通常、住民のほうから見ればこういう工夫をしてください、ああやってくださいと言ったわけですから、それに対してどういうふうにやったかというのは、新たな図面はうちのほうは持っていないといいますか、または置いていないというふうになります。","voiceIndex":76,"id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"じゃあ、それに対して新しく変更したというふうなところがわかる、そういう図面というのも区としても出されてくるわけですよね。これから。そこら辺のところがどうなっているかということと、それから、住民の方にはそういうふうな説明が一切ないということなので、そこら辺のところもぜひ説明をするようなご指導もお願いしたいなと思うんです。","respondent":"浜脇住環境整備課長","answer":"植栽については今言ったような、これまでの説明のほかはないですけれども、その私どものほうは、住民とやったことに対して説明したり、差し上げたりした、それを提出してもらうものであって、うちのほうにこういうふうにしてください。","voiceIndex":78,"id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この第２章の生活環境に９条で緑化の促進というふうなことでありますよね。ここのところで、緑をこういうふうに植栽でやっていきますよというふうなのは、区のほうには提出するんじゃないんですか。","respondent":"松代道路公園課長","answer":"建築をする際に、今委員からのご質問にありましたように、緑化に関することは緑化計画書ということで、私どものところに提出されて一定の計画について、まず計画を見て、必要な数量等の部分に達しているかどうか、あとは内容等を私どもで見まして。","voiceIndex":82,"id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"わかりました。住民のほうからぜひそういうふうなものを説明してもらいたいということを事業者のほうに言って、それでも説明しなかったら指導していただくということはできるというふうなことですよね。わかりました。","respondent":"浜脇住環境整備課長","answer":"その一環として、やっぱり植栽についてもあるいはそういった風をやわらげる方法として、植栽やバルコニーのところや手すりをつけるというようなことがあるんですが、それで、もし私どもに最初に計画したものと違ってあれば、これは住民に説明をして。","voiceIndex":86,"id":"exchange-037"},{"speaker":"三上委員","kind":"確認","question":"私は先ほど質問をいたしました答弁の部分が確認されていない以上は、本日のところは継続でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-038"},{"speaker":"高星委員","kind":"質問","question":"私は先ほど同じように質問をしたわけですけれども、植栽だったというようなところで２階の屋上になっちゃうのかなと思ったり、いろいろ考えるわけですけれども、請願というのは、地域住民から出るのが当たり前の話でして、基本的に例えばそこでかかわるいろいろな意味の建設にかかわって被害を受ける方々が、いろんなことで困るというような思いを請願として出しているわけで、そこで例えば、2)の防風壁。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-039"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"私はこのもともとの計画が戸越銀座商店街という中で１階に店舗も設けずに、しかもあそこはほとんど２０ｍ以下のビルしかないところにそれよりもはるかに高い、半分以上の１０ｍを超えたような建物を建ててなおかつ地域の方にかなりの迷惑をかけながら、それに対してもしっかりとした対応がとられていないというふうなところでは、今日、ぜひ採択ということで結論を出していきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":91,"id":"exchange-040"},{"speaker":"須貝委員","kind":"質問・要望","question":"先ほどもちょっとお聞きしたんですけれども、まだ住民の意向がはっきり住環境整備課のほうに来ていないということでそこをよく見て判断したいと思います。今日裏のほうを回りましたら建築紛争という建築反対ということで出ていましたので、ちょっと今回は継続にさせていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3802#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":36016,"voices":97}},{"id":"h16-20041129-9","meetingId":"h16-cm11","date":"2004年11月29日","dateIso":"2004-11-29","committee":"文教委員会","time":"午前１０時０６分～午後３時４７分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を90件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成１６年請願第２２号、学校事務職員・栄養職員を含む教職員の給与費半額国庫負担などの「義務教育国庫負担制度の堅持」を求める","agenda":"平成１６年請願第２２号、学校事務職員・栄養職員を含む教職員の給与費半額国庫負担などの「義務教育国庫負担制度の堅持」を求める","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"全日本私立幼稚園連合会も、「子どもたちが生まれながらに持っている等しく教育を受ける権利を奪わないでください」という意見広告を出しまして、今、ほんとうに全国さまざまな立場の団体から、何としてもこれは削減しないでほしい、堅持してほしいという声が上がっています。東京２３区の教育長会や校長会のほうでは、都の国のほうに、今どういった動きといいますか、働きかけが始まっているのか。","respondent":"市川庶務課長","answer":"お尋ねの件ですけれども、今現在、国におきまして、政府と与党間の方針が決められたです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"もちろん品川区の教育委員会は品川区に責任を置いていますけれども、この問題に関しては、やっぱり、今、全国の教育水準にかかわる大事な問題ですから、今後、時期を見ながらでも、言うべきところで、都、そして国に対して、この制度を維持するよう求めるべきじゃないかなと思うんですけれども、その辺の見解を教えていただければと思います。","respondent":"市川庶務課長","answer":"前回、９月の文教委員会で、これまでのさまざまな動きについてご説明申し上げた中で、本年８月に中央教育審議会から、義務教育費に係る経費負担のあり方ということで、いわゆる中間報告が出されてあります。","voiceIndex":7,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"どの家庭に生まれても、どの場所に生まれても、きちんと教育を受けられることが大前提でなければならないと思うんです。若月教育長は中央教育審議会のメンバーでもありますけれども、ぜひ、教育長のご見解を伺いたいんです。今回、行われたら、教育水準にばらつきが生まれるかと思うんですけれども、率直なところで結構ですけれども、ぜひ、教育長、最後に一言ご見解を教えていただければと思います。","respondent":"市川庶務課長","answer":"私から説明申し上げますけれども、先ほど申し上げましたように、今、中央教育審議会のほうでも、あるいは、文部科学省を含めた今の政府の考え方の中で、今、委員がご指摘になりました教育の機会均等ですとか、教育の水準維持、そういったことを前提にして考えるということで。","voiceIndex":9,"id":"exchange-003"},{"speaker":"沢田委員","kind":"質問","question":"推移を見守るというのは、地方自治体としてあるのかなとは思うんですけれども、私は、教育のあり方の検討からすると、それでいいのかと。財政力のあるところは充実した教育をやるけれども、財政力が少ないところ、厳しいところは、それなりのというようなことがあれば、憲法上で、すべての国民は等しく教育を受ける権利があるという規定をした根底が崩れはしないのか。そこら辺は、いかがでしょうか。","respondent":"市川庶務課長","answer":"いわゆる教育畑のほうからいたしますと、教育改革ありきというよりは、しかるべき財源の手当てがされた上での改革がされるべきということは、私どもの区長も、教育長も、そのような趣旨のことを、これまで申し上げてきているとおりですので、そういう趣旨で。","voiceIndex":11,"id":"exchange-004"},{"speaker":"沢田委員","kind":"質問","question":"そこでちょっと質問したいんですけれども、今度出ている、平成１７年度は４,２５０億円という暫定的な措置の裏付けというのは十分になされているんでしょうか。詳細は出ていませんけれども。","respondent":"市川庶務課長","answer":"冒頭の説明の中で申し上げましたけれども、先だって報じされたところによりますと、来年度におきましては、４,２５０億円の削減を計上するその一方で、税源移譲予定交付金に同額を計上していると受けとめてあります。","voiceIndex":13,"id":"exchange-005"},{"speaker":"沢田委員","kind":"質問・要望","question":"今進んでいることは、地方６団体が言っている、財源のしっかりした手当てをという方向とは違う方向にひた走っていることは明瞭だと思うんです。それを、慎重に見極めたいなんて言っているとなれば、大変なことになる。先ほど、中塚委員が、教育長の答弁を求めているんですけれども、教育長としては、そこら辺はどうなのかというのを、率直な見解をぜひ述べていただきたい。","respondent":"市川庶務課長","answer":"これは、先だっての１１月２６日に発表があって以来、片方で報じられたことですけれども、この合意なるものがどうなるかということについて、今、まだ確証が得られていない段階です。","voiceIndex":15,"id":"exchange-006"},{"speaker":"沢田委員","kind":"質問・要望","question":"ですから、じゃあ、もう一度ここを聞きたいと思うんですけれども、全体としては、私は、間違いなく国の財政難で、地方の補助金、あるいは負担金を減らすということで、財政的なことが大きな要素になって、地方公共６団体を巻き込んで、この間、一定の案が出された。これとて、まだこれからという面がもちろんありますけれども、全体の流れとしてどうなんでしょうか。","respondent":"市川庶務課長","answer":"先ほど申し上げたように、今示されている合意というものが、実際にどういうふうに離陸をして、着地をしていくのか、そういったところを、今後、今まで以上の注意と関心を持って、その推移を見守っていきたい。これが今の正直な気持ちです。","voiceIndex":17,"id":"exchange-007"},{"speaker":"林（宏）委員","kind":"確認","question":"この文章の流れの中で、いわゆる区市町村の職員としての考え方を確認したいんですけれども、趣旨の２行目にある、「長引く不況の下で、子どもたちの就学困難が広がる」と出ているんですけれども、義務教育の中で、こういう現象は起きているんですか。その辺、いわゆる区の職員としての感覚は、どういうふうに持っていらっしゃいますか。","respondent":"谷田部学務課長","answer":"経済的な理由で進学が困難な家庭に対しては、就学援助という制度がありますので、そういった経済的な給付というところでは、就学の機会を設けているです。","voiceIndex":20,"id":"exchange-008"},{"speaker":"林（宏）委員","kind":"意見","question":"そうすると、いわゆる国から出ているお金なんでしょうけれども、就学援助をして、義務教育はきちんと受けられるというような手当てと言ったら失礼かもわからないけれども、それを講じているにもかかわらず、こういう表現をしてくるというのは、僕は、この文章全体が、どうもあちこちで違う意味が出ているのかなと取らざるを得ない。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":22,"id":"exchange-009"},{"speaker":"沢田委員","kind":"質問","question":"ちょっと決めつける前に。今の質問で、こういう言葉のことで、就学困難というのが、正確な言い方はちょっとわかりませんでしたけれども、それをとらえて願意に沿いがたいというのは、妥当性を欠いているんじゃないかと。念のために、就学援助の話が、先ほど出たんですけれども、今、就学援助の推移というのはわかりますか。わかれば、ちょっと説明してほしいんです。","respondent":"谷田部学務課長","answer":"就学援助の受給率の推移というご質問でしょうか。〔「わからなければいいです、急ですから」と呼ぶ者あり〕小学校、中学校とも、大体２５％ぐらいの児童生徒が受給しているという状況です。","voiceIndex":24,"id":"exchange-010"},{"speaker":"沢田委員","kind":"質問","question":"２５％って、たしか今、生活保護基準の１.何倍だったか、ちょっとそれも教えてほしいんですけれども、実に４人に１人の割合で就学援助を受けている、これが就学困難でないということは、どこで言えるんだと。それでもなおかつ４世帯に１世帯が受けているという、ここに厳しさが出ているというふうに、私は思います。ちょっと、何倍かという推移も含めて、わかったら教えてもらえますか。","respondent":"谷田部学務課長","answer":"就学援助の、いわゆる準要保護の認定の基準ですけれども、生活保護世帯にいろいろ給付がありますけれども、私どもはその１.２５倍で認定しています。２３区では、比較的高い率だです。","voiceIndex":26,"id":"exchange-011"},{"speaker":"西本委員","kind":"質問・要望","question":"もう一度確認をさせていただきたいんですが、先日、三位一体改革で、義務教育も議論をされたというご説明が先ほどあったんですが、平成１７年度、４,２５０億円、それは同額を交付金で給付するという形で、お金の出し方が違うにしても、平成１７年度については、予算的に言うと、同額下ろされると認識をしてよろしいんでしょうか。","respondent":"市川庶務課長","answer":"少なくとも、報道されている範囲から読み取る限りは、そういうことだと受けとめています。","voiceIndex":28,"id":"exchange-012"},{"speaker":"西本委員","kind":"質問・要望","question":"もう一度確認したいのが、学校事務職員、栄養職員という考え方というのが、国の考え方ではどういうふうになっているのか。それは、地方のほうに移行していくべきだと考えるところに焦点があるのか。それとも詳細が、そこまでまだ決まっていない状況なのか、そこら辺に動きがあれば、教えていただきたいんですが。","respondent":"市川庶務課長","answer":"今回、政府・与党合意の中でも、最終的に来年の秋に出されます中央教育審議会の答申を踏まえて、その後の措置を決定したいですので、今の段階では、国のほうの、事務職員、学校栄養職員に対する最終的な考え方が示されている段階ではないと考えています。","voiceIndex":30,"id":"exchange-013"},{"speaker":"藤田委員","kind":"意見","question":"この請願につきましては、そうした中で、２項目目の、これまで対象外となっていた教材費、旅費、恩給費等々ずっと羅列されていますけれども、今現在、この段階で、ここまで広げて意見書を出してほしいということについては、ちょっとこれは、私たちの考えとは違うんではないかなということで、この請願に対しては、そういう意味合いから、願意に沿いがたいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":35,"id":"exchange-014"},{"speaker":"沢田委員","kind":"意見","question":"ここをいじることについては、よほど慎重にやるべきなのに、何か財源論が先行しているということにしか思えません。東京都は若干増えますけれども、地方の教育はどうなっちゃうのか、そこの子どもたちはどうなるのかという、全国的にできるだけ等しい教育を行っていく上で重大問題が絡んでいると思うことが一つ。そうした立場から、この請願で言っている、１、２項を含めて、これは当然のことだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":36,"id":"exchange-015"},{"speaker":"大西委員","kind":"意見","question":"私どもも、紹介議員として請願を出しておるわけですけれども、今、沢田委員がおっしゃったご趣旨に９０％、要するに総論の部分では大いに共鳴するところです。よりまして、この請願の部分については９０％賛成ですが、このままの状態では、若干のデコレーション部分に願意に沿いかねる部分があるということでの態度表明ということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":37,"id":"exchange-016"},{"speaker":"西本委員","kind":"質問・要望","question":"先ほども質問させていただきましたけれども、この時点ではいろいろな思いがあったのかなと推測はできるんですが、ただ、私どもとしても、今、義務教育費の置かれている状況というのは非常に理解されるところで、問題もある、解決しなければならないこと、それから、国の動向、それによる都の動向、さらには品川区として大きな影響が出てくるというところも理解できますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-017"}]},{"id":"topic-02","title":"平成１６年請願第２７号「義務教育費国庫負担法」の改正に反対する請願","agenda":"平成１６年請願第２７号「義務教育費国庫負担法」の改正に反対する請願","exchanges":[{"speaker":"沢田委員","kind":"意見","question":"同一議会でもって相反する結論は出せないということになりますと、今度のこの問題というのは、先ほどの請願と趣旨的には同じなんですよね。だから、そういう意味では、結論が出ちゃっている。私の考えとしては、これは採択を主張しますよ。それでもなおかつというのなら、それは聞きたいと思いますけれどもね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":45,"id":"exchange-018"},{"speaker":"大西委員","kind":"意見","question":"今、沢田委員が言われたお気持ちは、私は十二分に理解できるところはあります。私も、先ほど申しましたように、義務教育費国庫負担法これ自体に、私たちが反省する立場ということでは、先ほどの請願第２２号と同様の趣旨であるということは理解しておりますが、ただ、先ほどちょっと言われました一事不再議ということに関しましては、全く同様の案件ではないと、私は理解しております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":46,"id":"exchange-019"},{"speaker":"沢田委員","kind":"質問","question":"そのために、１項目、２項目あって、１項目は賛成だけれども、２項目は賛成できないという場合の取り扱いとしては、部分採択の方法があるわけなんです。それもせずに進んでしまったというのは、それも含めて各委員の判断ですから、いいんですけれども、ちょっとやっぱり問題が残るところじゃないかという、私の思いだけ伝えておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-020"},{"speaker":"沢田委員","kind":"質問","question":"先ほどの論議に引いてみますと、１項目目、それからタイトルが、学校事務職員なんかを含む教職員の義務教育費国庫負担制度の堅持という先ほどの請願があったわけですよね。だから、その１項目目も含めて流しちゃった、否決をしちゃったということは、やっぱり問題が残ると思いますよ。これは私の意見ですから、意見だけ述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-021"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"趣旨というのも、どっちかというと理由の中の重点的なものを掲げてきた言葉かなと思う。請願項目というのは、提出していただきたいとかいうことが書かれているから、それが請願の思いというのか、そういうふうに受けとめるんだけれども、そういうんでいいんですけれども、これは請願項目が出てこないんですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-022"},{"speaker":"林（宏）委員","kind":"確認","question":"だから、そういうことになっているし、名前だとか、宛て名だとか、日付だとか、そういう最低必要なものは書かれているんだけれども、我々が今まで受けてきた請願というのは、はっきり項目というものが書かれていましたよね。どこに書かれているというのではなくて、これから我々審査するときに、そういうふうに受けとめていけばいいんですねということを確認したい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-023"},{"speaker":"林（宏）委員","kind":"質問","question":"それで、真ん中あたりに外国の例というのが出ているんですけれども、ここら辺の文章が、ちょっと意味がよくわからない。「義務教育については全国一律の水準確保のために国家公務員としている」という意味は、これはどういう意味にとればいいのかな。義務教育に携わる公務員は国家公務員と限定するということなんですか。","respondent":"市川庶務課長","answer":"おそらくは、ここで言わんとしていることは、該当するのかなと思いますので、その辺をちょっと紹介します。そこでは、義務教育費負担のあり方を考える上で、主要な外国の制度と比較検討することが極めて有益であるという前提のもとで、幾つか検討を行ってあります。","voiceIndex":59,"id":"exchange-024"},{"speaker":"林（宏）委員","kind":"質問","question":"わかりました。日本は国家公務員ではないですよね。国立の場合はあれですが、今はなくなったのか、国立は。残っている部分もあるかな。国立は別として、地方公務員ですよね。そうすると、地方公務員の給与というのか、いろいろな諸費用に関して国が負担するというのが、国家公務員に準じた立場というか、仕事をしてもらうんだと、そういうふうに考えればいいわけですか。","respondent":"市川庶務課長","answer":"外国との比較を行った上で、その国の一つの考え方として共通して言えることは、国策として、学力の向上を目指し、教育水準保護のために国家の教育を拡充する方向で改善が推進されているというふうに、この中央教育審議会の中間報告の中では結論づけてあります。","voiceIndex":61,"id":"exchange-025"},{"speaker":"林（宏）委員","kind":"意見","question":"そうすると、しつこいけれども、地方公務員は地方公務員であるということで日本は成り立っているんですよという考え方でいいわけですよね。何も国家公務員に格上げをするとか、そういう意味にとらなくもいいと、それは皆が認めていることなんですよということでいいのかな。","respondent":"市川庶務課長","answer":"今、文部科学省を中心に行われております改革論議の中でも、今、委員が言われたような視点での議論、意見はあるのかもしれないですけれども、少なくともそれは、議論ということでは、私ども、まだ接したことはございません。","voiceIndex":63,"id":"exchange-026"},{"speaker":"林（宏）委員","kind":"確認","question":"ただ、どういう形にしていくのかというのは、議論すべきだと思うんですよ。真ん中あたりに、「拙速に負担制度廃止の結論を出すべきではない」と書かれているけれども、結論は出すべきではないけれども、やっぱり、やめるかやめないかということにこだわらず、きちんとしたものを持っていくべきだと、僕は思うんです。確認をしたいんだけれども。","respondent":"中島指導課長","answer":"小中一貫教育も、全区実施に向けまして、その方向性に迷いのあるところは全くございません。","voiceIndex":65,"id":"exchange-027"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"冒頭に言ったように、どれかというと、意見書を出してくださいというのが要望だと思うんですけれども、僕は、まだまだ意見書を出す段階に、品川区議会は考えがいってないと思うんです、議論をしてないと思うんです。今の段階では、意見書を出すのは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-028"},{"speaker":"大西委員","kind":"質問・要望","question":"ただ、今、お２人の委員からも出ましたように、若干、まだ国の動きがあるようにも思えるところがありますので、さきの議論に類するように、趣旨採択ということで、私の態度表明ということにさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-029"},{"speaker":"沢田委員","kind":"質問","question":"そういう意味で、見守るとかいう生易しい状況ではなくて、品川区の教育現場、品川区の子どもたちを考えるならば、これはやるべきではないということをしっかり意志表明すべきだと、私は思います。ですから私は、趣旨採択ではなくて、前段のも含めて採択をすべきだと。それで、一刻も早く品川区議会としての、住民意思の決定を関係機関に届けるべきだということを述べたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-030"},{"speaker":"西本委員","kind":"質問","question":"ですから、今の段階としては、趣旨は非常に賛同しますし、私どもとしても、義務教育費というのを、どういうところを堅持していかなければならないのか、どういうところを自分たちのところに権限委譲してほしいのか、するべきなのかという議論を、計画的にしていく必要があるかと考えておりますので、今回は趣旨採択という形で、意見書提出はまだ早いのではないかなと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-031"},{"speaker":"沢田委員","kind":"質問","question":"ちょっと聞きたいんですが、趣旨採択という場合には、何の趣旨なのか。それから、ここで言っている、意見書を出してほしいということに対してはどうするのかという問題があわせて出てくるので、全体が趣旨採択でというのなら、私は趣旨採択でも構いませんけれども、ただ、意見書は出すべきだというふうに思います。ですから、趣旨採択に反対するものではありません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-032"},{"speaker":"大西委員","kind":"意見","question":"私としては、大変苦しいところですが、政治決断として、今、現状の中でこれを採択、もしくは不採択という形で決を取った場合に、他の委員がおっしゃっている趣旨採択というご主張の部分も、それなりに理解できる部分もあります。これを回避するために、私どもの判断として、今回は趣旨採択でです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":81,"id":"exchange-033"},{"speaker":"西本委員","kind":"意見","question":"先ほど、明確にお話ししたつもりですけれども、これからの動向を見据えていろいろ議論をしていく必要があるということで、今回は、意見書はその時期ではないだろうという判断をさせていただきました。趣旨には賛同します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":84,"id":"exchange-034"},{"speaker":"沢田委員","kind":"意見","question":"わかりました。私どもは趣旨採択に反対するものではありませんし、むしろ採択すべきだという立場と、趣旨採択であっても、意見書を出すべきだということを述べて態度といたします。反対はいたしません。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":85,"id":"exchange-035"}]},{"id":"topic-03","title":"平成１６年請願第２８－３号、一人ひとりの子どもが大切にされる品川区を求める請願","agenda":"平成１６年請願第２８－３号、一人ひとりの子どもが大切にされる品川区を求める請願","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"初めに、すまいるスクールのことを、若干お伺いしたいんですけれども、それぞれすまいるスクールから、放課後児童健全育成事業を担うすまいるスクールに変わったときに、東京都に対して、新しい事業として申請書を出しているかと思うんですけれども、そこで、今行われている３１校すべてのすまいるスクールの育成室の広さ、羅列で構わないので、全部教えていただきたいと思います。","respondent":"富田教育改革担当課長","answer":"東京都に対しまして、第２種社会福祉事業の開始届けを提出するに当たりましての、育成室の面積ですけれども、すまいるスクール全体の事業面積は、２教室、３教室、またはそれ以上ということで大変広いものですけれども、都の実施要綱の中にあります適切な遊び。","voiceIndex":95,"id":"exchange-036"},{"speaker":"中塚委員","kind":"質問・要望","question":"なぜ、同じ事業にもかかわらず、学校ごとにこんなにも施設のばらつきが生まれているのか、ちょっと説明していただきたい。このままばらばらのままでいくつもりなのか、教えていただきたいと思います。","respondent":"富田教育改革担当課長","answer":"先ほど、申し上げました面積、ちょっと説明が不十分でございましたが、畳み敷きですとか、カーペット敷きということで、子どもたちがゆったりくつろげる場所というのを、どこのすまいるスクールも設けておりまして、それのあるスペースでもって換算しております。","voiceIndex":97,"id":"exchange-037"},{"speaker":"中塚委員","kind":"質問・要望","question":"私が一番伺いたいのは、育成室の説明がありましたけれども、ゆっくりくつろげるところ、ごろんとできるところの育成室のスペースが各学校ばらばらでいいのかということを伺いたいんですけれども、それについて、１点教えていただきたいと思います。それから、なぜばらつきがあるのか。なぜ、全く基準がないのか、基準を設けるべきじゃないかと思うんですけれども、それについてのご意見を教えてください。","respondent":"富田教育改革担当課長","answer":"そういったところから、畳み敷き、またはカーペート敷きにするスペースの若干の違いというものは出てまいりますけれども、すまいるスクールの実施内容は、先ほど申し上げましたように、フリーに遊んだり、スポーツをしたり、自習をしたりする活動、また、学年ごとの勉強会。","voiceIndex":99,"id":"exchange-038"},{"speaker":"中塚委員","kind":"質問・要望","question":"一緒に３０人学級について、若干、数字的なところを教えていただければと思います。５月１日の状況で、その学校が何クラスかというのを伺っていますけれども、今現在、小学校、中学校で、４０人を超える学校編成を行っているところがそれぞれ何クラスあるのかというところを、今手元にありましたら、教えていただきたい。","respondent":"富田教育改革担当課長、谷田部学務課長","answer":"子どもたちが精神的にゆったりくつろぐということは、ごろんと横になることだけで実現をしていくものでもございません。そういう意味では、必要な配慮をしているです。３１人以上４０人までのクラスが１２２学級ですので、３割弱という状況です。中学校ですけれども、１３５学級ございまして、３０人以下が２８学級、３１人以上は、数が増えまして１０７学級です。","voiceIndex":101,"id":"exchange-039"},{"speaker":"中塚委員","kind":"質問・要望","question":"この話をしますと、よく、実際は品川区は、ＴＴやさまざまな事業を講じて少人数になっているんだという話を伺いますけれども、小学校１年生の１週間の授業の中で、通常の学級編成でなくて少人数になっている科目というか、国語と算数などでＴＴを使っているかと思うんですけれども、全体のコマ数がどれぐらいで、実際にどれぐらいの割合のコマ数が少人数になっているのか、この辺を。","respondent":"谷田部学務課長、中島指導課長","answer":"制度上、ありますけれども、今現在、４１人以上の学級というのは、区内の小中学校ではございません。それぞれの学校でまた配分時数が変わってまいりますし、また単元による時数も、ほかの学年とのバランスがありますので、それぞれ個々に状況は違ってきている実態があります。","voiceIndex":104,"id":"exchange-040"},{"speaker":"中塚委員","kind":"質問・要望","question":"そこで伺いたいのは、毎年の２３区教育長会、また２３区の校長会も、正確な文章を持っていないので、３０人学級と言っているのかどうかわからないんですけれども、東京都に対して実現するように要請しているとお話を伺っているんですけれども、教育長会、また校長会は、東京都にどういう文面で３０人学級の実現を求めているのか、その内容と趣旨を教えていただきたいと思います。","respondent":"谷田部学務課長、中島指導課長","answer":"その後、転入等で、支障がなければ、学校のほうは受け入れるということで、もし例えば転入者が多くて、どうしても１学級では難しいという話があれば、私ども、そういう話を受ければ、東京都教育委員会のほうに。先ほど、全国での少人数学級の実施というお話がございました。私どもが伺っております資料の中では、平成１６年度では、４２の道府県で少人数学級を実施している状況があるという情報を持ってあります。","voiceIndex":107,"id":"exchange-041"},{"speaker":"中塚委員","kind":"質問・要望","question":"品川区では、現状のＴＴの配置の状況だけで、小学校の低学年で３０人学級を実施するという試算というのは行ったことがあるのかどうか、まず２点目として伺いたいと思うんです。始めから３０人学級にしておけば、そういった事態は起きないわけであって、こういう子どもたちの実態を、今後どうしていきたいと思っているのか、教えていただきたいと思います。","respondent":"谷田部学務課長、中島指導課長","answer":"ですから、一律に、では少なければいいんだというようなことは言えませんで、それぞれ一定の規模があって、それぞれ効果的な教育活動、学習活動が展開できるですので、それぞれ場面、場面に応じて柔軟に、私ども、対応しているです。こういう形で、多くの教員が個々の児童生徒とかかわることで、私たちの目指す基礎基本の定着、個々の伸長、こういった細かい指導ができていくものと考えています。","voiceIndex":110,"id":"exchange-042"},{"speaker":"中塚委員","kind":"質問","question":"ほんとうに３０人学級を、私は願うんですけれども、今、指導課長から答えていただきたかったのは、全国では、今のＴＴの状況を上手に組み合わせることによって、少ない予算の中でも、小学校低学年から３０人程度の学級を進めている自治体もあるんです。新たに予算をつけなくても、今のＴＴの状況だけでも、小学校低学年だけでもやっていけるのかどうかを伺いたかった。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":113,"id":"exchange-043"},{"speaker":"中塚委員","kind":"質問・要望","question":"学校できちんと子どもの思いを受けとめる、そういう教育環境をつくらなきゃいけない。生活集団は４０人でいいとおっしゃいますけれども、今の実態には絶対にそぐわないと思うので、一刻も早く３０人学級にしていただきたいと思います。先ほどの指導課長のご答弁だけお願いいたします。","respondent":"中島指導課長","answer":"それぞれの学校が、例えば１、２年生での算数の時間にそれを活用する、３、４年生の理科、社会科でやっているとか、それぞれの学校の教員のスタッフ等を鑑みる中で、体制を組んでいるという状況があります。","voiceIndex":115,"id":"exchange-044"},{"speaker":"沢田委員","kind":"質問","question":"先ほど、学級編成基準が少なければいいんだという立場は取らないと。一定の規模があって、場面、場面で、品川区ではやっているから、現状、４０人学級で問題ないんだということをおっしゃいましたよね。一定の規模というのは、４０人学級というふうにとらえていいんですか。４０人学級が、今の教育において適正だという考え方でいいのか、どうなのか。その考えを聞きたいんですが。","respondent":"谷田部学務課長","answer":"先ほども説明申し上げましたが、東京都の学級編成基準が４０人ですので、私ども、その４０人で学級編成を行って、東京都に学級編成の同意をして、その結果、編成が認められたです。","voiceIndex":117,"id":"exchange-045"},{"speaker":"沢田委員","kind":"質問・要望","question":"区の基準だとか、公立では４０人になっているかということを聞いているんじゃなくて、実際の子どもたちの置かれている現状、現場でいいのか、どうなのか。それが一つ。それからもう一つ、文部科学省が、今度、事務連絡で、新しい基準を出した、学級編成。それから、なぜ文部科学省がそういう結論を出したのかという背景について、説明をいただきたいんですが。","respondent":"中島指導課長","answer":"都教育委員会のほうでは、それを受けまして、区教育委員会からの情報について、一時ペンディングをしまして、東京都教育委員会のほうで検討するという状況がございました。","voiceIndex":119,"id":"exchange-046"},{"speaker":"沢田委員","kind":"質問","question":"今、国立教育政策研究所のデータの話があったんですが、あれは２通りに読めますね。だから、片方だけ言っていれば、ちょっと、今手元に資料がないですから、また別の機会にしたいと思いますけれども、それが一つ。それから、文部科学省が法律で４０人と決めながら、なぜ自治体の権限で加配教員をして、少人数学級にしていいか、その動機、背景は何なんですかと聞いたんですが、その答弁はないんですけれども。","respondent":"中島指導課長","answer":"文部科学省としては、地方行政といったところの活性化等も視野に入れているのかもしれませんが、私どもとしては、それを厳密にコメントする立場にはないものと考えています。","voiceIndex":121,"id":"exchange-047"},{"speaker":"沢田委員","kind":"意見","question":"わからないというふうにしましょう。では、もう一つ聞きたいんですけれども、全国レベルで見ると、４０人学級を、３０人だとか、３５人だとか、自治体独自で少人数学級をやっている都道府県はどのぐらいの数になるか、何かデータがありますか。","respondent":"中島指導課長","answer":"先ほどちょっと申し上げましたが、平成１６年度の実施段階では、４３道府県となっています。","voiceIndex":123,"id":"exchange-048"},{"speaker":"沢田委員","kind":"質問","question":"私は山形県に行って、サンサンプランと、これは本会議場でも述べたところですけれども、３３人学級なんですか、それでサンサンプランなんです。これは長野県でも同じですね。そのことに対するコメントがあったらお尋ねしたいんですが、この間、決算特別委員会で、私どもの宮崎幹事長が、３０人学級に移行するのに予算がどのぐらい必要なのかと。小学校で言うと、算数と国語ですか。","respondent":"中島指導課長","answer":"少人数の状況でありますけれども、少人数の学習の場面は、先ほど申し上げましたように、それぞれの学校で学年が工夫されている状況があります。５、６年生で実施しているところもあれば、１、２年生で実施をしているところもあります。","voiceIndex":125,"id":"exchange-049"},{"speaker":"沢田委員","kind":"質問","question":"具体的にどうなのかというのを聞いているんで、少人数指導を、私たちは間違えているとは思わないですよ、効果はあると思う。なければないでしようがないですから、いいです。それからもう一つ言いますと、国立教育政策研究所でこういう判断が出ていると言いますけれども、じゃあ、世界レベルで見たらどうなんだと。一日も早く実現してほしいということを述べて、長くなったんで終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":127,"id":"exchange-050"},{"speaker":"西本委員","kind":"確認","question":"一つだけ確認したいんですが、まず、すまいるスクールの実態把握を行い、必要な改善をということが２項目目に入っているんですが、すまいるスクールの実態調査というのは、どういうふうな状態になっているのか。そこら辺の状況把握はどうなっているでしょうか。","respondent":"富田教育改革担当課長","answer":"改善をですけれども、個別のすまいるスクール、さまざま状況が違ってきておりますので、それぞれのすまいるスクールの現場から上がってきております、例えば施設が２階、３階の場合のストッパーの設置ですとか。","voiceIndex":130,"id":"exchange-051"},{"speaker":"西本委員","kind":"確認","question":"既に３１校実施をしておりますので、ある程度近隣のすまいるスクール、もしくは全体の中で話し合いとか、どういう状況なのかというところは、意見交換されているのかなと思うんです。そこら辺の状況の実態の把握ですね。親にとってみると、行ってほしいという気持ちは強いんだと思います。居場所をはっきりさせたいということがありますので。その辺は何か、つかんでいることがありますでしょうか。","respondent":"富田教育改革担当課長","answer":"この４月から、放課後児童健全育成事業になってまいりますこともございまして、留守家庭児童に限らず、低学年の希望される保護者には、無断欠席の場合の連絡希望調査いたしまして、必要な、望まれる方には実施をしているところです。","voiceIndex":132,"id":"exchange-052"},{"speaker":"西本委員","kind":"質問","question":"個別の問題についても、かなり相談を受けて、対処していただいているというふうな答弁だったと思うんですが、学童保育クラブがあったときにも、学童保育クラブに行かなくなってしまうという子どもたちの状況もありました。その辺はいかがでしょうか。","respondent":"富田教育改革担当課長","answer":"そういう意味では、個別の指導員の現場、現場の対応ということだけではなく、全体的な指導員の研修指導といったことも含めて、全体体制で臨んでまいりたいと考えています。","voiceIndex":134,"id":"exchange-053"},{"speaker":"西本委員","kind":"確認","question":"先ほどの答弁の中にも、働いている、働いていないに限らず、放課後ということでとらえた場合には、子どもたちの居場所として必要なものがあるんだということだとは思うんですが、学童保育クラブの希望というのは、どういうふうにとらえているのか。学童保育クラブという意味よりも、もっと広い意味のすまいるスクールになっていくんではないかなと思いますが、その辺の今後の考え方を確認したいんです。","respondent":"富田教育改革担当課長","answer":"学童保育クラブ事業に求められているものですけれども、都の実施要綱によれば、放課後児童の健全な育成が図られるよう、衛生および安全が確保された設備を備える等により、適切な遊び、生活の場を与えることであるというふうに認識をしています。","voiceIndex":136,"id":"exchange-054"},{"speaker":"西本委員","kind":"質問・要望","question":"３番目の３０人以下学級の考え方を質問させていただきたいんですが、３０人以下学級にする場合、例えば３０人となったときに、１５人クラスになるわけですね。一律に人数で決められる状態なのかなというところがあります。ただ一律に３０人学級と言ってしまいますと、ほんとうに３０人でいいのか、どうか。２０人学級でもいいわけですよね。その辺の考え方はどうでしょうか。","respondent":"谷田部学務課長","answer":"そういう学級に在籍する特別な教育のニーズを必要とする児童生徒に対する、今後の支援をどうしていこうかですので、そういうような支援が必要なお子さんが何人いるから、ここは２０人でなきゃならないとか、３０人でなきゃならないとか。","voiceIndex":138,"id":"exchange-055"},{"speaker":"西本委員","kind":"質問・要望","question":"３０人だからいいとか、２０人だからいいとかということではなくて、今、求められているのは、子どもたちがどういう状況にあるから、こういう編成でやっていきましょう、こういう人数でやっていきましょう、先生の数でやっていきましょうということであるべきだと考えていますので、今後の状況に、そしてまた私どもも勉強、研究していきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":140,"id":"exchange-056"},{"speaker":"沢田委員","kind":"意見","question":"一つだけ。先ほど、すまいるスクールの問題があったので発言できなかったので、１点だけ聞きたいんですが、すまいるスクールに移行して、これまで学童保育クラブに通っていたお子さんの出席率がどう向上したのか。私、たしか今年の春ごろに、学童保育クラブの出席状況について調べてほしいということを言っていたんです。その状況を、ちょっとお答え願いたいんです。","respondent":"富田教育改革担当課長","answer":"すまいるスクールの登録申請に当たりまして、保護者の就労状況というのは把握をしておりますけれども、必ずしも保護者が就労している方が学童保育クラブにいらしたお子さんということもございませんし、そういう意味で。","voiceIndex":141,"id":"exchange-057"},{"speaker":"沢田委員","kind":"質問","question":"今、聞いてみると、調査もしていない。一体何なのか。実は、ここにいらっしゃる委員の皆さんと、この間、保育問題協議会と懇談をやった。そのときに、発言者の一人が、学童保育クラブがあるときは喜んで行っていたけれども、最近は行かなくなっちゃったと。この請願で言えば、よく把握をしてほしいと、その思いが込められているということで、ほんとうに調査していないのか、どうなのか。いかがでしょうか。","respondent":"富田教育改革担当課長","answer":"したがいまして、そういった保護者が悩んでいるような場合等につきましては、個別にご相談を受け、解決をしてまいりたいと考えています。","voiceIndex":143,"id":"exchange-058"},{"speaker":"沢田委員","kind":"質問","question":"個別にではなくて、調査をすべきですよ。ドラスティックに移行したわけでしょ。それは大丈夫だというふうにずっと言ってきたわけですから、どうなっているのか、個々の事情も含めて、全体として学童保育クラブに通っていたけれども、今、通えなくなったお子さんの調査をして、その原因がどこにあって、原因があるんならば、それを改めるということを約束すべき、してほしいと思いますが、いかがでしょうか。","respondent":"富田教育改革担当課長","answer":"さまざまなお子さんの状況というのは、私のところでは、必ずしも把握が難しいところですけれども、それぞれのすまいるスクールの現場では、それぞれのお子さんの参加状況については、きちんと受け付け、確認をしているところであり、相談につきましてもお受けしている状況です。","voiceIndex":145,"id":"exchange-059"},{"speaker":"沢田委員","kind":"意見","question":"あくまでも、調査をしてほしいと言って、やると言ったことを、今になって、それぞれのすまいるスクールのレベルでやっているはずだなんていうのは、これは区が取るべく立場じゃないですよ。それを、何か他人ごとのようにやるというのは、大変問題だと指摘して、長くなったので終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":147,"id":"exchange-060"},{"speaker":"大西委員","kind":"質問","question":"今、沢田委員のほうからありましたように、私は、少人の３名であっても、この人たちが、なぜ学童保育クラブからすまいるスクールになって行けなくなったのかということを調査するというんですか、その原因を探るということは、今後のすまいるスクールにとって、すまいるスクールを拡大していくことにとっては、当然必要なことだと思いますので、その努力はされるべきことはあろうかと思います。","respondent":"富田教育改革担当課長、中島指導課長","answer":"このほかにも、毎月のお便りというのをすまいるスクールで発行しておりますけれども、その中でも、すまいるスクールでの募集の内容等々を載せるだけではなくて、できるだけきめ細かく、すまいるスクールでの勉強会の内容。そのほかにも、プラン２１の推進の中で、教科担任制を実施している小学校、また、学年団という、学年を一つの基盤として通常の教育活動を考えているような小学校、２人担任制というようなシステムを採用している中学校。","voiceIndex":148,"id":"exchange-061"},{"speaker":"西本委員","kind":"質問・要望","question":"先ほどの沢田委員の発言の中で、私の違った情報もありますので、それを少しお話をして、一つだけ確認をさせていただきたいんです。学童保育クラブがあったときに、学童保育クラブに行きたくないというお子さんを、私はたくさん見受けています。そういうことで、毎年、同じ団体から請願書が出てきて、学童保育クラブの充実をしていきましょうという趣旨で、ずっとやってこられたと思います。それで終わります。","respondent":"富田教育改革担当課長","answer":"したがいまして、そういった保護者からのご相談といったものを受けていきますということを、これまでよりも丁寧にお知らせをしてまいりたいと考えています。","voiceIndex":151,"id":"exchange-062"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"ですから、ここに書かれていることは、何か学童保育クラブを充実するような形で、日中親が家にいない子どもたちがどうのこうのとか、そういうようなことになってくると、子ども全体、放課後、子どもたちがほんとうに安全に過ごす場所、あるいは、将来役に立つような場所があると、そういうものを、もっと広い視野で見ていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":155,"id":"exchange-063"},{"speaker":"藤田委員","kind":"意見","question":"ゆったりとした気持ちが、やっぱり大事だと思うんですよ。３０人学級については、３０人以下であれば、ほんとうに行き届く教育ができるのか。じゃあ逆な面で、３０人以上でやっている現在は、行き届いた教育ができないのかということですね。実態的に、そういうような教科、内容、加配について運営をしているということで、私は理解をいたしますので、この２項目については、願意に沿いがたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":156,"id":"exchange-064"},{"speaker":"大西委員","kind":"意見","question":"しかし、どうして３０人でなければ教育ができないのかといえば、学校長の考え方、また、教員の熱意、ちょっとダブルところはありますけれども、その学校の取り組みにより、改善はどうしても３０人でなければいけないとは限らず、学校長が、その部分は改善して余りあるもの、スケールメリット持ってしてできるものもあるのではないかということで、今回のこの請願について。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":157,"id":"exchange-065"},{"speaker":"沢田委員","kind":"質問・要望","question":"そこは、ぜひ、調査をしてほしいということ。この請願項目の中にあって、どうしても、私がちょっと不安がよぎるのは、常勤職員を１人にしてしまったという、これが影響していないかというその思いが非常に強いですから、２項目の常勤職員の複数配置というのも、私は全面的に賛成です。一日も早い３０人学級への移行を強く求めて、この請願は採択をすべきだということを述べて、意見表明をしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":158,"id":"exchange-066"},{"speaker":"西本委員","kind":"提案","question":"その人たちが、今、一生懸命やられている。これだけの長い年月を、保育問題協議会という形で質問されているんですから、それならば、今の子どもたちに合う政策はどういうものであるのかということを、むしろ提案をしていただきたかったと思います。ですから、今回の請願項目、２番、３番目につきましては、今後の保育問題協議会の活動を期待しつつ、不採択という形にします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":159,"id":"exchange-067"}]},{"id":"topic-04","title":"平成１６年請願第２９号、城南地区に複数の障害種別が共存する特別支援学校づくりを東京都へ求める請願","agenda":"平成１６年請願第２９号、城南地区に複数の障害種別が共存する特別支援学校づくりを東京都へ求める請願","exchanges":[{"speaker":"林（宏）委員","kind":"確認","question":"最初に全体的な確認なんですけれども、学校だから、文教委員会に付託されているんですけれども、厚生委員会とのかかわりという部分は、どういうふうにとらえるんですか、委員長は。というのは、例えば、ここにあるように、４学校と共同にしていくとかいうことになると、いわゆる厚生委員会の分野の話が出てくるわけですよ。その辺、ちょっとどういうふうにするのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":167,"id":"exchange-068"},{"speaker":"林（宏）委員","kind":"意見","question":"もう一つ言うと、ここに聴覚障害児とか、今も出た盲学校の話になると、視覚障害児の話だとか、そういう話が絡んでくるわけですよ、そういう子どもたちが、今、どういうあれになっているのかという話に。生活の実態とか、普段の、それは学校のことだけを話されているんだけれども、どうしても話はそこにいくんじゃないの。","respondent":"中島委員長","answer":"これはやはり、先ほど申し上げましたように、東京都も文教委員会で取り扱いということで、文教委員会に付託されている請願ですので、厚生委員会に関連するような部分は、文教委員会の方から連携をとっていただくとか、そういう対処の仕方もあろうかと思います。","voiceIndex":171,"id":"exchange-069"},{"speaker":"林（宏）委員","kind":"確認","question":"多少踏み込んでもいいということなら、そこだけ確認しておきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":173,"id":"exchange-070"},{"speaker":"沢田委員","kind":"質問","question":"今の件に関連して、いいですか。願意の2)は、障害者センター校の役割を持った学校づくりということで、どこまでいっても、一応学校ということになっているんですけれども、その前にある、「成人障害者や成人聴覚障害者とのふれあいの場としても活用できる」というあたりなんか、微妙にやっぱりオーバーラップしてくるのではないかというのが一つ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":176,"id":"exchange-071"},{"speaker":"沢田委員","kind":"質問・要望","question":"そういうのもあるので、ちょっと東京都のことであるから気の毒なんだけれども、あればいただきたいということが一つ。それから、ではちょっと具体的な質問に入りますけれども、先ほどの話で、ろう学校８校を４校にして、とりあえず、現在の品川ろう学校は、中学部を中央ろう学校に移転すると言いましたっけ。ちょっとそこら辺だけでも、もう一度説明してもらえるとありがたいんですが。","respondent":"谷田部学務課長","answer":"ですから、知的障害者が増えていて、一方でろう学校、盲学校に行っているお子さんが減少しているということで、それぞれ障害の重度、重複化に対応できるような形で、特別支援教育を展開していこうというのが、今回の計画の筋です。","voiceIndex":178,"id":"exchange-072"},{"speaker":"沢田委員","kind":"質問","question":"もう１点、わからないままなんですが、現在のろう学校は、小学部、中学部で何名ぐらいいて、要するに、生徒が少なくなったから再編しようということだと思うんですけれども、具体的な事例が、もしわかったら、減ってきている現状が何年前と比べどうかだとか、現在、どうかとかいうのがあったら、教えてほしいんです。","respondent":"谷田部学務課長","answer":"中学部が、昭和３５年度に３７１人、平成１６年度に１００人という状況になって、それで、３分の１から４分の１ぐらいに減少したという状況です。","voiceIndex":180,"id":"exchange-073"},{"speaker":"林（宏）委員","kind":"質問","question":"基本的なことで、大変不勉強なんだけれども、ここにも出ているんだけれども、いわゆる城南と、矢口と、この近くの養護学校がありますよね。ろう学校の児童生徒だけ別ですよね。視覚障害の人は盲学校、そしてろう学校、それから身体的な養護学校、例えば城南養護学校で、視覚障害、あるいは聴覚障害の人が一緒に学ぶというのは不可能なんですか。","respondent":"谷田部学務課長","answer":"これまでの心身障害教育と申しますのは、障害の種別に応じて学校をつくる。ですから、目の不自由な人は盲学校、耳の聞こえない方はろう学校、それから肢体不自由の方は肢体不自由の養護学校、知的障害の方は知的障害の養護学校、あと病弱の方は養護学校と、そういう種別に応じて。","voiceIndex":184,"id":"exchange-074"},{"speaker":"林（宏）委員","kind":"意見","question":"特別支援学校をつくっていってくださいというのが、請願の表題に出ているんですけれども、２項目の最後のほうに出ている、新しい障害者センター校というのは、特別支援学校と同じと見るのか、役割を持ったというんだから、特別支援学校の役割というか、コンセプトが、こういうセンター的な学校になるようにという意味にとるのか、その辺はわかりますか。","respondent":"谷田部学務課長","answer":"後段のほうの、大人との関係と申しますと、私の推測になりますけれども、いわゆるろう学校の関係の聴覚障害の皆さん方というのは、やはりコミュニケーション能力の観点で、機能訓練が必要だろうということで。","voiceIndex":190,"id":"exchange-075"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、今ある品川区のところが特別支援学校として生まれかわって、建替えるとなれば、また２年ぐらいはかかっちゃうのかもわからないけれども、今までの人も、あそこに存続させてくださいということは、ほぼ通っているわけですか。","respondent":"谷田部学務課長","answer":"先ほど申し上げましたけれども、現在、品川ろう学校のお子さんの数というのが。","voiceIndex":192,"id":"exchange-076"},{"speaker":"林（宏）委員","kind":"質問","question":"もう１回。あそこの品川がなくなっちゃうか、なくなるかという今の時期なのか、特別支援学校という、いろいろな障害の人たちが一緒になって学べるところをつくっていくんだということで、品川区の場所を生かしていくということは、まだ決まっていないんですか。","respondent":"谷田部学務課長","answer":"といいますのは、養護学校の実施計画が、たしか平成１８年度から１９年度に始まりますので、その建設の関係で、城南養護学校のほうに分教室が移るということですから、いずれにしても城南地区には分教室が何らかの形で残るということです。","voiceIndex":196,"id":"exchange-077"},{"speaker":"林（宏）委員","kind":"質問","question":"平成1８年度以降の２年間というから、平成２０年度までは今のままというふうに理解をしていいわけですよね。そうでしょ、だから、平成２０年度まではいまのままでいくという理解をします、そういうふうに言っているから。〔「平成１９年度ですね」と呼ぶ者あり〕平成１９年度までですか。きょう、採決して結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":200,"id":"exchange-078"},{"speaker":"藤田委員","kind":"意見","question":"私どもも、都議会のほうで、この件について、うちの議員が発言していますので、今、ご説明があった、私もそこまで詳しくはっきりは存じ上げませんでしたけれども、新しい障害者センター校がどのような学校になるのか、その辺も、今後、我々も十分議論をすべきじゃないかなと考えています。趣旨については、きょう、採択して結構だと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":201,"id":"exchange-079"},{"speaker":"沢田委員","kind":"質問・要望","question":"大変申しわけないんですけれども、わからない点が大分あるんです。例えばＰＴＡなんかがあった場合に、ＰＴＡとしてどうなのかという状況なんかも知りたいとかいろいろあるので、できれば、継続して審議していただきたいと思うんです。全体で趣旨採択ということでは、有志の方で、区部の方ですから、賛成はしますけれども、できれば継続でという思いはあります。ただ、趣旨採択で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":205,"id":"exchange-080"},{"speaker":"西本委員","kind":"質問・要望","question":"決してろう学校をなくさないでほしいという気持ちではないということだけ、理解していただきたい。私たちも、東京都に意見書を提出くださいというのが願意になっているので、どういう扱いになるのかという確認をしたかったんですが、この請願者たちは、意見書を提出くださいという願意なんですが、今の皆さんのご意見中では、趣旨という意味はわかったんですけれども、どういうふうにとらえているのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":206,"id":"exchange-081"},{"speaker":"西本委員","kind":"確認","question":"要は、最終的に決定するところは東京都になると思うんです。品川区として、東京都のほうに、こういう意向がありますよというふうに何らかで伝えていくというのがあればよろしいかと思うんですが、趣旨採択になったときに、どういう表現の仕方が東京都にあるのか、そこら辺を確認したいんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":210,"id":"exchange-082"},{"speaker":"林（宏）委員","kind":"意見","question":"もう少し様子を見るという部分がたくさんあるわけで、趣旨はわかります。ここにも、養護学校として残る要素もあり、もう少し経緯を見ていきたいということなんで、趣旨は受けとめますということで、意見書は提出しないということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":212,"id":"exchange-083"},{"speaker":"藤田委員","kind":"質問","question":"先ほど言いましたが、特別支援学校をつくるということですよね。ここにも書いてあるように、成人の方とか、ふれあいを高めたいとか、どういう中身でやるのかという、そういう議論が、品川区議会として、学校をつくってくださいという以上は、やっぱり何か具体的なものを我々も知っていなければいけないと思うんです。ですから、全体として、趣旨採択がいいんではないかという判断で、お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":213,"id":"exchange-084"},{"speaker":"沢田委員","kind":"意見","question":"率直に言えば、さっきも言ったことなんですけれども、不勉強で大変申しわけないですけれども、もうちょっと勉強したいと。だから、継続してもらえればと思うんですが、皆さんの意見を聞くと趣旨採択で、気持ちはよくわかりますから、趣旨採択で構わないと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":217,"id":"exchange-085"},{"speaker":"西本委員","kind":"質問・要望","question":"今後、いろいろと変化はあるかとは思うんですけれども、皆さんからの、このままで様子を見ていきたいという気持ちはわかるんですが、私が採択を主張した場合に、不採択という意味になってしまうんですね。そういうことがあれば、これは継続的に議論していっていただきたいという気持ちもありますので、ここで不採択ということはできませんので、趣旨採択という形でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":220,"id":"exchange-086"}]},{"id":"topic-05","title":"校舎改築校の工事状況","agenda":"校舎改築校の工事状況","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"簡単に。台場小学校のことでなくてもいいんですね。大崎地区のほうなんですけれども、２階平面図が一番わかりやすいかと思うんですけれども、グラウンドがあって、周りに緑色の、お昼休みや、すまいるスクールと、そうじゃない放課後の児童の遊び場、１年生から中学３年生までいるんですけれども、校庭というのは、どういうふうに使うのかなと。","respondent":"中島指導課長","answer":"もちろん、１年生から９年生までは、いろいろな形で放課後の校庭、体育館等を活用していくわけですので、現在、小中一貫校の準備委員会の中の学校運営部会というのがございまして、そちらのほうで、具体的に、有効的で安全な使用法について検討しています。","voiceIndex":228,"id":"exchange-087"}]},{"id":"topic-06","title":"平成１７年度小・中学校新１年生希望申請結果等","agenda":"平成１７年度小・中学校新１年生希望申請結果等","exchanges":[{"speaker":"林（宏）委員","kind":"質問","question":"一つだけいいですか。小学校のほうの、住民基本台帳による予定数２,１１７名が、平成１６年度に比較をすると約１４０人ぐらい増加というか、この傾向をどういうふうに見られておられるのか。１００人ずつ増えていくと、大変なことになりますので、教室数が。すまいるスクールをつぶすとか。１４０人ずつ増えていったら、大変なことになる、教室が足りなくなっちゃうんだから。","respondent":"谷田部学務課長","answer":"例えば平成２２年度に小学校に入る予定のお子さんといいますのは、今から６年後ですから、今年の４月１日現在集計したものでいきますと、０歳のお子さんが、住民基本台帳上２,２９２名いらっしゃる。","voiceIndex":235,"id":"exchange-088"},{"speaker":"中塚委員","kind":"質問","question":"これは申請数ですけれども、実際に、小学校に入学前に就学前健診を受けるわけですけれども、そこでの数というのが、実際に入学する数に大体イコールという話も聞きまして、実際に、今年１１月３０日までに区教育委員会の報告が上がるかとは思うんです、改めて教えていただけばと思うんですけれども、その時点で、小学校で１学級。","respondent":"谷田部学務課長","answer":"私ども、就学時健診については、希望する学校のほうで受診してくださいとお願いしてございまして、何人受診されたかという数字は、教育委員会のほうには来ていませんので、その数字については、ちょっとお知らせできないんですが、この表にお示ししているとおり。","voiceIndex":237,"id":"exchange-089"},{"speaker":"中塚委員","kind":"質問","question":"正確じゃないかもしれないけれども、聞いた話では６人ぐらいだったという話を伺ったんです。結局、選ぶときに、このまま減っていくとなくなっちゃうんじゃないかという不安の中で、じゃあ、確実なほうの大間窪小学校に行こうかという話も伺ったんで、質問したんですけれども、そういった声というのはつかんでいるのかどうか伺いたい。","respondent":"谷田部学務課長","answer":"学校選択については、導入して、小学校ではもう６回目になります。当初から、学校統廃合を目的にしているのではないかとかいろいろ言われていますけれども、これは本区の学校改革の一つの手段として行っているわけでして、その辺を十分にご理解いただきたいと思ってあります。","voiceIndex":239,"id":"exchange-090"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4522#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":60934,"voices":245}},{"id":"h16-20041129-5","meetingId":"h16-cm11","date":"2004年11月29日","dateIso":"2004-11-29","committee":"総務委員会","time":"午前１０時０６分～午後２時５９分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の第７３号議案、品川区情報公開・個人情報保護条例の一部を改正する条例","agenda":"の第７３号議案、品川区情報公開・個人情報保護条例の一部を改正する条例","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"３点ほど教えていただきたいと思います。違うんだよというのであれば、それでも構わないんだけれども、そういう絡みは、住基カードの中でも言えることなんだけれども、それと連動するのか、しないのか、それと逆に、認証を意図的にそういうことをして、それが表に出たり、見ちゃったりというのも、こういう罰則にあるのかどうか、それも教えていただきたい。３点お伺いします。","respondent":"中川原広報広聴課長","answer":"３点目ですけれども、住民票を持っていない住民の方について、その住民票があるかないかと問い合わせることは、個人の情報を特定するものではないかということであれば、もうちょっと具体的に要素を考えなければいけないんですが、さっき言った、存否応答拒否というのは。","voiceIndex":7,"id":"exchange-001"},{"speaker":"石田委員","kind":"質問・要望","question":"私も大変不勉強で、よくわからなかったんですが、一つは、先ほども言いましたように、罰則について、他区という話もあったし、物事の考え方もいいんですが、区民に広く周知をしなくてはならないというときは、それはそれとして、非常にそれは分かりますが、平成１７年４月以降、例えば事業者というお話があったけれども、事業者はしっかりそこでこういうことになりますよということを言えば、それは逆に。","respondent":"中尾根企画部長、中川原広報広聴課長、田中情報システム課長","answer":"後でいろいろあると思いますが、私のほうから、３番目のところをちょっと言います。周知期間についてですが、罰則につきましては、東京地方検察庁にも協議して決めたりとか、ある程度手続き的に。民生委員なら民生委員、その情報について、だれが、どう使ったかというようなことについて。","voiceIndex":9,"id":"exchange-002"},{"speaker":"土井委員","kind":"質問・要望","question":"それで言うと、法の部分にも当然運用上問題があった部分があるのかもしれませんけれども、その部分というのはどの部分なのかという、運用上条例に加筆すべきもの、これがいわゆる先ほどお話のあった、区独自の項目とイコールにつながっているのかどうなのか、その辺をちょっとお伺いしたい。それから、これをさっと読ませてもらったときに、存否応答拒否のところがよくわからないんです。","respondent":"中川原広報広聴課長","answer":"そのほか、私が説明した以外に、お渡ししました新旧対照表の中で改正点がありますが、それは以上のような４点の主な改正点を改正する中で、関連事項が出てまいりましたので、表頭を変えたものです。","voiceIndex":13,"id":"exchange-003"},{"speaker":"土井委員","kind":"意見","question":"こういうものを聞いてこられたら、これはわかりません、あるも、ないも言えませんということが決まっていなかったら、窓口ではどうしようもないですね。それはどうなっているのかということになりますね。もう一つは、先ほど言ったように、私のは教えないでくれと個人が言い出したときには、これは作用するのか、しないのかという、この２点。","respondent":"中川原広報広聴課長","answer":"存否応答拒否についての具体例というものが細かく定められているかということですが、これは１回お預かりして、中でそういった個別ごとの事例になりますので、協議をして決めていくということです。","voiceIndex":15,"id":"exchange-004"},{"speaker":"土井委員","kind":"質問","question":"そうすると、この考え方は、少なくともかなり大き目の考え方で窓口にも指示をしておかないと、答えてしまってから、後からそれはあるも、ないも言えませんという話になってしまってはまずいわけです。したがって、それは何か決めなければいけないんじゃないかと思うんですが、それはどういう形で、いつ、どこで、どんな形になっているんですか。","respondent":"中川原広報広聴課長","answer":"それを整理して、今度各課ごとにヒアリングを行って、その中でそういった情報の性質とか、そういった可能性があるものについては、その所属部分に存否応答拒否について適切に答えられるように、私どもとしても庁内の整理をしていきたいというふうに今準備を進めているところです。","voiceIndex":17,"id":"exchange-005"},{"speaker":"土井委員","kind":"質問","question":"そのためにも、考え方として、こういうものは応答拒否に値するものなんですよという大もとを示してあげないと、何でもかんでも拒否でも困るし、何でもかんでもパスも困るわけだから、ぜひそこら辺はうまく調整をしていただくということで、これはお願いをしておくしかしようがありませんね、運用上のあれですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-006"},{"speaker":"本田委員","kind":"質問・要望","question":"１つだけお尋ねしたいんですが、先日ＮＨＫで、この法改正に伴って、企業等の中でも情報漏えいが大問題になっているということで、社員を罰則するというのは当然ですが、もう一歩進めて、ファイルを持ち出したり、必要ないと思われるコピーを出したりということを、コンピュータを各人が持っているわけですけれども、それをコントロールすると言いますか、そういう操作を全部チェックするということで。","respondent":"田中情報システム課長","answer":"今ネットワークにつながっているパソコンが２,３００台ぐらいあるんですが、朝立ち上げてから、例えば統計の情報にしろ、個人の情報にしろ、ファイルにアクセスして、それが１枚プリントアウトしたのか、２枚、どういうファイルをやったのかというのをすべて記録して。","voiceIndex":20,"id":"exchange-007"},{"speaker":"本田委員","kind":"質問","question":"今の話を聞いて大変安心したといいますか、そうすると、庁内の２,３００台のパソコンは全部一元化されて、どういう使い方、今言ったように、例えば日曜日とか、土曜日とか、夜中とか、普通あり得ないところでコピーが出ているとか、何かしているということになれば、全部それはチェックされるというふうに、いつ頃そういうシステム化が完成するんですか。","respondent":"田中情報システム課長","answer":"最終的な決定に至っておりませんので、細かい詰めと検討を今進めているところです。","voiceIndex":22,"id":"exchange-008"},{"speaker":"宮崎委員","kind":"質問・要望","question":"１番のところの個人情報の種類の追加等についてよくわからないんですけれども、参考１というところで、Ａファイル、Ｂファイル、Ｃファイルそれぞれあるんですけれども、例えば民生委員の場合というふうな話があったんですけれども、具体的にどういうふうなものが想定されているのか、５００件以上とかというお話もあったんですけれども、具体的にどんなものがファイル簿になるのか。","respondent":"中川原広報広聴課長","answer":"迅速な処理とか、そういった面から、個人情報ファイル簿については一定の要件を設けて、こういったファイル簿にしていく予定です。","voiceIndex":25,"id":"exchange-009"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっと疑問なのは、例えばこういうファイル簿が公開されて、必要に迫られているということではないという感じなんでしょうか。これからこの条例でどんなものが出てくるかということで考えると。個人情報の保護の関連法が昨年５月に成立したということですけれども、何で今これをつくる必要があるかというのが、ちょっといまいちわからないんです。","respondent":"中川原広報広聴課長、中尾根企画部長","answer":"区役所はいろいろな個人の情報を広範にわたって持っているんですが、自分の情報が区役所にはどんな情報を持っているのかなというのがなかなか分かりにくくて、先ほど申し上げました、いろいろな権利を、利用停止とか。したがって、もともと区が所有する情報というのは何なのか、何を漏らしてはいけない情報なのか、これをはっきりさせなければもともとにならないということで、ファイル簿と、この体系をきちんとさせているです。","voiceIndex":27,"id":"exchange-010"},{"speaker":"宮崎委員","kind":"確認","question":"要するに、これには、こういうふうにしたら個人情報がとれますよという、とり方が書いてあるんですけれども、例えばさっきの民生委員の名簿というふうに仮定した場合、これは請求者が、今のお話ですと、自分の情報が正しく載っているかどうかということの確認ということだけではなくて、民生委員の名簿を見たいんだということでも請求できるということになるわけですよね。","respondent":"中川原広報広聴課長","answer":"今の民生委員の名簿を見たいというのは、自分の情報であれば、自己情報の開示になるんですけれども、一般的な民生委員の名簿が見たいということであれば、情報公開という形になって、区役所の保有する行政情報の公開という形になります。","voiceIndex":30,"id":"exchange-011"},{"speaker":"宮崎委員","kind":"質問","question":"今までは、例えば先ほど西口地区のあれも出たんですけれども、例えば来年２０歳ですよという方の名簿を見るときにも、出張所へ行って一々見ながら、この家は何年生まれだということを調べていましたけれども、具体的な例でいくと、例えば来年２０歳を迎える方の名簿を見たい、あるいは貸し付けの関係で見たいということになると、今まではどうで。","respondent":"中川原広報広聴課長","answer":"それが何人も情報公開の請求ができるんですね。個人情報のものについては、原則開示は難しいんです。個人情報は開示は原則は本人だけにするんですね。そういう意味で、ここにある個人情報ファイル簿というのを情報公開するのは、原則本人なんです。","voiceIndex":32,"id":"exchange-012"},{"speaker":"宮崎委員","kind":"確認","question":"ちょっと確認しますけれども、参考１のところで、個人情報の取得方法ということで、先ほどの説明だと、情報公開の手続きをやって下さいというふうなことだったんですが、そうではなくて、名簿に載っている個人でないと見れませんよと。ほかの地域の方の、例えば民生委員同士が連絡をとりたいのでということであれば、ほかの名簿も見れちゃうとか、そういうことはあるんですか。","respondent":"中川原広報広聴課長","answer":"情報公開と自己情報の開示は違うんですね。自己情報の開示の手続きというのは、情報が別ですので、情報ごとに沿って今回は説明をしていないので混乱があったかと思うんですが、自己情報の開示の手続きというのは、あくまで自分の情報についての開示の請求だけです。","voiceIndex":34,"id":"exchange-013"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、本人になりすまして請求をした場合には罰則がある。これで歯止めをかけているということですか。それが分かって過料だというふうになったときに、例えば氏名の公表なども含めて、大体そういうのが普通あるのかなと思うんですけれども、そういうのというのは、ここには５万円以下の過料というだけなんですけれども、何かこれで歯止めになるかなという気もするんです。","respondent":"榎本行財政改革担当課長","answer":"それに対して、今回はそれを罰則をもって防ごうという意味で、逆に、罰則をかけるときには、先ほど企画部長が説明したように、どの情報を漏らしたら罰則なのかというのをきちんと精査する意味で、罰則規定を設けたということで、今回過料の５万円というのは。","voiceIndex":36,"id":"exchange-014"},{"speaker":"宮崎委員","kind":"意見","question":"５万円の過料が自治体としては最高なんだということです。そもそもファイル、こういう名簿もありますよと。今までそういうのはなかったわけですね。こういう名簿を見ようと思えばありますよ。それをお知らせするという意味というのは何なのか。","respondent":"中川原広報広聴課長","answer":"内部としては、罰則も設けて、こういったものをきちんと適正管理していくんだということを、本人と、行政の内部に向けてしっかり確認をするためのツールと言ったら変ですけれども、道具としてこれをきちんとつくりなさいということが、法律の中で、各自治体に認識したものです。","voiceIndex":38,"id":"exchange-015"},{"speaker":"若林委員","kind":"確認","question":"参考のところに個人情報ファイル簿とあるんですが、ここには個人情報が入らないんだというご説明がさっきあったと思うんです。これは個人情報が入らないというのであれば、例えば今いろいろお話を聞いている中で、いまだにごちゃごちゃしているんですが、名称を、本人確認ファイルとかいう、そういう考え方はないんですか。","respondent":"中川原広報広聴課長","answer":"そうすると、そこで氏名、住所、電話番号を見たところ、電話番号に間違いがあったということであれば、この電話番号は違っていますよということで、自分の自己情報を訂正して下さいと、広報広聴課のほうに言えるというのが。","voiceIndex":40,"id":"exchange-016"},{"speaker":"若林委員","kind":"質問・要望","question":"最後に、これは平成１７年４月１日に施行ですので、これから広く区民の皆さんに広報広聴されるということですが、ぜひ分かりやすく、文字でやると、いまだにこの中でも理解するのに随分差があると思うんです。どのようにされていくか、一応お考えをお聞かせいただきたいと思います。","respondent":"中川原広報広聴課長","answer":"基本的には広報紙ということで考えておりますが、今日ご質問を受けて、非常に説明が難しかった部分、分かりずらかった部分を分かりやすくして、区民の方に身近な例でお知らせできるように努力したいというふうに思っております。","voiceIndex":42,"id":"exchange-017"},{"speaker":"宮崎委員","kind":"意見","question":"住基ネットとの関係ですけれども、これはどういうふうになっているのか。このファイル自身がホームページ上での公開をされるのかどうなのか。","respondent":"田中情報システム課長、中川原広報広聴課長","answer":"一般的な区の個人情報ファイル、自己情報に係わるところは、これはこちらの条例に基づいてやられることになります。法律が優先されて、そちらの法律で規定されている部分についてはそちらのほうで手続きをしてもらうという形になります。個人情報ファイル簿の公開の方法ですけれども、情報公開の対象のファイル基準表として区政資料コーナーに置いてありますので、それと同様にファイル簿につきましても、区政資料コーナーのほうに設置することをまず考えてあります。","voiceIndex":46,"id":"exchange-018"},{"speaker":"宮崎委員","kind":"質問","question":"区政コーナーに設置するということですけれども、条例上ではそれはホームページに載せないということになっているんでしょうか。","respondent":"中川原広報広聴課長","answer":"公表の仕方については、条例事項ではございませんので、運用のほうで考えていきたいと思ってあります。","voiceIndex":49,"id":"exchange-019"},{"speaker":"宮崎委員","kind":"質問","question":"最後に１点ですけれども、個人の情報ですけれども、いろいろな角度から名簿が見れるよというふうになっているんですけれども、例えばさっきの民生委員ということで、こういう名簿がありますということですが、そもそも情報というのは、個人情報が一つ全部まとまっている中からそうやって必要な情報が検索されていくのか、それとも一つ一つの名簿があって、そこからファイルというふうになっていくのか。","respondent":"中川原広報広聴課長","answer":"ファイルが存在するかどうかというのがまず大事な情報で、存在したとすれば、その中に個人の情報がどういう項目が入れられているかという、そういう順番に検索はなされていきます。","voiceIndex":51,"id":"exchange-020"},{"speaker":"宮崎委員","kind":"意見","question":"先ほど広報広聴課長のほうからいろいろ具体例ということで、もうちょっと区民に分かりやすい説明というふうなお話だったんですけれども、私は、できたら、そういうものは今日この場所にあったほうがよかったんじゃないかというふうに思われてしようがないんですけれども、いずれにしても、説明を受けても、まだよく理解できないんですよね。それを見て判断できないものかと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":53,"id":"exchange-021"},{"speaker":"宮崎委員","kind":"質問","question":"今の件で、例えば午後に用意ができるとか、何かあれば、ちょっとお願いしたいと思うんです。私自身がまだこなれない部分もあるので、どうでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-022"},{"speaker":"宮崎委員","kind":"意見","question":"かえって情報をとりやすくしてしまうのではないか、本人になりすましてとった場合には５万円以下の過料というふうになっているんですけれども、私はこれで抑止力になるのかなというふうに思いますし、ある意味では、そういう名簿が出た場合に、こんなことを考えるんですけれども、それなどもこういう名簿はこういうふうにそろえてありますよというふうに、わざわざやること自体が。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":59,"id":"exchange-023"}]},{"id":"topic-02","title":"の第７５号議案、戸越幹線貯留管整備工事その２請負契約","agenda":"の第７５号議案、戸越幹線貯留管整備工事その２請負契約","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"なぜかというと、先ほど右岸工事のところへ行って、大成・松本はそれはそれでいいんだけれども、これもよく見ると、大成・松本で同じように組んでいるなと思ったので、今回の組み方とか、要件というのはどういうふうにやられたのかというところだけ分かれば教えていただきたいと思います。","respondent":"鷹倉経理課長、矢部下水道河川課長","answer":"具体的に言いますと、第１グループについては６社、第２グループについては８社という形で、若干数字が違う形になったわけですけれども、その数字を示す中で、それぞれ手を挙げられた１グループ、２グループ。それなものですから、品川区のほうでは工事の区切りがいいところということで、３年債にならない範囲内で一次巻き工事までをその２工事として一つの工事、それ以降をその３工事として一つの工事という形でやっているところです。","voiceIndex":72,"id":"exchange-024"},{"speaker":"石田委員","kind":"質問・要望","question":"最後のところでちょっとお聞きしたいんだけれども、２年債までしか東京都が認めてくれないという、それだとするならば、それはそれで決まりがあるからしようがないんですが、工事的に、例えばそれのほうがいいのか、あとは金額が安くて済むというのがもしそこにあるとするなら、逆に、２年債まで認めてくれないということ自体がおかしいという話をしたほうがいいんじゃないかなと思うんですが、そこら辺の。","respondent":"鷹倉経理課長、矢部下水道河川課長","answer":"グループ分けのところの考え方は、先ほど申し上げましたけれども、ちょっと話をしますと、これはあくまでも第１グループ、第２グループの名簿をお示しして、それぞれがそれぞれの相手方を主体的に検討をされてやっているということです。今のところ単年度主義が原則なんだけれども、２年債までは認めようという中で工事をやらせていただいております。そういうことで、３年債は今の状態では難しい。","voiceIndex":75,"id":"exchange-025"},{"speaker":"石田委員","kind":"質問・要望","question":"これはお願いしておきますが、ほかの場面でも、ゼロ債のときに１回こういう、またぐ、またがないの話があったかと思うんですが、今の２年債とかというのは、してもらった、単年度で分かるんですが、かかるものはかかるわけですから、こういう議論は、ゼロ債のときも含めていろいろ話がありましたが、ぜひこういうのはちょっとおかしいというような、単年度は分かりますが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-026"},{"speaker":"宮崎委員","kind":"質問","question":"今回の台風２３号のところ、戸越のほうは被害があったかと思います。５０mmの８０％の流入という説明ですけれども、例えばこの前の台風２３号クラスのものですと、これはまだ稼働をしていませんけれども、稼働をした場合にはどのくらいの水が貯留されるのか。この前の台風２３号クラスがきたと想定すると、本管のほうに流れる水がどれぐらい軽減されるのかということを教えて下さい。","respondent":"矢部下水道河川課長","answer":"約２,３００ｔの貯留能力があるんですけれども、そこにつきましては、今までに去年、今年と３回貯留がされているんですが、２,３００ｔのうちの６００ｔぐらいたまっただけでも浸水被害が出なかったというような形の報告がなされて、貯留量関係なしにして。","voiceIndex":81,"id":"exchange-027"},{"speaker":"若林委員","kind":"質問・要望","question":"関連して、横断歩道の話がございました。中学校を背にして右側にというお話でございましたが、地元の方のお話ですと、左側にはできないのかという声があるらしいんですが、地元の方、地域の方のご要望はどのように、右側にしたという見方がありますでしょうか。","respondent":"矢部下水道河川課長","answer":"事前にこの前事業説明会をすでにやっておりますけれども、それ以外に町会の役員の方とお話をしておりますが、横断歩道の信号機の移設、右左の話というのは、ちょっと私どものほうで要望は聞いておりません。","voiceIndex":83,"id":"exchange-028"},{"speaker":"若林委員","kind":"質問","question":"今回、その２で、２年債で１回切れるという言い方で正しいのか、その３になったときには、契約は、再び入札という話にはならないと思うんですが、そこら辺の整合性を教えていただければと思います。","respondent":"鷹倉経理課長","answer":"その３は来年度以降ですが、先ほど下水道河川課長が申し上げているとおり、その２と、その３は一体的に、経費的にもきちっと整合性のとれるような形でやっていくということであれば、一定のその種の契約、随意契約等を検討していく必要があろうかなというふうに考えてあります。","voiceIndex":85,"id":"exchange-029"}]},{"id":"topic-03","title":"平成１６年請願第２６号、郵政事業の民営化に関する請願","agenda":"平成１６年請願第２６号、郵政事業の民営化に関する請願","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"分かったら教えていただきたいんですが、請願趣旨の５行目、「各自治体との連携により住民票や納税証明書等の交付事務を行うなど」ということですが、もちろん品川区はやっていないのは分かっているんですが、こういうことをしている自治体もあると思うんです。","respondent":"榎本行財政改革担当課長","answer":"それ以外にも、例えばそういう市町村と連携した行政サービスということで、郵便局の窓口でのバスの回数券の販売ですとか、それが１５４市町村の９１２局で行っております。","voiceIndex":94,"id":"exchange-030"},{"speaker":"石田委員","kind":"質問・要望","question":"これはもう決定しているらしいんですが、すべて指定庁にして、５年後ぐらいにオンライン申請までできるようにしていくという考え方は考え方ですから構いませんが、区民サービスのことを考えると、品川区の法務局はああいうことを考えていると、郵便局でそういうところも担ってもらわなくては、もちろん鵜の木になるという話が出てくると、品川区のサービスを考えると。","respondent":"榎本行財政改革担当課長","answer":"要は、今よりサービスが落ちてしまっては何もならないというのが、一番住民の方の率直な意見ですので、そうならないような形で郵便局というものが活用できていかないと、なかなか全体のものというのはうまく、切り分けできないし。","voiceIndex":96,"id":"exchange-031"},{"speaker":"石田委員","kind":"質問・要望","question":"そのかわり民意を十分反映して、民営化を拙速にというのはその部分だと思うんで、民営化を拙速に進めると、特に品川区は今そんな状態の話があるときにごちゃごちゃになっちゃうような気がするし、そういう意味では、品川区にとってもこういう形のものは訴えていくべきところには訴えていくほうがいいのかなと思って、それは要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-032"},{"speaker":"本田委員","kind":"質問","question":"国民の十分な理解と、よく知るという、郵政事業というのは大変な事業ですから、そういう意味の意見書を出すということは、これはよろしいんじゃないかなというふうに私は思いますので、紹介議員に私はなっておりませんけれども、賛成をしますので、できれば今日、採択をしてはどうかというふうに思うんですが、意見を申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-033"},{"speaker":"土井委員","kind":"質問・要望","question":"僕もこれを聞かれたら、とても知っているとは答えられない。それから、郵便局の問題というのは全国一律の郵便の問題であるとか、保険や、貯金にしても、民営との関係も含めて、どう処理をするのか。ここでおっしゃっている、よく説明をして、よく理解を求めて、やってもらわないといけないですよというのは、もう当たり前のことなんでね。ぜひ通していただきたいと、こんなふうに思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":100,"id":"exchange-034"},{"speaker":"宮崎委員","kind":"意見","question":"うちのほうも、特に今回出されています採算性重視というふうなところ、郵便事業がどうなっていくんだと。多くの国民の心配でもありますし、郵便事業だけでなくて、簡保とか、郵貯とか、こっちの事業もどうなっていくんだ。これが心配なんですけれども、ここでは十分民意を反映して拙速に進めるなと、そういうことで意見を出してほしいということなので、ぜひこれはやっていこうというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":101,"id":"exchange-035"}]},{"id":"topic-04","title":"平成１６年請願第３０号、劣化ウラン兵器禁止に関する意見書提出を求める請願","agenda":"平成１６年請願第３０号、劣化ウラン兵器禁止に関する意見書提出を求める請願","exchanges":[{"speaker":"石田委員","kind":"質問","question":"全体的にいろいろなもっとやらなくてはならない、整理しなければならない部分があるのではないのかなと考えています。ですから、そういう形の中で、これだけを取り上げてという形は、我々としてはなかなか解せないなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":111,"id":"exchange-036"},{"speaker":"土井委員","kind":"意見","question":"私どももいろいろ議論をいたしました。区民の皆さん、国民の皆さんがいろいろ考えるときに、それぞれ出てきた事象をどう捉えるかという形で、その事象、事象によって取り組みを考えられて、いろいろとこういう請願や陳情という形も含めて出てくるんだろうなと。その意味で、何らかの形でこの趣旨が生かされるようにしていただければありがたいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":112,"id":"exchange-037"},{"speaker":"宮崎委員","kind":"質問","question":"劣化ウランで被弾した戦車、イラクとか、あるいはアフガニスタンとかいろいろ使われたと。私もそう思います。ところが、今アメリカの大きいところで、核の廃棄の約束自体がどうなっていくのかというふうな心配があります。ですから、今回劣化ウランということで限定されていますけれども、これはこれでなくそうという運動は賛成できますし、この趣旨を生かして採択できればいいなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":113,"id":"exchange-038"},{"speaker":"本田委員","kind":"意見","question":"しかも、比重は重いということで、いろいろな記事を読んで、対戦車砲に、砂漠とか、半島といいますか、陸上戦に有効な兵器なんだろうなというふうに思うわけですけれども、品川区民からそういうものをなくそうという請願が上がるというのに、ちょっと奇異な感じも私はしたんですけれども、こういう新しい兵器を使って、そういう行為が行われているということについて、平和的な観点から。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":114,"id":"exchange-039"},{"speaker":"若林委員","kind":"意見","question":"ただ、別紙で、署名に協力して下さいという中で、参考人の物理学者が、特別措置法の特別委員会で意見を出されて、その全文を見させていただいて、これは抜粋になっておりますが、表に出てくる文面では、私は大変にそのとおりだと思うんですが、表に出る前の全体像として、例えば今のイラク戦争に日本が加担をして、そういうことはやめるべきだというような、国として決議をして。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":115,"id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1670#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":42690,"voices":121}},{"id":"h16-20041130-6","meetingId":"h16-cm11","date":"2004年11月30日","dateIso":"2004-11-30","committee":"区民委員会","time":"午前１０時０４分～午前１１時３５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"１番目の、特別円滑化資金の実施結果","agenda":"１番目の、特別円滑化資金の実施結果","exchanges":[{"speaker":"原委員","kind":"質問","question":"一つだけ。今、ご説明があった中の、追加の借入れは、全体の中でどのぐらいの割合を占めているんですか。追加だと５００万円になるわけですが、その辺のところは、全体で実行された中の何パーセンテージぐらいなんでしょうか。","respondent":"日下部産業振興課長","answer":"実は、すべての案件に当たりまして、追加の融資を受けたということで申込みを受けております。金額にしましては、５００万円の上限のところ３６０万円ということでありますので、利用としましては７割程度ということになってまいります。","voiceIndex":6,"id":"exchange-001"},{"speaker":"山路委員","kind":"質問","question":"１件不実行ということなんですけれども、その原因をちょっと教えてください。","respondent":"日下部産業振興課長","answer":"相談の段階ではわからなかったんですが、要するに代表者がＡ社、Ｂ社と複数の会社を持っておりまして、実際の申込みはＡ社の関係の申込みであったんですが、実は、Ｂ社の関係で借入れがございまして、これについて融資条件の変更が途中でなされたということで。","voiceIndex":8,"id":"exchange-002"},{"speaker":"藤原委員","kind":"質問・要望","question":"一本化できるという施策は、区で初めてだと思うんですけれども、まず初期の予想を６０件ぐらいに見ていたという根拠と、この説明を受けたときに、すごくいいなと思いました。私は、６２件というのは少ないんじゃないかなと思うんですけれども、その辺について、何か説明があったらしていただきたいんです。","respondent":"日下部産業振興課長","answer":"私ども、いろいろ調べた範囲でも、とにかく実際の対象者は大体５％で、おそらく最大でも１０％までいかないだろうと、そんな状況でありまして、私どもとしましては、対象になる方は全体で約１,０００件ほどでありますから、そのうちの６％ぐらいということで見込みましたら。","voiceIndex":12,"id":"exchange-003"},{"speaker":"藤原委員","kind":"質問","question":"他区の事例を見て５％ぐらいだから、大体当たったというのはわかるんですが、５％ぐらいしか利用しない、金融機関が勧めなければ、もっとパーセンテージが減っただろうという施策なんですが、今後もこの施策はやっていくんですか。それとも、もうやらないんでしょうか。","respondent":"日下部産業振興課長","answer":"つまり、負担の先送り、あるいは、これが続きますと、金融機関の信用の低下とか、いろいろそういう問題も出てまいりますので、そういったこともやはり総合的に勘案をいたしまして、今回はこれで打ち切りということで判断をしたわけです。","voiceIndex":14,"id":"exchange-004"}]},{"id":"topic-02","title":"２番目の（仮称）天王洲創業支援施設の入居者募集","agenda":"２番目の（仮称）天王洲創業支援施設の入居者募集","exchanges":[{"speaker":"菊地委員","kind":"質問・要望","question":"実際にそういうふうに持っておられるところで、中小企業ですから、十分にそのものもごくわずか、２０名ですか、ちょっとどこが基準になっているかわからないけれども、そういうところの創業支援という考え方と、本来、最初から起業しようとするときの支援。","respondent":"日下部産業振興課長","answer":"私どもも、基本的には、そういうような考え方をベースにしまして、やっぱり品川区内の中小企業の活性化、いろいろと厳しい状況に置かれているわけですが、既に経営基盤はありつつも、やっぱり新しい事業展開によりまして、例えば、さらに事業力の確保の問題とか。","voiceIndex":21,"id":"exchange-005"},{"speaker":"藤原委員","kind":"質問","question":"東京商工会議所より切実な願いがあったというところから、この１０室が満室になると思うんですけれども、審査をする基準といいますか、審査方法、どういうふうになっているんでしょうか。","respondent":"日下部産業振興課長","answer":"審査の基準といたしましては、先ほどもちょっとご説明させていただきましたけれども、中小製造業、それから関連業種ということで、例えばソフト関係も含めて、情報通信も、そういったものであれば幅広く対象にしていきたいと考えております。","voiceIndex":23,"id":"exchange-006"},{"speaker":"山村委員","kind":"質問","question":"公募委員で、大学生が３人、高校生が４人、中学生が６人ということなんですが、これは公募ということですから、この人たちが自分で応募してきたのか。どういう形で募集したのか教えてください。","respondent":"金井環境課長","answer":"実は、中学生につきましては、学校のほうに依頼をしまして、学校を通じて来ていただいた。一般募集は行ったわけですが、大学生、高校生は来ておりますけれども、中学生は一人も来ておりません。","voiceIndex":31,"id":"exchange-007"},{"speaker":"山村委員","kind":"質問・要望","question":"環境プログラム作成分科会と、イベント分科会、中・高校生の育成で、出ている委員が２１名、２８名、１９名とあるんですけれども、この中で、学生がどのぐらい出ているか教えていただきたい。","respondent":"金井環境課長","answer":"高校生と大学生という状況です。","voiceIndex":39,"id":"exchange-008"},{"speaker":"山村委員","kind":"質問","question":"大学生、高校生、中学生をこの活動推進会議の委員にしようと思ったというか、ある程度、最初から入れようと思ったんだと思うんですけれども、その理由を教えてください。","respondent":"金井環境課長","answer":"ご案内のとおり、今の環境問題というのは将来世代に大きな影響を及ぼすということで、やっぱり子どもたち、若者の環境の育成をしよう、意識を高めていただこうということで、当初から、中・高校生、大学生等を入れようという計画で進めてまいりました。","voiceIndex":43,"id":"exchange-009"},{"speaker":"山村委員","kind":"質問","question":"ちょっと話は変わりますが、これでできて、なぜ青少年健全育成とか、そういうのでは学生を入れないのか、よくわからない。青少年対策地区委員会とか、そういうのにこそ学生を入れるべきじゃないかと、私は常々思うんですが、そこら辺のご意見を教えてください。","respondent":"金井環境課長","answer":"それぞれ事情があろうかと思います。","voiceIndex":45,"id":"exchange-010"},{"speaker":"山村委員","kind":"質問・要望","question":"これを見て、青少年対策のほうの方がどう思うのか、教えていただきたい。","respondent":"田村地域活動課長","answer":"今、環境課長のほうから答弁があったように、一定のプログラムの分科会とか、検討とかをするので、やっぱり中学生以外に高校生、大学生ということで、きのうもお話のあった青少年の健全育成も、小学校は一部の地域ではやっていますけれども、中学校でということで。","voiceIndex":47,"id":"exchange-011"},{"speaker":"山村委員","kind":"質問","question":"そうすると、学校の意見はあまり要らないということですか。中・高校生は当事者として必要だと思うんですけれども、町会長よりは、自分たちの方がわかっているんだから。かなり世代の隔たりがあるから、無理があると、私は出ていて感覚的に思うんですけれども。","respondent":"田村地域活動課長","answer":"ですから、そういう意味からすれば十分に、実際にお子さんの声を直接聞かなくても、そういうものを踏まえた議論ができるのかなと考えています。","voiceIndex":51,"id":"exchange-012"},{"speaker":"山村委員","kind":"質問・要望","question":"それができていれば、非行も何も起きないと思うので、常にふだんから話ができている状況なら、非行も起こりませんし、地域とのかかわり合いなんか考えなくても、できていると思うんです。要望として、少しはそういうことも考えていただければなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-013"},{"speaker":"井上委員","kind":"質問","question":"環境プログラム作成のことについてなんですけれども、私の認識なんですけれども、設置目的のところに、「人々と協働して進めていくことを目的に設置」ということで、広く区民の方たちと協働して進めていくために、この会を設置して、行動計画をつくるという認識に立って質問をするんですが、そこにところの設置目的は、それでいいんでしょうか。","respondent":"金井環境課長","answer":"実際に、これからの環境問題をどう地域に広げていくか、どう知識を深めてもらうか、あるいは、いろいろ体験してもらうかというのが、今、大事な時期だろうと思いますので、そういったプログラムを、まずはみんなで協働して。","voiceIndex":54,"id":"exchange-014"},{"speaker":"井上委員","kind":"質問","question":"その実践プログラムをつくった上で、そのことを、この推進委員会の人たちが進めるわけではなくて、それを広く外に向けて、そのプログラムで実践して、皆さん、やりましょうね、というところなんですか。環境プログラムというものの位置づけがよくわからないんですけれども。","respondent":"金井環境課長","answer":"そのできたプログラムが、例えば学校で使えないか、地域で使えないかとか、要望があった時に紹介はできないかとか、そういう広がりをあわせて考えております。まだまだそこまでは相当遠いんですが、最終的には、そういうことをイメージとして、今、検討しています。","voiceIndex":56,"id":"exchange-015"},{"speaker":"井上委員","kind":"質問","question":"そうではなくて、この方たちはそれなりにそういうプロセスを学びながら、地域のリーダーとして育っていってほしいということなので、今回は推進会議の活動状況の報告ということなんですけれども、実際に環境計画をどう進めていくか、重点項目として、５年をめどにそこを実施するという計画がありますけれども、そこのところはどういうふうに、実際に、何をどうしていこうかということの働きかけとか。","respondent":"金井環境課長","answer":"実施計画で取り組もうということになれば、当然、予算も措置されて、それが実際の行動計画的なものとして実践されているわけです、計画的に進められます。","voiceIndex":58,"id":"exchange-016"},{"speaker":"井上委員","kind":"質問","question":"こういう方たちが講師になっていくという、そこでいい発想があれば、計画に反映できるということをおっしゃっていたので、その中では、その区民の声というのは取り入れられているという認識であるかもしれないんですけれど、広く区民の声というところでは、もっとこの計画に対して、この方たちが外に出て、こういうプログラムを考えているんだけれども、皆さん、どうですかという、そこに反映できるものとか。","respondent":"金井環境課長","answer":"委員の考え方というのは、この中に入っています。ただし、そこまでいくには、相当な時間と、やはりこの委員がそれなりの知識を深めたり、体験もいろいろ経験されないと、なかなかそこまではいかないと思うんですが、いずれにいたしましても、そういう方向では考えております。","voiceIndex":60,"id":"exchange-017"},{"speaker":"井上委員","kind":"質問・要望","question":"環境計画に対して、もっと大きなところで、品川区がやろうとしているものはこういうものなんだということを、品川区が特におっしゃっている１３地域というそういう地域ごとの特性も生かしながら、地域エリアの環境に対する思いというのも、たったこの品川区のエリアの中でも、それぞれ違うと思われている人たちもいらっしゃるので、そういうところでは、外にこういう計画であるということを説明するとか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2412#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":14879,"voices":74}},{"id":"h16-20041130-7","meetingId":"h16-cm11","date":"2004年11月30日","dateIso":"2004-11-30","committee":"厚生委員会","time":"午前１０時０５分～午後３時０５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を73件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"先日歯科医師会とともにやっている８０２０の顕彰式に参加をさせていただいたんですが、つくづく歯の健康というのが大事だなと、歯の丈夫な方というのはほんとうに表情も明るくて、この方たちが８０歳以上なんだろうかと思うくらいお元気な方々ばかりで、私も歯を大事にしなくちゃいけないなと思っているんですが、なかなかこの成人歯科の健診に行かれなくて反省ばかりしているんですけれども、今回６５歳。","respondent":"田中健康課長","answer":"８０歳になるまでの節目にということで健診を各自治体でも検討するようにという内容ですので、今高齢の方はどんどん増えておりまして、９５歳、１００歳の方もいらっしゃるかと思いますが、当面私ども、この厚生労働省での一つの方針を受けて。","voiceIndex":5,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ今後拡大の方向でいっていただきたいなと、これは要望ですけれども。それから、周知について、広報紙および契約医療機関でのポスターの掲示ということがあるんですけれども、以前にもちょっと触れさせていただいたんですが、この契約医療機関というのは、品川区内のすべての歯医者さんではないですよね。契約されていないところにどういう機関があるのか、ちょっと教えていただきたいんですが。","respondent":"田中健康課長","answer":"私ども、いわゆる医療全般的なものとは違いまして、健診というのは、区民健診等も含めまして、区としてこういうものを区民の方の健康維持にということで、しかも同じですけども、項目ですとか内容ですとか、そういうものを決めさせていただいて。","voiceIndex":7,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"以前お伺いしたら、歯医者さんのほうはちょっとわからないんですが、３割ぐらい入っていらっしゃらない方が、そういう状況、その辺を教えていただきたいのと、区民の方で医師会に入っているとか入っていないとか、そういう感覚はあまりないと思うんですね。そういった面で、受診をされたりするんで、その辺の差があるというところで、ご意見なんかが届いているかどうか、もしあったら教えてください。","respondent":"田中健康課長","answer":"歯科関係につきましては特に聞いてはございませんが、私ども医のほうで、高齢者インフルエンザにつきまして医師会の方から要望がございまして、それはある一定程度高齢者インフルエンザは、いわゆる東京都を含めた中で実施している共通のものですので。","voiceIndex":9,"id":"exchange-003"},{"speaker":"嶋委員","kind":"質問","question":"それで、こういう形で受診率みたいなものを広報紙とか、契約機関でのポスターというと、何かすごく周知がまだまだ足りないのかなと思うんですが、そこら辺のお考えと、２番目の歯周疾患なんですけど、これの内容と、やはりこれも３月、３カ月、あと場所も歯医者がみんなやられるのか、そこら辺をお聞きしたいと思います。","respondent":"田中健康課長","answer":"それにつきまして、９５８名の方が受診をいただいてあります。それで、広報の方法なんですけれども、この歯科健診につきましては、６月から３月ということで実施をしてございまして、４カ月、５カ月の間にいろんなことを調整するという内容になってあります。","voiceIndex":11,"id":"exchange-004"},{"speaker":"嶋委員","kind":"質問・要望","question":"検証する場があるということで、こういうのは声を皆さんに口から口へじゃないけども、伝えていってもらいたいなと思っていましたので、ぜひこういう声とか、もし何か喜びの声を、これがというのがあったらお聞かせいただきたいと思います。","respondent":"田中健康課長","answer":"１５年がちょっと減って２９名ということなので、実は４０歳以上の方は治療に行く方のほうがむしろ多いという判断がありまして、どの程度治療じゃなくて改善指導かというところが難しいところなんですが、これは各診療所の先生方が判断をし。","voiceIndex":15,"id":"exchange-005"},{"speaker":"築舘委員","kind":"質問","question":"受診率というんですか、２万３,５１８名が対象者なんですけど、９５８名しか受けていないということで今お答えがあったんですが、どうしても治療に行く人が、もちろん痛くならないとなかなか行かないという、私なんかもそうなんですが、そういう方が多いということもあって、何でもないのに受診するというのはなかなか難しいかもしれないんですけど、そのためにも。","respondent":"田中健康課長","answer":"４５歳、５０歳、５５歳といいますと、私どもも一番最後のころなんですが、なかなか関心が実は自分自身向いていないというかあれですので、ＰＲには今後とも努めていきたいというふうに考えてあります。","voiceIndex":17,"id":"exchange-006"},{"speaker":"本多委員","kind":"質問","question":"ちょっと重複するんですが、区がやっている健診全般を見て、この歯科に限らず健診自体、おそらくリピーターといいますか、毎年やっているという傾向があると思うんですが、その辺から見て、この歯科健診の５歳刻みということは当然財源に限りがあるので妥当な方法だと思うんですが、その辺のリピーターを引きつけるといいますか、その辺についてはどのようなお考えでしょうか。","respondent":"田中健康課長","answer":"ただ、これは全国的な健診の中で、先ほども申し上げた厚生労働省のほうも、いろんな財源も含めてここはなるべくこういう形でやってほしいよということが今度の７０歳までの部分も増えてきて、私どもとしては対応するというというふうに認識しておりますが。","voiceIndex":19,"id":"exchange-007"},{"speaker":"武内委員","kind":"質問","question":"１月から３月末までのモデル的に拡大ということなんですけど、例えば受診率が低いとか、あまりニーズがないような場合にはそこで打ち切るようなことも可能性としてあるんでしょうか。","respondent":"田中健康課長","answer":"あくまで高齢の方が増えてまいりますので、そういう中でどんな問題が生じるかというのは一応医師会の傘下の診療所の先生方とも実態の議論をさせていただきながらとは思ってありますが、一たんやはり方向性としてと思ってありますので。","voiceIndex":21,"id":"exchange-008"},{"speaker":"本間委員","kind":"質問","question":"既に出たお話の繰り返しの部分も出てくると思いますけども、一言だけお願いします。これは年代的に見て、率直な感想を持ちますと、結局土曜日とか日曜日とかというのはお医者さんはやっていませんよね。公募健診ながら個別の案内もしますというようなことを言われましたけど、広報紙、医療機関、ポスター掲示のほかに個別の案内というのはどのような方法をとられているのでしょうか教えてください。","respondent":"田中健康課長","answer":"ただ、やはり、皆さんに５歳刻みということもありまして、関心を持っていただいて、ご自分でぜひ機関のほうに健診を受けに来ていただくというあたりは、やはり、ますますＰＲを私どもとしても努力すべきかなというふうに考えてあります。","voiceIndex":23,"id":"exchange-009"},{"speaker":"本間委員","kind":"質問","question":"いろいろデータをこちらで調べてくればよかったんですが、その部分がないので大変申しわけないんですけども、これまでの実績として受診率が出ていましたけれども、そのことによってかかっている費用、それから今後かかるであろう予算的な措置といいますか見積もり、これはモデル事業ですので、本格実施はその後になると思いますが、その辺の部分、今の段階で把握されているのでありましたら教えてください。","respondent":"田中健康課長","answer":"といいますのは、現行ですと、予算的には歳出が９６０万円程度考えてございまして、今回、あくまで推計的な受診の率なんですけど、１００万円程度の歳出というふうに上乗せを考えてありますが、あくまでシミュレーションですけども、現行。","voiceIndex":25,"id":"exchange-010"},{"speaker":"本間委員","kind":"質問・要望","question":"モデル的に年齢を拡大するということで、いよいよ間近に本格実施の事業となると思われますので、あらゆるそういう足りない部分、これまでの反省点を踏まえながら、せっかくこういうよいものが立ち上がって、続いていく部分があるわけですので、国の補助金等ともいろいろ勘案してですけど、さらに一層受診率が上がってくるような方法をまた動きながら考えていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-011"},{"speaker":"嶋委員","kind":"質問・要望","question":"これは大変やっぱりすばらしい事業だと思うので頑張っていただきたいんですが、これは２３区でやっているのか、品川区独自でやっているのか、ちょっとそこら辺のことをお聞かせいただきたいと思います。","respondent":"田中健康課長","answer":"基準は先ほど申し上げました厚生労働省が示している４０歳、５０歳という１０歳刻みのほうの制度で運用しているところが多いかなというふうに思ってあります。","voiceIndex":28,"id":"exchange-012"},{"speaker":"嶋委員","kind":"質問・要望","question":"要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-013"},{"speaker":"南副委員長","kind":"質問・要望","question":"受診する年齢が５歳刻みでなかなか忘れがちだとかということで、先ほども受診数が二万三千五百数人に対して９５８人だということで、１割にも全然満たないという状況ですから、やっぱりここをどう引き上げるかという努力が大事かなというふうに思っているんですが、受診者の年齢的な内訳というんでしょうか、その辺をちょっと教えていただきたいというふうに思います。","respondent":"田中健康課長、平野品川区保健センター保健サービス課長","answer":"それから成人歯科の関係では、歯周病の予防教室等を保健所等でもやってありますし、いろんな形でブラッシングなり、こういう予防対策というのはいろんなところで、いろんな方法を構えているわけなんですが。歯科ではありませんけど、医学的な部分もありますので、私どもの歯科衛生士等がどう指導しているかということについて申しますと、電動歯ブラシは障害があったりして、手麻痺があるような方には非常に有効だと思いますけれど。","voiceIndex":31,"id":"exchange-014"},{"speaker":"南副委員長","kind":"質問・要望","question":"さっきちょっと伺った９５８名で前進させていく姿勢はお持ちだろうと思うけども、その辺の見解をちょっと伺ったんですが、答弁がなかったので改めてお聞かせをいただきたいと思います。それで、やっぱりざっと先ほど受診数を紹介していただきましたけども、４０歳が２６３人というのは、私としては意外だった。先ほどのところをちょっと教えてください。","respondent":"田中健康課長","answer":"ただ、この１０月からかかりつけ歯科医制度をスタートさせていただきまして、例えば女性の先生がいるところとか、いろんな形の紹介ができる制度もつくられましたので、そこでかかりつけの先生を見つけていただいて。","voiceIndex":34,"id":"exchange-015"},{"speaker":"南副委員長","kind":"質問・要望","question":"そういうふうにしてくださると、そのときは行けなくても、行かなくちゃ、行かなくちゃという認識はずっと継続されるので、それは区のほうからというふうにはなかなかならないと思いますけど、それぞれのお医者さんの医療機関の独自の裁量のところなんだろうと思うんですけど、そういうことも、お医者さんによってはされていらっしゃると思いますが、５年に１回ですからね、区の健診は。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"歯周疾患の改善の指導のところなんですが、今ちょっと概要を開いたんですけども、成人歯科健診の結果のところでは、歯周疾患の治療を要しますという人が受診者の約半分、４９７名いらっしゃるということは、歯周疾患を予防していくということがほんとうに求められているなと思って右のほうを見たんですけども、この辺でこの歯周疾患改善指導受診状況というのを見ましたら、平成１４年度が３８名、１回目。","respondent":"田中健康課長","answer":"医療のほうできちんと治療を受けてくださいということなので、非常に「治療は必要ないが、改善指導の必要あり」というのはどこなんだということで、これはなかなか難しいところがありました。","voiceIndex":37,"id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ほんとうに健康を保っていくために大事な歯だし、このことに関しては、ほんとうに前々、痛くなってから、悪くなってからじゃ遅いので、ほんとうにＰＲに力を入れていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-018"},{"speaker":"嶋委員","kind":"質問・要望","question":"この厚生労働省の実施する子育て支援総合推進モデル市町村事業ということなんですが、これが一つの普及啓発セミナーということで、そのほかにまだ予定がこの中に含まれているかお聞きしたいことと、それとあと、先着３５０人ということなんですが、これは基本的に親子だったらいいなとふと今思っているんですが、大人だけという部分もあると思うんですが、当日券を配布して当日と。","respondent":"辻田児童課長","answer":"大人だけがいらっしゃって、ドラえもんショーは見ないで帰りますよということがあれば、そういう形でその時間になりましたらお子さんを入れるというようなことも対応をとっていければなというぐあいに考えております。","voiceIndex":46,"id":"exchange-019"},{"speaker":"嶋委員","kind":"質問・要望","question":"私が心配したのは、トークショーの「私の子育て体験」と、このお二人のゲストなんかも、どちらかというと、若い世代から、いろんな形で、子育てに関係ない人たちがこれを見に来る可能性があるのかなと今ふと思ったので、それを聞かせていただきましたので、そこら辺、ちょっと当日整理する方が、たくさん来るのはうれしいけど、また逆にお帰りいただくという部分もあるかと思うので。","respondent":"辻田児童課長","answer":"各子育て課が区にあります。そちらのほうにポスター、チラシをお送りして、そして掲示をするようにお願いするです。","voiceIndex":48,"id":"exchange-020"},{"speaker":"築舘委員","kind":"意見","question":"この品川区がモデル地区として子育て支援総合推進の区になっているわけなんですけど、それが今回近隣地区にも呼びかけるということが国から言われたということなんですけど、これはどういう意味がというか、要するに、会場も狭いし、そういった意味では、ほかのほうから来てもらっても困る場合もあるわけですよ、今回の場合はね。","respondent":"辻田児童課長","answer":"近隣につきましては、当然そういうようなことで大きな会場と、それから、こういう言い方は大変いけないのかもしれませんけど、子育ての専門的な方たちだけが集まる、そういうような事業でしたら、それはある意味で近隣のところにやったとしても、専門的なとか。","voiceIndex":50,"id":"exchange-021"},{"speaker":"築舘委員","kind":"質問","question":"モデル地区だからといって、そのまま受けることもないわけで、それだけのことはある程度上に逆に企画をしていくということがあって当然じゃないかということと、それから、トークショーにしても、俳優の方、女優の方なんですけど、この人選なんかも、例えば国のほうで言われている人をとるとか、そういうことはあるんですか。","respondent":"辻田児童課長","answer":"最初に、ちょっと気になることがありましたので、押しつけという形ですけど、決してそういうことではないということで、やはりこのモデルの指定を受けるということは、それなりに区が全国に発信できるもとですので、そういう意味では、やはりこれを受けたということでは。","voiceIndex":52,"id":"exchange-022"},{"speaker":"本間委員","kind":"質問","question":"何か急ぎの形で進められて、決められてというような流れの中に、品川区がはまっているようでして、このスケジュールの中身を見ますと、やはり品川区としての立場、出番が見えて来ませんね。うちとどこが違うんだ、品川区を見習おうという思いで来る場合があったときに、どのような対応になるのかということがあったものですから、その点についてお尋ねします。","respondent":"辻田児童課長","answer":"ですから、ここでは、確かに品川区だからこういう形でできるんだと、いわゆる子育ての楽しさを実感できるということが、品川区の基本的なコンセプトで、他区にこういう形のものを実施することによって、品川区は子育てを支援するんだということを発信していくということで。","voiceIndex":54,"id":"exchange-023"},{"speaker":"本間委員","kind":"質問","question":"その部分での出番がこの中にあるのかなということでお尋ねしたわけでして、それは楽しくイベントをやって次につなげるとか、指定されたから私たちの持っているものを別の機会にやるとかという話でフォローしていくというふうにも思われますが、この一つの１日の行事の中で、品川区は市町村のモデル事業として国から、あるいは東京都を通じて指定されたという意義づけがどのようにして見られるのかなと。","respondent":"辻田児童課長、小沼児童保健事業部長","answer":"東京都でも、いわゆる子育てをしている俳優であるとか歌手の方を呼んで、参加者と共感をするというような形での事業も実施しており。それに対して、幾つか代表的なところで質問等も入ってくると思うんですが、場内からあらかじめ幾つかの子育てにかかわるお話等を当日してもらうというような質問に答える形でのものというようなことも計画していますので。","voiceIndex":56,"id":"exchange-024"},{"speaker":"飯沼委員","kind":"意見","question":"この辺の団体とか対象がある程度絞られているのか、その辺１点と、あと、当日のプログラムを見ていて、当日託児の実施と書いてありますけれども、親子で楽しむというところでは、全体的な流れが親子で一緒に座って見られるのか、託児の体制がどの程度に、普通だと親御さんが参加して、見ていられないお子さんを預かるという託児が多いと思うんですが、この辺の体制がどうなっているのかお聞かせください。","respondent":"辻田児童課長","answer":"当然お子さんはドラえもんショーが見たいということで、その時間になりましたら、親御さんと一緒にショーを見ていただくということで、具体的には当日託児しますか、それともひざの上に乗せますか、それともお隣に座らせますかというようなことを参加する方々に聞いて。","voiceIndex":59,"id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私たちはよくいろんな催しをするときに、必ず感想を書いていただいたり、アンケートをとったりするんで、ぜひその辺せっかくのお集まりなんで、意見を聞いていただきたいなと思うんですが、いかがでしょうか。","respondent":"辻田児童課長","answer":"予算ですけど、全体の予算として事例集までつくるので８００万円程度かかります。その中で、今回私どものほうとしては、実施計画策定経費とあわせた形でそれと一緒に抱き合わせで４００万円程度この事業につぎ込んでいるです。","voiceIndex":63,"id":"exchange-026"},{"speaker":"武内委員","kind":"質問・要望","question":"１点だけですけど、今アンケートというお話もありましたけど、例えば子育てガイドブックとか、それはちょっと無理にしても、何か情報的な子育ての、そういうものを逆に来た方に配布するような、そういう何か試みも検討されているようでしたらお聞かせいただきたい。","respondent":"辻田児童課長","answer":"ちょっと今手元にないんですが、子育ての先日健康課のほうから出しましたそういうものについては、当日会場に置きまして、そして参加者にお配りするというようなことで、私どもの資料としてお配りいたします。","voiceIndex":65,"id":"exchange-027"},{"speaker":"南副委員長","kind":"質問・要望","question":"今のご質問でも出たように、子育てガイドをお配りするという話を聞いてちょっと安心したんですけど、私もどうせというか、こういういい企画をされるに当たって、やっぱりテーマが子育て支援ですから、子育てをされている方々に話を聞いていただくだけじゃなくて、行政がどんな支援を、体制をとろうとしているのか、とっているのか、その辺をやっぱり知っていただくことが。","respondent":"辻田児童課長","answer":"なかなか行政として、こういうような方々に接して交渉するということは無理です。そういう意味では、当然そういうことをプロモーションする、そういうような方がいて、私どものほうもそういう方たちにある程度事業を委託して実施していくです。","voiceIndex":67,"id":"exchange-028"},{"speaker":"南副委員長","kind":"質問・要望","question":"そういうプロモーターにお願いするんであれば、とりわけこちら側のコンセプトというのをほんとうに知っていただくことが大事だし、いろんなノウハウを持っていらっしゃるから、そんなに心配することではないのかもしれないけども、やっぱりせっかくの機会ですから、有意義にこのお金を使っていくという点でも一番大事な基本のところですから。","respondent":"辻田児童課長","answer":"会場に入りましたときに、そういうものをお渡しすると、そういう形でそのパンフレットについて何らかの形でご紹介するような形で私どものほうとしては考えていきたいというぐあいに思っております。","voiceIndex":69,"id":"exchange-029"},{"speaker":"本多委員","kind":"確認","question":"区民への周知でそれぞれこの内容の周知を努めているということで、その部分なんですけれども、この制度が始まってこの３カ月間なんですが、当然その区内の契約医療機関と４月以降は都内の契約医療機関ということで、この３カ月間の区切りでちょっと注意をしていかなければいけないのかなと思うんですが、以前は区外の診療機関等に受診し。","respondent":"辻田児童課長","answer":"初めに、私どものほう、今年の最初の段階、この制度を始めようというぐあいに考えたときには、多分１区だけでやっていかなくちゃならないので、全部お医者さんと契約をして、そして品川区が全部対応していくということで、事務量等も膨大になるということを予想していました。","voiceIndex":76,"id":"exchange-030"},{"speaker":"武内委員","kind":"質問","question":"先ほど聞き間違えたのかもしれない。色がグリーンの医療証というふうにお聞きしたんですけど、例えば乳幼児用と小学生の３月までと４月以降と医療証の色を変えたりして区別をわかりやすくするような予定みたいなのはおありなんでしょうか。","respondent":"辻田児童課長","answer":"ただ、その中で、私どものほうとしては、負担者番号を削ることによってその辺について対応してきたです。","voiceIndex":80,"id":"exchange-031"},{"speaker":"嶋委員","kind":"質問・要望","question":"ほんとうにこれはすばらしい待ちに待った助成制度ということで、ほかの区の方たちからはほんとうに品川区はすごいということで、ほんとうに胸を張る内容だと思います。それから契約機関、医療機関なんですが、今品川区の中で小児科だけではなくて、お子さんの場合、小学生の場合は普通の大人がかかる内科でほとんどかかっている場合があると思いますが、この契約医療機関の数を教えていただきたい。","respondent":"辻田児童課長","answer":"歯科医師会、医師会を入れまして、７７２人の方が医師会のほうに登録しているです。","voiceIndex":84,"id":"exchange-032"},{"speaker":"嶋委員","kind":"質問・要望","question":"そういう意味で、これは品川区だけじゃなくて、ほかの区もそうですが、小児科の先生がほんとうに撤退をして人材不足をしているということがどこの区も今問題、取り上げているところですので、品川区としてもぜひまたこういう機会にすばらしい先生を品川区に、小児科専門の先生をアレルギーとかいろんなこともあると思いますけど。","respondent":"辻田児童課長、青山品川区保健所長","answer":"私どものほう、小児科医を品川区に充実させるために、ちょっと専門が私のほうからお答えできないんですけど、２番目のご質問につきましては、区外でかかる方、それなりにいらっしゃいます。その方々が小児科やあるいは公衆衛生の分野に進んでいただけるように、あるいは進まなくても、そういう心あるいは目を持って活躍していただけるように、この研修に対しても力を入れてまいりたいというふうに考えております。","voiceIndex":86,"id":"exchange-033"},{"speaker":"嶋委員","kind":"質問・要望","question":"直接これにかかわることじゃないんですが、ちょっと今思っていることなので、もしここでお答えができなければそれで結構なんですが、今親御さんも学校現場、教育でもそうだと思いますけど、子どもの病気に察知ができない、急変の病気の何かに察知ができない親御さんが多くなってきているということもありますので、こういう機会にこのすばらしい品川区の医療費制度ができますので、そういう形でも保護者。","respondent":"青山品川区保健所長","answer":"そういった意味では、子育て支援策全体を含めまして、親御さんたちが我が子の状態あるいは周りの子どもを含めまして、目が常にあるということを心がけていかなければならないと思いますが、ただ。","voiceIndex":89,"id":"exchange-034"},{"speaker":"本間委員","kind":"質問・要望","question":"テーマに沿いながら質疑します。それから、対応ですが、この人的な支援の面と補助的な支援、お金の支援といいますか、補助金でしょうか、この辺の二つの面からどのような中身になっているのか教えていただきたいというふうに思います。","respondent":"金子保育課長","answer":"ですので、私どもとしては、問い合わせ等ご案内があった場合等に対応するということで、物的、人的な支援についてはここでは私どもとしては直接的には考えておりません。","voiceIndex":97,"id":"exchange-035"},{"speaker":"本間委員","kind":"質問","question":"その部分の品川区としての体制で今回いこうということですが、さまざまなケースといいますか、突発的なケースが大変多いというふうにお子さんのことですからいろんなケースが出てくると思います。そういう場合の対応方も含めて、通常の病院の仕事の範疇を超えるような部分までは行っていないというふうにお考えでしょうか。","respondent":"金子保育課長","answer":"当日もこれについては該当の児童に関しては診察をして、その後にお預かりするというふうになっておりますので、その意味では通常の診察の後、要するに時間的にも場所的にもそういうようなイメージでとらえていただければというふうにお考えいただければと思います。","voiceIndex":99,"id":"exchange-036"},{"speaker":"本間委員","kind":"質問","question":"利用料金というものの中に、月曜日から金曜日が２,０００円となっています。土曜日が１,２００円ということで料金の変更がありますが、これは前段にもありますように、利用時間等の関係で、土曜日は午前中と、いわゆる１２時ですから午前中というふうなことによって１,２００円というふうになるのでしょうか。","respondent":"金子保育課長","answer":"委員ご指摘のとおりです。土曜日は１日分の時間がないので、料金も若干低くしているです。","voiceIndex":101,"id":"exchange-037"},{"speaker":"武内委員","kind":"意見","question":"利用時間が一応５時半というふうになっておりますが、あってはいけないんでしょうけど、どうしてもこれを３０分とか１時間とか延びた場合の対応とまた料金の問題と、それから逆にこれは料金は変わらないと思いますけども、逆にお母さんが仕事を何とか都合をつけて早目に早退して、例えば午後１時ぐらいに戻ってきて引き取りに来た場合なんかの料金も変わらないのかどうかということと。","respondent":"金子保育課長","answer":"例えば、骨折等で長期間にわたり通常の保育ができない場合というのは、これは病後児のほうで対応しておりますので、そういう場合には基本的には病後児のほうで対応するというふうに考えております。","voiceIndex":103,"id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問・要望","question":"クリニックに委託をするということで、今までの病後児保育よりもさらに急性期のお子さんを預かるというところでは、大変安心な今回の中身になると思うんですが、一つ急性期とあるんですけれども、今までの病後児保育との違いがあるところがあったら教えていただきたいのと、既に公立、私立の保育園で病後児保育が行われている中での要求というのか、新たなこういう要求があって始めたとか。","respondent":"金子保育課長","answer":"ですので、その意味では、現場からの声も受けておりますし、また、私どもの所管ではありませんが、少子化に関する区民調査の中で、自由回答というものがあるんですが、ここで病気のときの施設、預かってもらう施設というような要望がかなり多く寄せられていると。","voiceIndex":105,"id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この辺で指定基準についてどういう状況になっているのかというところで、特にまだ見せていただいていないのでわからないので、預かっている保育室というのか、病室になるのかわかりませんが、スペースの問題とか、職員というのが、配置をされている人の問題がどういうふうになっているのかなというのを聞きたいのと、病後児保育のときには、利用される範囲が。","respondent":"金子保育課長","answer":"食事に関して原則持ち込みと申しましたが、ここの施設にはもともと栄養士もいらっしゃるので、その辺の対応というのが可能な人員になっております。それから、スペースの問題は今ちょっと数字を持ってきていないので後ほどお答えします。それから、病後児との何でしたか。","voiceIndex":107,"id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問","question":"病後児保育のところの事業の説明の用紙をちょっと今探してきたんですが、利用料のところに、認可保育園園児が無料となっていて、その他の就学前児童１日２,０００円となっているので、今回のところだと、保育園に預けていらっしゃる、通所している保護者が就労等で保育できない場合、だから、この条件のところが前の病後児のように園に預けていらっしゃるお子さん以外のところも受ける体制があるのかどうか。","respondent":"金子保育課長","answer":"確かに委員ご指摘のとおり、病後児につきましては、在園している方については保育の延長ということで、当初いろいろ検討はしたんですけれども、保育の延長ということで２,０００円という金額についてはいただいておりませんが。","voiceIndex":109,"id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問","question":"利用料のところじゃなくて、すみません、ここの場合は病時保育のところの対象児童のところなんですが、幼稚園ということは、ここの前の、ごめんなさいね、病後児保育と同じに認可の保育園以外に拡大して見ているというふうに受けとめればいいということなんですね。そこの対象がどの範囲で違いがあるのかなというところがちょっと気になったものですからお伺いしたんです。すみません。","respondent":"金子保育課長","answer":"基本的にはそういった通常どこかに通っている方で就労等でやむを得ない事情が発生した場合を想定していますので、それを原則としていますが、それ以外にもこれに準じた理由というのはあろうかと思いますので。","voiceIndex":111,"id":"exchange-042"},{"speaker":"飯沼委員","kind":"質問","question":"今の点は理解しました。先ほど栄養士がいらっしゃるので、食事は原則持ち込みと書いてあるけれども、その辺は考慮していただけるんでしょうか。もう一個、先ほどの事業に関する扱いで、病後児保育と同じような内容というか、通知とか規定があるのかどうか、１点もう一回お伺いしたいのと、今後区でここの事業に関して報告を受けたり、内容のチェックなどはどのようにしていくのかお知らせください。","respondent":"金子保育課長","answer":"どういうふうな形でチェックしていくか、またどういうふうに報告をいただいていくかということですけれども、私どもとしては、初めてやる事業でもありますし、具体的にまだ詳細を詰めたわけでありませんが、例えば１カ月に一遍とか。","voiceIndex":113,"id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問・要望","question":"細かく中身を報告いただいてやっていくことと思います。よろしくお願いしたいと思います。１点概要のところに病後児保育の件数は載っているんですが、ぜひ今やっている制度ともあわせて中身がどういう状況になっているのか、ぜひもうちょっと詳しくこの中身も当委員会で今後またご報告いただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":115,"id":"exchange-044"},{"speaker":"築舘委員","kind":"質問・要望","question":"病時保育において、幼稚園も含まれているわけですけども、その前の病後児保育においても、保育園、幼稚園ということで通園しているお子さんがということでお仕事していらっしゃる方ということなんですけれども、その病後児保育の中で、幼稚園でそういうお子さんを預かった例というのが何件ぐらいあるのかというのをちょっとお聞かせいただきたいのと、それから。","respondent":"金子保育課長","answer":"いろんな方がいらっしゃいまして、品川区内で医院等を開設している方というのは、結構少なくて、外からの方が非常に多いですね。そういう意味では、実績がどうかということを掌握することが非常に難しいわけです。","voiceIndex":116,"id":"exchange-045"},{"speaker":"築舘委員","kind":"質問","question":"ただ、病後児保育の場合は、保育園にそれぞれ預かるということで、なかなかそれが行きにくいというようなこともあったり、幼稚園に行っていらっしゃる方は在宅の方もいらっしゃるしということで、確率的には低くなるのは当然だと思いますが、幼保一元化園もあることですし、担当がというか、管轄が保育課にも来ているということもありますし、そういった意味で、保育園だけに限らず。","respondent":"金子保育課長","answer":"私どももこの事業をスタートするに当たって、やはり必要な方には利用しやすくしなければならないし、かといって、一方で先ほども申し上げたとおり、病気だからといって育児放棄につながるような、そういった運用は決してしてはならないと思っていますので。","voiceIndex":118,"id":"exchange-046"},{"speaker":"本多委員","kind":"質問","question":"三つ目なんですけれども、これも築舘委員から出ていました一応その他のところで、医師が利用することを適当と認めたということ、これは病気についてなんですが、症状を見て、これは当然大事だというような判断をするんだと思うんですが、それとあわせて、どうしても仕事を休めない、その部分のチェックというのはどのようにしていくのか、その３点をちょっとお聞かせください。","respondent":"金子保育課長","answer":"３点のお尋ねですが、まず１点目、病時保育という名称の問題かと思いますが、私ども病後児保育を運営してきたことからいってというのは１点ありますし、またもう一点は、国はこれを一つの要綱で運営しておりまして。","voiceIndex":120,"id":"exchange-047"},{"speaker":"嶋委員","kind":"質問・要望","question":"それと今の本多委員のほうから拡大する必要はないとおっしゃられましたけれども、やはり働く保護者の立場からすると、デイケアルーム的なものは、ほんとうに１カ所でなくて、もう少し拡大をしていただきたいというのが、そういうところがあるということが一番安心して就労していくことですので、もちろん基本的には病気のお子さんを置いていくというのはしのびないことですが。","respondent":"金子保育課長","answer":"今後の展開のことのご質問かと思いますが、私どもとしては、初めてスタートする事業ですので、利用率がどの程度になるか、それからニーズ、そしてどのような利用実態になるのか、こういうところを見ながら、今後の拡大については検討していきたいというふうに考えてあります。","voiceIndex":122,"id":"exchange-048"},{"speaker":"嶋委員","kind":"質問","question":"「広報しながわ」には場所の地図とかは載っているのかどうか。それから、これは最終決断をされるのは委託医師が診察して利用の可否を決定といいますと、最終決断をするのは委託機関ということでしょうか。","respondent":"金子保育課長","answer":"そこの時点でのその子の状態というのは主治医のほうで把握されているというふうに考えておりますが、やはり当日に実際に連れてきたところで、病気の対応が変化している場合もありますので、最終的にはお預かりするところで決定するというのが妥当なところかと思っていますので。","voiceIndex":124,"id":"exchange-049"},{"speaker":"嶋委員","kind":"質問","question":"当日最終は委託機関が決定ということなんですが、もし、だめと言った場合はどのような、もちろんお医者様の判断ですから、私どもにはわからない部分がありますが、そこら辺、親はオーケーと思って連れてきていても、だめと言った場合は大変そこで混乱が起こりそうなのかなと。これから起きることなので、あまりそういうことは予想もしたくないことですけど、そこら辺はどういうふうにお考えなのか。","respondent":"金子保育課長","answer":"その場合に、やはりどうしても仕事がある場合というふうになりますけれど、これについてはこれ以上の法令は今の段階では私どもとしてはできないというふうに考えてあります。","voiceIndex":126,"id":"exchange-050"},{"speaker":"南副委員長","kind":"質問・要望","question":"だから、あちこちにつくってほしいというふうにはなかなか私としては言いたくないなと思っているんですけど、だからこそ、こういうふうにつくっていただいたのはそれはそれで評価するんですが、しかし、何でもかんでも行政で受ければいいんじゃなくて、やっぱり例えば今次世代育成の行動計画を立てているときに、必要な意見をどういうふうな形で産業界に言ったりしたらいいのかわからないですけども。","respondent":"金子保育課長","answer":"それから２番目に、この医療機関に決定した地理的なことはどうかということですけれども、私どもとしましても、区として第１号の施設ですから、これを例えば極端な話、区境で実施するということになれば、その意味が半減以上するわけですので。","voiceIndex":128,"id":"exchange-051"},{"speaker":"南副委員長","kind":"質問・要望","question":"そういうときに、たまたま子どもが熱を出したり病気になってしまって苦労するというのはあると思うんですけど、母親だけがそういう責任を負うんじゃなくて、やっぱり父親とか、いろんな家族との連絡調整の中でやっていくのが最低限のことだというふうに思うので、私の場合もいろいろな人たちに助けられてこれたんで、それはそれで感謝したいと思っているんですけど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":130,"id":"exchange-052"},{"speaker":"築舘委員","kind":"意見","question":"年末保育なんですけども、これは保育園に通っている方だけでしたっけ。年末に商売をやっている方とか、そういう方もオーケーというような話をちょっと聞いたことがあるので、その辺のことと、利用状況は保育園に行っている方以外の方があるのかどうかということを聞かせてください。","respondent":"金子保育課長","answer":"年末保育につきましては、通常通園されている方以外にも年末に仕事などをされている方ということで要件をしておりますので、在園児以外も対象としているということでご理解いただきたいと思います。","voiceIndex":135,"id":"exchange-053"},{"speaker":"築舘委員","kind":"意見","question":"そういうことでしたら、病時保育のときは幼稚園にも保育園にも掲示しているということなんで、各保育園だけじゃなくて、幼稚園にも掲示というか、周知をしていただいたほうがいいと思うし、それから一般の２割を利用されているということだと、「広報しながわ」を見て利用されるんだとは思いますが、その辺のＰＲもお願いしたいというふうに思います。","respondent":"金子保育課長","answer":"幼稚園のほうにもお知らせするような形でＰＲについては考えていきたいと考えています。","voiceIndex":139,"id":"exchange-054"},{"speaker":"本間委員","kind":"質問","question":"何点かお尋ねします。０歳児から５歳児まで預かるということで、この部分の年末保育については大変評判がよろしいというふうに聞いております。例えば、０歳とか５歳というような幅が非常にある部分で、この時期の波動的な対応をどのようにしているのか、実際の現在の所属している先生方で対応しているのか、あるいはまた別の方法をとられているのかどうか、その点について対応方について教えてください。","respondent":"金子保育課長","answer":"１５年度、１４年度あたりは大体このような７園、６園から８園あたりを実施していまして、大体この数が区内全域をある程度の距離の間隔を持ってカバーしているという数ですので、現在の利用者数からいえば、このぐらいの数が適当ではないかなというふうに今考えてあります。","voiceIndex":141,"id":"exchange-055"},{"speaker":"本間委員","kind":"質問","question":"３番目の件なんですけど、職員の体制はというふうな部分は、私どものほうで一応危惧するのは、６ブロックごとに分けて、それぞれの園に応援に行く部分なんですが、結局０歳から５歳までの非常に幅のある年齢で、そして数もまちまちだと思うんですね、１人だとか２人だとか、３人だとかというような形の中で、非常に子どもが保育に携わる先生のなつきといいますか、対応という部分で泣きじゃくったりして。","respondent":"金子保育課長","answer":"私も例年両日実施日については、全部すべての園を回っているんですが、委員ご指摘のとおり、中には、全体として見ている限りでは、全体として１人ぐらいなんですけども、ご指摘のとおりずっと泣きじゃくっているお子さんがいないわけではないということは事実としています。","voiceIndex":143,"id":"exchange-056"},{"speaker":"本間委員","kind":"質問・要望","question":"特に数が、何回も言いますように、年齢別に差があることによって振り回されるといいますか、きちんとしないと、子ども１人について、職員がそのたびに振り回されるような形になるようなことのないように危惧すると、そういうことのないようにしていただきたいというふうな観点からお尋ねさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":145,"id":"exchange-057"},{"speaker":"飯沼委員","kind":"意見","question":"一つは、今課長が私も全園回っていますということで、ほんとうに職員の皆様、ご苦労をかけていて、ほんとうに感謝しているんですけれども、一つは非常時の対応というか、ここのところ、いろんな事件が起きていますけれども、緊急の場合の体制がどのようになっているのかと、病気とかけがが起きてはほしくないんですけれども、起きたときに、病院関係とどのような連携がとれているのか、お聞かせください。","respondent":"金子保育課長","answer":"病気とかけがの場合ですけれども、これにつきましても、年末年始の医療機関、特にお願いをしているわけではありませんが、近隣の開設しているところをきちんと把握をした上で、万が一病気とかけがが起きた場合には対応できるようにしています。","voiceIndex":146,"id":"exchange-058"},{"speaker":"飯沼委員","kind":"質問・要望","question":"一つわからなかったんですが、学校１１０番のスイッチを持っているということなので、ちょっとその辺をもう少し詳しく教えていただきたいなと思うのと、保育課に何人か体制を持っているということなんで、その辺は連携ができているというので安心をしました。学校１１０番のところだけ。","respondent":"金子保育課長","answer":"一つの施設で三つのスイッチが標準的に設置されていまして、それを押せば５０人規模の警察官が直ちに押した場所に向かうというふうな機能を持ったものです。","voiceIndex":148,"id":"exchange-059"},{"speaker":"嶋委員","kind":"質問・要望","question":"就労の支援を行う技能訓練、知識とか、７項目にわたってのいろんな修得をするということですが、この方たちを教える指導者といいますか、それは常勤の職員２名と非常勤職員２名ということなんですが、この中の、どういう経歴があるのか教えていただきたい。","respondent":"西島障害者福祉課長","answer":"現在就労支援センターとしてはここに常勤２名、非常勤２名とありますが、この事業の拡大に合わせて１名さらに採用するというふうに聞いてあります。それから、実際の講義等に当たりましては、それぞれそれに該当するような方をお呼びして実施するというふうに聞いてあります。","voiceIndex":154,"id":"exchange-060"},{"speaker":"嶋委員","kind":"質問","question":"それに該当するというのは、全然わからないんですけど、もう少し詳しく教えてください。","respondent":"西島障害者福祉課長","answer":"例えば安全衛生だとか、コミュニケーション基礎だとか、計算基礎というようなことがあります。そうすると、それぞれ専門の講師の方をお呼びして実施することになってあります。","voiceIndex":156,"id":"exchange-061"},{"speaker":"嶋委員","kind":"質問","question":"３カ月単位で実施をするということで、訓練期間は３００時間ですが、これはそれに伴う企業に対するアプローチといいますか、そこら辺はどのようにされていくんでしょうか。","respondent":"西島障害者福祉課長","answer":"その企業の想定いたしましたような実技的な訓練を行うというところがみそでございまして、そういう意味で就労に即つながるような訓練になるというふうに考えてあります。","voiceIndex":158,"id":"exchange-062"},{"speaker":"築舘委員","kind":"質問・要望","question":"この障害者の就労支援センターで、平成１５年に就労された方が１４名いて、また１６年では１１名いらっしゃるということ。これはどういうところに就労されているか、それからその状況をお聞かせいただきたいと思います。","respondent":"西島障害者福祉課長","answer":"平成１６年度で言いますと、清掃関係で株式会社ニコレ、それから同じく清掃関係でモンテローザ、介護補助でＮＰＯに勤められた方も１人いらっしゃいます。そのような状況です。","voiceIndex":161,"id":"exchange-063"},{"speaker":"築舘委員","kind":"質問","question":"その実績をどんどん増やしていくということがこれからも大切なことだというふうに思うんですけど、企業も今回太陽の家ですか、別府市で見てきたような形の、ソニーなんかもそういった形で協力をしていましたけども、区内にある大企業なんかもそういう形の受け入れというか、協力というのを何らかの形でやってくれているのかどうか。","respondent":"西島障害者福祉課長","answer":"区内は幸い大きな企業がありますので、例えばソニーですと、ソニー光だとか、特例子会社をつくりまして、障害者を重点的に採用するだとかという努力をいただいているんですが、区内はまだ法定雇用率の該当する企業というのは８７０社ほどおそらくあると思いますけども。","voiceIndex":163,"id":"exchange-064"},{"speaker":"飯沼委員","kind":"質問・要望","question":"一つは、仕事を受け入れる側の企業の体制もあると思うんですが、５２１件の相談に対して１４名とか、やはりまだまだの状況なんで、ぜひここに力を入れていただきたいなと思うところで、体制的な問題が１点と、あと委託していますけれども、委託料がどの程度で、この辺で人件費が賄われているのかどうか、その辺もちょっとお聞かせください。","respondent":"西島障害者福祉課長","answer":"２問目の委託料のほうから先にお答え申し上げますが、委託料ですが、今１,７４０万円です。それで、体制ですけども、この５２１件あるいは今年で言うと３９４件ですが、これは１人の方が複数回ということもありますので、現在４名で賄えるというふうに考えてあります。","voiceIndex":165,"id":"exchange-065"},{"speaker":"飯沼委員","kind":"質問・要望","question":"５点目のところで、新たな就労訓練の展開というのがあるんですけれども、東京しごと財団というのを、手っとり早くでよろしいんですが、ちょっと教えていただきたいのと、この委託に対して、ここのぴゅあ・さぽーとに委託料が入るんでしょうか、その辺の中身も、お金はすごく大事なので、よろしくお願いします。","respondent":"西島障害者福祉課長","answer":"この事業ですけど、国のほうが平成１６年度から実施をいたしました。国が東京都のほうに委託をいたしまして、都が東京都の外郭団体であります東京しごと財団のほうに委託をお願いしている。","voiceIndex":167,"id":"exchange-066"},{"speaker":"武内委員","kind":"質問・要望","question":"一つ、移転後の新たな就労訓練の展開の中の７番のラウンジ事業の拡大というところで、ラウンジ事業ということについて教えていただきたいのと、それから前のほうに戻りまして、今まで約３０平米弱のぐらいのところで非常に狭かったということなんですけど、今度６倍ぐらいの広さの土地に行かれるわけですけど、かなりスペースが広がったんですけど、これがこのラウンジ事業と何か関係してくるのか。","respondent":"西島障害者福祉課長","answer":"ラウンジの内容ですけれども、一緒におつけいたしました、パンフレットのコピーで恐縮ですが、「障害者就労支援センターげんき品川」というところを開いていただきますと、ラウンジ事業ということで、そこに説明が書いてありますけども。","voiceIndex":169,"id":"exchange-067"},{"speaker":"飯沼委員","kind":"意見","question":"今回移転ということで、旧芳水学童保育クラブ跡地が移転先なんですけれども、一つこの間学童保育クラブがすまいるスクールのほうに移行したことで、あちこちに跡地ができているわけですけれども、その辺の跡地利用に関しては、どこかで全体的に把握して方向性が出されているのか、この間大井学童保育クラブが保育園の拡大とかなっていますけれども、その辺、どこで希望とかいろいろ。","respondent":"辻田児童課長","answer":"担当ではないんですけど、この間いろいろ施設を新たなものに転用してきましたので、私のほうから。総務部のほうに公有財産活用検討委員会というのがございまして、そこで一括して、もちろん企画財政課や何かも入って、そして今後の事業展開を考えながら決めていくです。","voiceIndex":174,"id":"exchange-068"},{"speaker":"飯沼委員","kind":"質問","question":"公有財産、そうですよね。そういった面で、行政側の体制は今わかったんですけど、例えば地域の町会とか、いろいろなサークルとか、今区内あちこち会合したり、利用する集会、〔「管轄が違う」と呼ぶ者あり〕管轄が違う。わかりましたけれども、その辺の声を出すところがあるのか、受けとめる場所があるのか、それだけちょっとお伺いしたいと思います。","respondent":"辻田児童課長","answer":"そういうようなことで、そういうような要望につきましては、活用検討委員会のほうにも上げまして、全体的な中で調整しているです。","voiceIndex":176,"id":"exchange-069"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今までの地域との大事なつながりがあったと思うんで、ぜひその辺を今後もつなげていただきたいなと思います。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":178,"id":"exchange-070"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"南副委員長","kind":"質問・要望","question":"もう一点は、認証保育所の関係なんですが、本会議での質問というのは、子育て支援の角度でやっぱり取り上げまして、公立の認可保育園じゃなく、いわゆる認証保育所のところの保育料がＡ型とＢ型とあるんですけども、Ａ型というのは大きなタイプの保育園で、そこの保育園が独自に保育料金は当然民間ですから設定されるんですが、安くて６万３,０００円、これは区内のあるＡ型の保育所ですけど。","respondent":"田中健康課長、金子保育課長","answer":"これにつきましては、多分その前からあった通知が廃止されて、平成８年に再度厚生労働省の児童家庭局長通知で母性、乳幼児に対する健康診査および保健指導の実施についてというものがございまして、その中で「母性の各期において。私から認証保育所の関係についてのご質問にお答えしたいと思いますが、本会議でもご答弁申し上げたとおり、この認証保育所の保護者に対する保育料の助成というのは、私どもとしてはこういう基本的な考え方の構造を持っております。","voiceIndex":181,"id":"exchange-071"},{"speaker":"南副委員長","kind":"質問・要望","question":"しかし、私が質問したのは、子育て支援でやはり必要じゃないかと、その考え方を伺いたいのと、それから二つ目には、先ほども申し上げましたように、母性、子どもを産んで育てていくという、そういう女性の身体的あるいは精神的な体づくりをしていく上に当たって、人によっていろいろですけど、さっきもちょっと一例として紹介したように、たばこを吸うとか、あるいはダイエットをするとか。","respondent":"田中健康課長、金子保育課長","answer":"妊婦健康診査のほうですけれども、こちらでは、逆に品川区内で受けられるといいますか、受ける体制が整っている、いわゆる妊婦健康診査の実施医療機関というのは、実は３０しか現実にはございません。上のお子さんが認可保育園で下のお子さんが認証保育所の場合に減額していることの考え方ですけれども、これは昨日もご議論されていました認可保育園の場合に、２人目以降の子どもについては３０％から５０％減額していると。","voiceIndex":185,"id":"exchange-072"},{"speaker":"南副委員長","kind":"質問","question":"それとあと、必ずしも自分の自宅、東京都内にある自分の自宅で産む人が半分か、それ以下ぐらいで、あとは田舎に帰るとかということで出産されるという方が、そういう状況だからという話なんだけど、出産がどこでされようと、妊婦健診そのものは住んでいる居住地でされているわけですから、やっぱり子育て支援の角度で取り上げていく必要があるんじゃないかなというふうに思いますので、その辺を伺って。","respondent":"田中健康課長、金子保育課長","answer":"ただ、妊婦健診につきましては、先ほども申し上げましたとおり、かなり妊婦さんのほうがいろんなところで分娩をされる予定でそういうことに入りますので、かなりいろんな区内である限定というのが非常に難しい部分がありますので。先ほどもご説明しましたが、上の子が認可保育園で下の子が認証保育所に通っている場合の減額の措置というのは、第２子以降の認可保育園に２人とも預けた場合の措置に準じたものです。","voiceIndex":189,"id":"exchange-073"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3098#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":69946,"voices":195}},{"id":"h16-20041130-8","meetingId":"h16-cm11","date":"2004年11月30日","dateIso":"2004-11-30","committee":"建設委員会","time":"午前１０時０４分～午後０時２９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"「の２、報告事項、(1) の戸越幹線貯留管整備工事その２」の着手","agenda":"「の２、報告事項、(1) の戸越幹線貯留管整備工事その２」の着手","exchanges":[{"speaker":"高星委員","kind":"質問・要望","question":"今の説明で、一番冒頭の言葉に、「軽減のため」という言葉を使われるんだけれども、もちろん天災が相手ですから、軽減という言葉しか使いようがないのかもしれないけれども、これだけのお金をかけて、大工事をやるときに、抜本的なところにどういうふうに的を得たような工事をやっていくのか、どのような工事をやっても、「軽減を図るため」という言葉にならざるを得ないのかなというふうに思うんだけれども。","respondent":"矢部下水道河川課長","answer":"私どもとしても浸水被害をなくすためというふうに申し上げたいところなんですが、委員もご承知かと思いますけれども、雨の降り方、降雨の計測時間、地形的なもの等で、この工事が完成すれば、浸水が全くなくなるというところまではお約束ができないというのが現実です。","voiceIndex":7,"id":"exchange-001"},{"speaker":"高星委員","kind":"質問","question":"中間報告は中間報告でいいんだけれども、広く中間で報告するというときに、その中に建設委員会に付議をして、建設委員会のいろいろな話を聞くという、組み込むとか何かという、そういう作業、手順というのは出てこないんですか。","respondent":"藤田都市計画課長","answer":"現在、区民の皆様からもこれから意見をいただくところですし、この後、最終的な取りまとめを行うのは今年度末を予定しておりますので、その前の中間報告、区民の意見等を合わせる中で、本委員会の中でもまたご報告をして、皆様から意見を募るというふうに考えてあります。","voiceIndex":16,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１２月２１日の広報ということですけれども、意見を募るという、その中身については、広報だけですか、それともインターネットでも、「意見を募りますよ」というふうな形で出しているのかどうかということと、いつぐらいまでにというふうなのがあるのか、そこら辺も教えていただきたいと思います。","respondent":"藤田都市計画課長","answer":"１点目ですけれども、広報しながわ等ということで、広報しながわでは、なかなか紙面の関係もありますので、詳細についての報告はできないと考えています。その関係もありますので、インターネット等も活用しながらお知らせをしていきたいというふうに思っております。","voiceIndex":18,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"インターネットからいろいろと詳しく引き出せるというのは、それはそれでいいなというふうに思っているんですけれども、インターネットを使わない人もいると思うんです。そういうふうなところで、インターネット等を使わない人にも、その中身が分かって、意見を言えるというものをぜひつくっていただきたいなと思います。これは要望で、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-004"},{"speaker":"大沢委員","kind":"質問・要望","question":"第８条の(8) で、計画戸数の規模に応じた自転車置場を設けることとあるんですけれども、自動車駐車場の場合は計画戸数の１０分の１ということですけれども、規模に応じたというのがあるんですけれども、どのような規模なのか、居住者の人数を目安とするのか、それとも戸数を目安とするのか、教えていただきたいと思います。","respondent":"浜脇住環境整備課長","answer":"２点目の第８条の件ですけれども、自動車のほうは１０分の１になってございましたけれども、(8) の自転車置場につきましては、運用基準の(5) の中に、住戸数の２分の１以上ということで、いろいろな経過があってやったものですので、ここを見て。","voiceIndex":31,"id":"exchange-005"},{"speaker":"三上委員","kind":"質問","question":"必ずしもワンルームというのが悪いのかどうか、要するに、ファミリータイプであればいいのか、悪いのか、こういう定義になってくると、非常に悩む部分があるわけです。そこらあたりについて、品川区としてはどういうふうに基本的なことを考えているかということを伺っておきたいんです。","respondent":"浜脇住環境整備課長","answer":"ファミリータイプの中でも、そういったマナー違反の方もいらっしゃるというふうに考えておりますので、一概にワンルームだから悪い方というふうな分け方で、建主側に言ったことはございませんし、そういうふうには見てございません。","voiceIndex":33,"id":"exchange-006"},{"speaker":"三上委員","kind":"意見","question":"住環境整備課長の話を聞いていても、悩む部分というのは出てきている。要するに、マナーの部分は浮き彫りにされてくる部分というのはあると思うんだけれども、マナーの部分を、どう社会に喜んでもらえるようなマナーにしていくかということについても、指導指針というのは考えられないか。","respondent":"浜脇住環境整備課長","answer":"この指針自体は、外形といいますか、施設に対する、そういったものが基本的なこととして、近隣になるべく面倒をかけないようにして、近隣と良好な関係でやって、ルールまで果たしてこういうもので、そういったことをやるというのは、ちょっと違うかなですけれども。","voiceIndex":35,"id":"exchange-007"},{"speaker":"三上委員","kind":"質問","question":"外形的な部分という話だけになっちゃうと、３ページの管理的事項という話になって、マナー的な部分のことを書いてあるということが、だから、私はそこのところが中途半端じゃないかなと思います。外形的な部分だったら、そういうことは必要ないわけでしょう。そこのところで私はいつも思うんです。これはワンルームだけにこういう縛りをかけるんですか。","respondent":"浜脇住環境整備課長","answer":"２ページのほうに近隣商業と商業地域を除くというのが前提にあるんですけれども、私どもとすれば、この指針をつくった頃は、当然民法上から見て、住宅系はお互いが５０cmずつ離れさせて、いろいろな用途に使う、あるいは一番は離れて、施設から落ちる水や。","voiceIndex":37,"id":"exchange-008"},{"speaker":"三上委員","kind":"質問","question":"これはワンルームだけに限らないという考えでいいんですか。","respondent":"浜脇住環境整備課長","answer":"これは狭いところでワンルームの場合にはやるという表示があったので、そういった意味では５０cmを守らなければいけないということで、ワンルームだけにやっておりまして、一般的な集合住宅の開発のほうには掲げてございません。","voiceIndex":39,"id":"exchange-009"},{"speaker":"三上委員","kind":"意見","question":"そうなってくると、また違うんじゃないかなという話になる。だから、そう考えてくると、一貫性がない。やるなら、やるで、なぜ５０cmを目標にして全部やらないのかという話になってくる。だから、さっき言った、ワンルームは悪なのかというような話になる。そこのところの話にもつながってくるようになる。","respondent":"浜脇住環境整備課長","answer":"ただ、１９戸から１５戸の間を何とか今の指針のほうで開発指導要綱と同じような水準でやっていきたいということで指導指針を設けたというふうになってありますので、２０戸以上は本編のほうの指導要綱で指導をしています。","voiceIndex":41,"id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、３ページの(7) のところは、自動車の駐車場については戸数の１０分の１の台数というふうなことで書いてありますけれども、その下の自転車置場については、戸数の規模に応じたというふうな形になっているんですけれども、開発指導要綱の前のほうを見ると。","respondent":"浜脇住環境整備課長","answer":"ここのところは最低水準の関係で、２５m2というのは２９m2をとる考え方が一般的でございましたので、２９m2にいたしまして、最近居住水準のほうは２９m2、商店の場合は２９m2までだということで改正した。それ以外は改正してございません。","voiceIndex":43,"id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"その前に、中高層の建物の全体の中でワンルームの占める割合というのは何％で、何戸ぐらいあるかということと、併せて管理人がその中でどれぐらい置かれているのか。それから、６番目のところで、近隣住民が協定の締結を望むときは、合意の上締結するというのがありますけれども、こういう協定を結んでいるところというのもどれぐらいあるのか、把握しているところがあったら、教えて下さい。","respondent":"浜脇住環境整備課長","answer":"５０戸以上の場合は管理人を置くということになっておりますけれども、近年ここのところにきて、システム化ではないですけれども、そういった連絡網が確立されておりまして、管理人を置かなくても、管理人的なことを行えるシステムがあったということで。","voiceIndex":45,"id":"exchange-012"},{"speaker":"木下副委員長","kind":"質問・要望","question":"お聞きしたいんですけれども、建築紛争以外のマナー、ルールの点で、自転車ですとか、騒音、ゴミということで、３ページの９計画戸数の規模に応じたゴミ容器置場を設置することとなっておりますけれども、その基準的なものを教えていただきたい。","respondent":"浜脇住環境整備課長、片田建築課長","answer":"３ページの９番ですが、ゴミの関係につきましては、清掃の関係から、今区に清掃事業は移管しておりますので、そこに行って、こういうような計画をしたいということで。補足しますと、今委員のほうで、５０cmというお話がございました。実は５０cmは、民法の第２３４条だと記憶していますが、そちらの中で建物を建てるときに空けてほしいといったような規定があります。","voiceIndex":47,"id":"exchange-013"},{"speaker":"木下副委員長","kind":"質問・要望","question":"それと、先ほど５０cm、民法というお話ですけれども、ということは、特に区のほうのルールとしても、お隣から何でこんな狭いんだというようにクレームがきたとしても、それは別段構わないということなんでしょうか。よく近隣住民の方々から、新しい家が建つと、こんなに狭く建ててという形で、文句を言う方がかなり大勢いらっしゃるので、そこら辺をちょっと教えていただきたいと思います。","respondent":"片田建築課長、浜脇住環境整備課長","answer":"基本的には民法ということが別体系としていますので、その辺についてご説明をしながら、業者のほうにもちょっとお話はいただいておりますけれども、こういった意見の中で、隣地の中では、５０cm以下であったとしても、建ペい率。先ほどのゴミ置場の件ですけれども、要綱のほうに書いてあるんですけれども、品川区の中に廃棄物の処理及び再利用に関する条例というのがございまして、これにつきましては、清掃リサイクル課のほうで計算式を持っておりまして。","voiceIndex":50,"id":"exchange-014"},{"speaker":"大沢委員","kind":"質問","question":"近年の流れの中で、さっきワンルームというのは２５m2から２９m2ということで変更があったということですけれども、５０m2でワンルームというような、ワンルームという名前はついているんだけれども、こういう部分で平米数が違ってくる、より広いワンルームが増えているんじゃないかと思うんですけれども、そこら辺のこれからの流れというものと現状。","respondent":"浜脇住環境整備課長","answer":"ですから、ワンルームといいますか、３０m2以上については、これは集合住宅の一部というふうに捉えていいと思います。","voiceIndex":53,"id":"exchange-015"},{"speaker":"須貝委員","kind":"質問","question":"どこに連絡していいかもわからない。そうすると、ますますトラブルのもとになると思いますので、そこは例えば現行のマンションに対しても、管理者の表示板をつけてくれというような方向性というんですか、そういう何か指導はあるんでしょうか。","respondent":"浜脇住環境整備課長","answer":"こういうものを年々改正をしていって、そういう近隣被害というのは、こういうものがある前に建ったというふうに思われますから、既存のものに対して何かできないかということですけれども、こういう条例とか、要綱というのは、付則の中にありますけれども。","voiceIndex":55,"id":"exchange-016"},{"speaker":"須貝委員","kind":"質問・要望","question":"ワンルームの指導指針が出て、というのは、そういう経緯が現行でもあると思いますので、この指導指針とは別枠でも、ワンルームに関して、現在あるものに関しては、協力を願うような何か方向性を考えていただければありがたいなと思いますので、トラブルが多いからこういうのがどんどん規制されていくわけですから、要望ということでお話しします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-017"},{"speaker":"高星委員","kind":"意見","question":"この間、マスコミ、新聞などでも相当ワンルームの課題を集中的に取り上げてきたという背景があって、この夏頃だと思うんですけれども、その辺に７月の改正がされたのではないかなというふうに思うんですが、改正にあたっても、どのくらい慎重な審議がされたのかということを、ワンルームのこういった、全体的に品川区だけでない、各区でも見直しがあった背景のところをどういうふうに押さえているのか。","respondent":"浜脇住環境整備課長","answer":"これが、中にはできないということもあったかもしれませんけれども、ほとんどの方が守ってやっていただいておりますので、それほどこれについて大々的に変えたり、あるいは条例化したりという状況にはなっていないというのが、検討をした結果です。","voiceIndex":60,"id":"exchange-018"},{"speaker":"高星委員","kind":"質問","question":"そうすると、その人たちが退職金をどう使うかということ、それを業者がねらっているわけですね。地方から東京に来て、一生懸命働いて、一定程度会社を務め終えて、かといって、今さら田舎に帰れないというような方はどうするかというと、やっぱりそういうようなところが、いわゆる退職金の預けどころというんですか、投資的なものに当て込んでいく。","respondent":"浜脇住環境整備課長","answer":"戸数を１５戸のままでいいのか、もう少し減らしたらいいかとかあったんですが、やはり１５戸ぐらいにならないと、環境などを整備していただきますから、それ以下だとなかなかできないということがあって、１５戸以下の方は、今委員がおっしゃったように、大家といいますか。","voiceIndex":62,"id":"exchange-019"},{"speaker":"高星委員","kind":"意見","question":"これからさらに、今品川区の指導指針では棟数で３０％がワンルームみたいな形で、普通のファミリーマンションで言ったら、その３倍からの、かなりの棟数が一気にできてしまうけれども、そういうふうなこと。あるいはそういったところを執行部のほうの所管の担当の方々がどういうふうに把握して、どういうふうに考えていらっしゃるのか、その辺のところを聞いてみたいと思います。","respondent":"中谷まちづくり事業部長","answer":"近頃問題になっておりました空き缶やたばこの投げ捨てなどもそうでございましたが、社会の一般的な規範が足りない、ルールを守らないという、地域社会の問題、こういう問題もたくさんありますが、まずできるのは。","voiceIndex":64,"id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3804#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":22364,"voices":66}},{"id":"h16-20041130-9","meetingId":"h16-cm11","date":"2004年11月30日","dateIso":"2004-11-30","committee":"文教委員会","time":"午前１０時０４分～午後０時２５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"林（宏）委員","kind":"確認","question":"小中一貫校の日野中学校の生徒の呼び方なんですけれども、中学校１年生、２年生、３年生と呼ぶのが正しいですよね。現段階で、７年生、８年生、９年生と呼ぶのはまだ早いと思うんですけれども、そういうふうに呼んでいるところがあるんですけれども、その辺をはっきり確認をしたいんです。どういうふうな呼称で、日野中学校の生徒を呼んでいるのか、説明してくれますか。","respondent":"中島指導課長","answer":"ご承知のように、小中一貫校として平成１８年度からの立ち上げという部分を想定しているところではありますが、現在、第二日野小学校と日野中学校が取り組んでいる文部科学省の研究開発学校の中で、もう既に９年間を通した研究を続けて３年目に入ってきています。","voiceIndex":6,"id":"exchange-001"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"ただ、あるところでは、中学校１年生、２年生、３年生と呼んで、あるところでは７年生、８年生、９年生と呼ぶ。それから、僕は聞いた覚えはないんだけれども、文教委員会にそういう説明がされたんですか、今言ったように、準備として、こういうふうな呼称を使うと。僕は、日野中学校のホームページをちらっとのぞいたんだけれども、そういうことが書かれているんですか。お願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":8,"id":"exchange-002"},{"speaker":"沢田委員","kind":"質問","question":"今の関連なんですけれども、一貫教育のほうも、７年生、８年生、９年生というのを使うんですか。","respondent":"中島指導課長","answer":"したがいまして、周りは、４、３、２ということで、小中一貫校につきましては、１年生から９年生という呼称を使っていきたいと考えておりますけれども、それ以外の学校につきましては、小学校は１年生から６年生、中学校は１年生から３年生という呼称になろうかと考えています。","voiceIndex":9,"id":"exchange-003"},{"speaker":"沢田委員","kind":"質問","question":"小中一貫校の場合は、７、８、９年生というのを使うということですけれども、例えば卒業証書なんかというのは、中学校の３カ年を修了したとかになるわけですよね。そうしますと、品川区の、しかも小中一貫校の中ではそれが通用するけれども、他の学校に行ったときには、それは通用しないということで、何か問題は起きないんでしょうかね。","respondent":"中島指導課長、若月教育長","answer":"小中一貫校の中での、４、３、２のまとまりに合わせた１年生から９年生という取り組みという形になりますので、ほかとの問題というのが生じることはないと考えています。したがって、学年の呼称が、カリキュラムをつくる上で、７、８、９年生と連続で出てきているわけです。先ほどちょっと説明しましたけれども、一貫した形のより強い意識を持ってもらおうという問題意識が、現場からありました。","voiceIndex":11,"id":"exchange-004"},{"speaker":"沢田委員","kind":"確認","question":"もう一度確認したいんですが、現場の教師からそういう意見が上がってきたということはわかったんですが、実際に運用してみて、子どもたちの意見、あるいは親の意見、それから教師も、ちょっとほかの関係でいろいろ問題があると、やっぱり従来どおりの一貫校中学校何年生みたいな呼称のほうがいいとなったら、その余地はあるんですか。","respondent":"若月教育長","answer":"それはそうでしょうね。","voiceIndex":14,"id":"exchange-005"},{"speaker":"中塚委員","kind":"確認","question":"確認なんですけれども、２年後に全区展開をされる。だけれども、全区展開で一貫教育を順次進めていくところは、７年生と呼ばなくて、まだ一貫教育が始まっていない、あるいは組み合わせが行われていない中学校は、そのまま中学校１年生という形になるんですか。その辺のところを。","respondent":"中島指導課長","answer":"学校のほうでは、平成１８年度から新しい一貫教育のカリキュラムで進めていきますけれども、その一つ一つの中身に関しては、一遍に入れる内容と、年度を置いて入れていかなければいけない内容がありますので。","voiceIndex":18,"id":"exchange-006"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"林（宏）委員","kind":"質問","question":"実際にスタートを切ってからやっていくわけですから、そういう意味で、ちょっと言葉はいけないけれども、教師という人材をどう生かしていくのか、殺しちゃうのか、そういうところの備えというのは、教育委員会は持っていなきゃいけないと思うんです。品川区にＡ先生が行く、Ｂ先生が行くと正式に決まるのは、もう直前じゃないですか。できる、できないじゃなくて、考えるべきだと思うんです。","respondent":"若月教育長","answer":"教師を採用して、育てる準備をという、今、ご指摘でありますけれども、基本的に、やはり教員という職業の特殊性から考えたときに、私は、本来、その備えから、手だてから、指導から、やはりその赴任した学校がするのが一番適切であろうと思います。","voiceIndex":26,"id":"exchange-007"},{"speaker":"林（宏）委員","kind":"質問","question":"どうしても、Ａ小学校、Ａ中学校というと、そこだけの情報になりがちじゃないですか。やっぱり、品川区、あるいは品川区のみならず、いろいろなほかの市町村の例も情報として取れるわけでしょうから、そういった中で、先生を育てていくということを、やがては品川区から出て行ってしまうんだけれども、品川区から出て行く先生が多いと言っている中で、品川区に来たいという先生はたくさんいるんですよ。","respondent":"若月教育長","answer":"ですから、これは何としてもやり遂げていかなければならないことだし、事実、このプラン２１を進める中で、力量が少しずつ高まってきた校長というのも現実に何人かいるということも、私は一つのいい材料だと思っています。","voiceIndex":28,"id":"exchange-008"},{"speaker":"林（宏）委員","kind":"質問","question":"最後にします。今、最後に言われた、校長先生が現場の教師の教師であり、リーダーであり、あるいは経営者であるわけです。だからそういった意味で、採用とか、任用とか、なかなか区でまだできないとすれば、人事制度の中で、区としてできることをしっかりつくり上げる、あるいはやっていく、運営をしていくという考え方を教育委員会が持つべきだと思うんですが、その辺はいかがでしょうか。","respondent":"若月教育長","answer":"それをどうやって形に変えて、教育界に引き込んでくるかというのは、教育委員会の仕事であり、それを実現していくのは校長の責任だと、こんなふうに考えているところです。","voiceIndex":30,"id":"exchange-009"},{"speaker":"大西委員","kind":"質問","question":"やはり私も、学校を変えていくというのは、その長である校長の意識の問題だと思うし、その人の優秀さというんですか、そういうことでドラスティックに変わっていく。社会においては、会社に入れば、２、６、２のバランスというのがあります。ご承知だと思いますけれども、優秀が２割、何ともないのが６割、悪い２割と。たいてい悪いほうの２割が引っ張っていくという状態があるわけです。","respondent":"若月教育長","answer":"それをどう料理するかというところに、また今、専門職としての教員の力量が問われているんだろうし、そういう力量をこれから身につけていってもらいたいという、今は一つのプロセスだと考えていただければなと、こんなふうに思います。","voiceIndex":33,"id":"exchange-010"},{"speaker":"大西委員","kind":"質問","question":"新しいフィールドに出てきて、ああ、品川区のプラン２１でこういうことをやっていると、これはどういう趣旨でやっているのか、どういう結果を導いているかという研鑽ができないような校長であれば、それはもう全く論外の校長なんです。改めまして、ぜひ、テストケースというんですか、ケーススタディというんですか、そういう意味でも、柔軟な発想を持っていただくことを、私は切に望むところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-011"},{"speaker":"沢田委員","kind":"質問・要望","question":"道場問題はこれからですからあれですけれども、その前に報告のあった、平成１２年に人事考課制度を導入して、自己申告制を、民間と同じに取り入れて、目標のどこまで達成しているのかというのをやろうということを導入したというんですけれども、具体的にはどんな中身なのか、わかる範囲で教えていただきたいと思います。","respondent":"中島指導課長、若月教育長","answer":"こういった研修をやっていきたいという部分が幾つか出てくるわけですけれども、その研修を具体的に１枚のシートにあらわしたものが、先ほど、ちょっと説明したキャリアプランということで、教員の研修については。では、教育委員会として、一番根本に何を持っているかというと、特に授業力というものを考えたときに、これはちょっと抽象的な言葉になってしまって、おそらく沢田委員には納得していただけないかもしれないけれども。","voiceIndex":36,"id":"exchange-012"},{"speaker":"沢田委員","kind":"質問","question":"当初、年間５,０００億円の業界のリーダーとしての利益を上げたんだけれども、今は赤字に大転落です。しかも、営業みたいに、売上げをどれだけ伸ばすかというのは数値化できるけれども、技術部門は数値化できないじゃないですか。ですから、必ずしも民間でやっていることが万々歳ではなくて、大きな問題をはらんでいるということを、私はこの本で読んだんで、述べておきたいと思います。","respondent":"若月教育長","answer":"なぜならば、教師は戦うということも、あの要綱には書いてあります。戦うというのと、労働者ということを考えたときに、これは単純に働く人という意味ではないというふうに、私は解釈をしているというのが１点目です。","voiceIndex":39,"id":"exchange-013"},{"speaker":"沢田委員","kind":"質問","question":"これで終わります。労働者を１万７,０００名減らすと。ところが、退職金を２倍近くに上げたら、ソニーの人たち、当初予想していた以上の人がだあっと辞めちゃったんです。いい人も含めて、みんな出ていっちゃった。民間というのはやっぱりそれだけ厳しいですから、利益を上げるためには、愛社精神なんかどこかにすっ飛んで、ほんとうにすさまじいリストラをやる。意見だけ述べて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-014"},{"speaker":"西本委員","kind":"質問・要望","question":"保護者が約８割ぐらい来るんですよ。担任だけではなくて、高等学校ですから、教科担任制がありますので、ほかの先生も、非常に一人ひとりの子どもに対してどういう教育をしていったらいいのかということを、親にしてみると、ほんとうにわかるぐらい発信してくれます。権限移譲というのは、なるべく早くしてほしい、人事権に対しても、品川区に移してほしい。そこら辺は、何か持っていたら教えてください。","respondent":"若月教育長","answer":"それはもう水平調整の時代なんだと。全く同じことを、２３区の特別区の教育長会でも、私はこの前、都の人事部長が来ましたので、それをはっきり言いました。いつまでも垂直調整じゃなくて、財調と同じように水平調整にしてほしいんだと。","voiceIndex":42,"id":"exchange-015"},{"speaker":"西本委員","kind":"意見","question":"意外と新任教員のほうが柔軟性があって、理解していただけるという話も聞くんです。もう一つ最後に、今、品川区の現場で、プラン２１というやり方、検討委員会をいろいろつくって、いろいろ積み上げの中でやっているんだよということは、やっぱりもっと東京都のほかの地域に知ってほしいと思うんです。それは、区教育委員会のＰＲを、ぜひ、してほしいなと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":44,"id":"exchange-016"},{"speaker":"藤田委員","kind":"質問","question":"今までずっと伺いまして、この趣旨はわかりました。最後に、品川区は、教育委員会として、今後、ＯＪＴに対するかかわりを持ちたい、この辺をちょっとお伺いしたいと思います。","respondent":"若月教育長","answer":"そういう意味で、ぜひ、教員の育成に寄与していきたいなと、こんなふうに考えているところです。","voiceIndex":45,"id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4524#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":30551,"voices":48}},{"id":"h16-20041130-5","meetingId":"h16-cm11","date":"2004年11月30日","dateIso":"2004-11-30","committee":"総務委員会","time":"午前１０時１０分～午前１１時１５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成１６年請願第２８号、一人ひとりの子どもが大切にされる品川区を求める請願","agenda":"平成１６年請願第２８号、一人ひとりの子どもが大切にされる品川区を求める請願","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"少子化に対する区民調査などでは、女性のほうの希望としては、もっと男性のほうに協力してほしいと、そういう希望は、調査に一貫してありますけれども、もうちょっと、一歩突っ込んで、何でそういう気持ちになっていくのかというところをつかんでいるかどうか、それはどうでしょうか。","respondent":"榎本行財政改革担当課長","answer":"具体的には労働に関しての男性の意識というか、そういうものの項目というのは特に入ってはいないんですけれども、区民調査の中でやったのは、逆に、独身者に対して、何でそういうふうに結婚というものを意識しないのかということはやったんですけれども、特にその部分については。","voiceIndex":6,"id":"exchange-001"},{"speaker":"宮崎委員","kind":"質問","question":"私はもうちょっとそこのところを突っ込んでいかないと、同じことを言うにも、実態をつかんでいないとかみ合わなくなってくるようなこともないかというふうに思うんですけれども、仕事と生活時間のバランスとか、そういうふうに問題意識を持っておられるわけですから、機会があったら、そういうところの調査もしていただいたほうが、せっかく男性の意識の問題だというふうになって。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":8,"id":"exchange-002"},{"speaker":"石田委員","kind":"質問・要望","question":"先ほど１１月５日の総務委員会というお話がありました。そういう中で、ご説明もある程度されて、もちろんその前に我が会派は政策要望ということも出させていただいて、さまざまな次世代育成支援だけではなく、子どもに関するこちらの部分も、すまいるスクール等ほかの部分も政策要望をさせていただいている中で、もちろん子育て支援は必ずしていかなくてはならないというふうに考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-003"},{"speaker":"土井委員","kind":"質問","question":"このことについてはずっと取り組みを進めているわけです。ですから、これはその意味では、ここで審議するのも、これは参考送付程度でよかったんじゃないかと思うぐらいの中身だというふうに思いますので、ここであえて、言われれば、採択するのはおかしいから、不採択にせざるを得ない、こういうことだろうと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-004"},{"speaker":"本田委員","kind":"質問","question":"この請願の内容が項目を盛り込んで下さいじゃなくて、具体的に現実に品川区の状況の中では民間企業ではどうなっているとか、こういう点を特に強調してほしいとか、そういう各論が入っていれば、検討が必要かなと思うんですけれども、項目を設けて下さいでは、もう項目を設けて、具体的に実施に移そうというところまできているわけですから、議会として請願者の意思といいますか、趣旨というのは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-005"},{"speaker":"若林委員","kind":"意見","question":"ただいまの石田委員、土井委員、本田委員以上のことは申し上げることはないと思いますが、あえて言えば、男性向けの教室とか講座とか、すでに具体的に進められているということで、また、項目の上から言っても、すでに１１月５日のご説明で十分承知をしておりますので、この内容につきましては不採択でいきたいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":15,"id":"exchange-006"}]},{"id":"topic-02","title":"危機管理担当組織の設置","agenda":"危機管理担当組織の設置","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"それと、この前の、私らもちょっと経験をさせてもらったけど、私などは東京にいたんですけれども、地震があったときに、すぐ新潟とか、皆さんが電話をする方がいらっしゃったものですから、携帯電話もかからないという、逆に使えない状態になっちゃった。東京同士で電話を通話しようとしても、今いっぱいですからだめだという状態にすぐなりました。あれも本当にすぐなったと思うんです。","respondent":"宮地総務課長","answer":"危機管理室の事務局ですが、事務局の職員のうちほとんどが区内に住んでおりますが、とにかくこれを１回訓練とかやってみて、時間を測ってみないことには、今すぐ何分以内にとは申し上げられませんが。","voiceIndex":22,"id":"exchange-007"},{"speaker":"石田委員","kind":"質問・要望","question":"お願いですが、初動期が本当に大切で、こういう組織があったんだけれども、動かなかったという自治体もあったりとか、我々も新聞とか、報道の範疇でしか分かっていないんですけれども、初動期をどうやって動かすかというのは大切で、組織をつくってもそれが稼働するか、今お話を伺ったら、訓練もされるということです。それと、ある新聞関係では、回線がいっぱいなんだと。それはお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-008"},{"speaker":"土井委員","kind":"質問・要望","question":"となりますと、それらのそれぞれの事例においての権限委譲と言いますか、そこへ来た人がトップなんだと、この部分をしっかりしていただかなければいけないので、そういう意識づけを少なくとも総務部の担当の皆さん方も、自分が来たら、総務課長というか、総務部長というか、もう自分しかいなかったら、私がそれなんだという意識を含めた調整なり、研修というべきか、意識づけなり。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-009"},{"speaker":"宮崎委員","kind":"質問","question":"実際に想定事例というふうにいろいろ書いてあるんですけれども、国とか、あるいは警察の仕事じゃないのかなというふうに思うんですけれども、そこら辺のところはどんなふうになっているんでしょうか。","respondent":"宮地総務課長","answer":"国、東京都から指導があったのかですが、これは区の独自の考え方で、必要だから設置するです。防災課がこういうことをやっている課もあれば、いろいろな自治体によってさまざまです。","voiceIndex":26,"id":"exchange-010"},{"speaker":"宮崎委員","kind":"質問","question":"例えば目的のところなんですけれども、事態への適切な対応というふうに書いてあるんですけれども、実際にどこまでやるのかというのが、ここには事例がありますから、例えばこの事例でいくと、国がどういうことをやる、東京都がどういうことをやる、区がどういうことをやると、そういう意味では線引きも考えているんですか。","respondent":"宮地総務課長、本間総務部長","answer":"さまざまです。それをこれからの危機管理室の中でも想定事例をもとに、どこまで、どういう形でできるのかもひとつ考えていきたいというふうに考えております。実際、品川区の職員がやったのは、その間、近辺の限られた地域内の区民の方を安全に避難させて、具体的には学校施設等を使って、その間安全に品川区の職員が避難の手伝いをしたというように、それぞれの機関が連携して。","voiceIndex":28,"id":"exchange-011"},{"speaker":"宮崎委員","kind":"意見","question":"これから考えようと。例えば今交番が留守という問題も非常に社会問題にもなっていますけれども、一方では、本来やらなければいけない仕事に手を引いていって、それが自治体が肩代わりになっているみたいなこともありますし、本来のやるべきことというのをもっと整理していけば、こんなところまで考えなくたって、日常の連携とか、そういうのができるんじゃないかというふうに思うんです。これは意見です。","respondent":"本間総務部長","answer":"ご意見ですけれども、まさに逆だと私どもは考えてあります。例えば庁内で何かあれば、どこにも属さないことは全部総務課が対応をしてまいりました。","voiceIndex":31,"id":"exchange-012"},{"speaker":"宮崎委員","kind":"質問","question":"変わらないじゃないですか。そのための準備で、こういう法制整備が進められているわけですから、私は、こういうものというのは、そもそも発想がおかしいと。それに対応するわけですから、その対応で法整備をしているわけですね。そういう自治体を巻き込んでの、やれ、テロだとか、そういうことを対応をとってくるというのは、これは自治体のやるべきことじゃない。あえて言っちゃいますけれども、意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-013"},{"speaker":"本田委員","kind":"質問","question":"一つお尋ねするのは、体制図の中で、危機管理監が総務部長ということで、あとはその事例に応じて、事案に応じて関係部長ということになっておりますが、学校関係はいろいろな意味でちょっと、事例の中に入っておりませんけれども、何が起きるかわからないような危険というのはあるというふうに私などは思っているんですけれども、これは教育関係も全部入っているんですか。","respondent":"宮地総務課長","answer":"ただ、もっと関係が広がってくれば、ここの関係部長のところには当然教育関係も入ってくる。全部かぶった一つの危機管理対策本部体制です。最も緊密な部分のところの部長、あるいは教育長等も入ったですので、そういうふうにご理解いただけるかと思います。","voiceIndex":34,"id":"exchange-014"},{"speaker":"本田委員","kind":"質問・要望","question":"これから危機管理のマニュアル作成、事例ごとに必要とされるマニュアル等をいろいろつくっていくということですから、所管委員会にもちゃんと議会のほうにも報告をいただいて、役所の中では万全の体制で何事に対しても対応できるという安心感というものを区民に持っていただけるという危機管理体制というものをしっかりと確立していただきたい。これは要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-015"},{"speaker":"土井委員","kind":"質問・要望","question":"そういうときに安心をどうやって得られるかということになると、役所の皆さんが、例えばこの間の地震の場合でも、新潟で起こったときに、うちの役所は何をやったんだろうというのが非常に気になっているんですね。ですから、その意味で、ＰＲの活動も十分にやっていただきたいということ、そのためには、例えば地震が起こったら、今までの事例が幾つかありますから、マニュアルの中に当然ある。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-016"},{"speaker":"若林委員","kind":"質問・要望","question":"１カ月弱で、間にどういうふうに、例えば広報しながわに出しますよとか、将来はこういうふうな体制なんだけれども、周知、また、モデル事業というんでしょうか、品川区も含めて１月を目途にとかというのを、区民の皆さんはいつからガチッと体制を固めるんだという、そういう考え方をお知らせいただきたいと思います。","respondent":"宮地総務課長","answer":"今ある机と、人間で対応いたしますので、特段できないということはございませんので、準備は進めているところです。","voiceIndex":38,"id":"exchange-017"},{"speaker":"若林委員","kind":"質問・要望","question":"右手の図の中で、いわゆる地域の力、どうしても危機管理の上では、議会というのは、右端というんでしょうか、双方の矢印がありますが、議会との矢印の意味と、地域の力がここにどう、住民というところになってくるのかもしれませんが、地域の力としてどういうふうに想定されているか、この２点だけ最後にお願いいたします。","respondent":"宮地総務課長","answer":"港区は総務課の中に危機管理担当という係を置いておりますが、これは今年度の体制で、来年度につきましてはどういう形にするか、今検討中ということですので、２３区はそういった形になってあります。","voiceIndex":40,"id":"exchange-018"},{"speaker":"堺副委員長","kind":"提案","question":"私も過去にこの件について提案したことがありますので、ちょっと確認をしておきたいなと思うんですが、我が党としても平成７年の阪神・淡路大震災の際に危機管理という点で、本会議の代表質問の際に提案をさせていただいた経緯がありましたが、そのときは緊急危機管理マニュアルの作成ということを中心にした提案でございました。","respondent":"宮地総務課長","answer":"今年ある予算の中で何ができるかですが、当面のところは紙を使ってまとめたり、案をつくったりということですので、今あるもろもろの事務経費の中で対応をしていきたいというふうに考えております。","voiceIndex":44,"id":"exchange-019"},{"speaker":"堺副委員長","kind":"質問","question":"おそらく今回は、先ほどもお話に出ておりましたように、過去１０回にわたる台風の上陸と、新潟中越地震という、今までにない大きな被害を受けた中で、区民の皆さんは安全、安心ということを望むわけでありますから、そういう視点で区民の皆さんにこういうものが、水防対策本部とか、災害対策本部とはまた別の形で、いつでも危機管理について対応できるような組織をつくりましたということを周知してあげれば。","respondent":"宮地総務課長","answer":"私どものほうでも、ある手段、使えるものはなるべく早期に使えるものから順番に活用していきたいと思いますが、１月１日の広報にはちょっと間に合いませんが、早々に載せて、それからホームページなどはすぐできることですので。","voiceIndex":46,"id":"exchange-020"}]},{"id":"topic-03","title":"平成１６年請願第２６号、郵政事業の民営化に関する請願にかかる意見書","agenda":"平成１６年請願第２６号、郵政事業の民営化に関する請願にかかる意見書","exchanges":[{"speaker":"宮崎委員","kind":"意見","question":"これで内容はいいんですけれども、文言のところなんですけれども、「こうした状況を踏まえ、マスコミによるアンケート等」となっているんですけれども、前後の関係でいくと、「こうした状況を踏まえ」というよりも、「しかしながら」とか、そっちのほうがいいような感じがするんですけれども、皆さんの意見で、これでいいよとなれば、これでいいんですけれども、ちょっと前後の関係でいくと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":52,"id":"exchange-021"},{"speaker":"本田委員","kind":"質問","question":"この文面からすれば、「懸念されます」ということと同じく、議会では承知しているということですから、つなぎの文章としては、「こうした状況を踏まえ」というのでいいんじゃないかなと私は思うんです。同じことを喚起する言葉ですから、「しかしながら」と言うと、今度は違ったことを意味する。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-022"},{"speaker":"石田委員","kind":"質問","question":"「加えて」がいいんじゃないですか。「しかしながら」と一緒だから。","respondent":"須藤委員長","answer":"加えて、マスコミによるアンケート等においても、郵政事業の民営化に対する国民の理解度が不足していると考えます。」というような形で、並列して、国の事業としていろいろと国民の利便性があるよと。","voiceIndex":54,"id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1672#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":19846,"voices":64}},{"id":"h16-20041201-11","meetingId":"h16-cm12","date":"2004年12月1日","dateIso":"2004-12-01","committee":"自治制度特別委員会","time":"午前１０時０４分～午後３時５７分","status":"正式会議録","sourceType":"formal","overview":"自治制度特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を4件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"高星委員","kind":"質問・要望","question":"これから３カ所視察に行かせていただくんですけれども、この中に品川区からの派遣職員が行かれているところというのはどこにあるのか、ちょっとそこだけ教えていただきたいと思います。","respondent":"桑村人事課長","answer":"今浜川荘に１人おります。ほかのところには区の職員はおりません。","voiceIndex":3,"id":"exchange-001"}]},{"id":"topic-02","title":"これより特定事件調査を行います。特別区人事・厚生事務組合に関すること","agenda":"これより特定事件調査を行います。特別区人事・厚生事務組合に関すること","exchanges":[{"speaker":"須藤委員","kind":"質問・要望","question":"何点かお聞きしますが、路上生活者の緊急一時保護センター、第１、第２ブロックがまだだよという話なんだけれども、この辺はどういう状況になっているのか、まるっきり進まないのか、どうなのか。それから、上の委託の民間のところもどういうふうになっているのかなというのが、上のというのは、宿泊所というのは民間法人に委託というのがどこになっているのか、そのあたりが分かれば教えて下さい。","respondent":"志村生活福祉課長","answer":"荒川区につきましては、都市基盤整備の中の公園の候補地のところに施設をつくるということで、これにつきましては、たしか着工したというようなお話を聞きましたので、先ほど説明がありましたとおり、年度末。","voiceIndex":10,"id":"exchange-002"},{"speaker":"高星委員","kind":"質問","question":"こういうことを一貫して見ていると、これから先もかなり長期間必要とされるんだろうというふうに思うんですけれども、例えば来年度の東京都の予算を計上するにあたって、大体２,０００億円程度の減額をしていこうという東京都の見込みがあるというふうに聞いているんですけれども、これから先こうした事業が東京都と区の割合と言ったら変だけれども。","respondent":"志村生活福祉課長","answer":"４分の１が私どもの区の経費になる、このような関係になってあります。ですので、お尋ねの東京都の関係となりますと、一応路上生活のことでありませんけれども、これは２３区と東京都で２分の１ずつ負担をしていく、これが基本になってあります。","voiceIndex":12,"id":"exchange-003"},{"speaker":"高星委員","kind":"質問・要望","question":"どうしても気になるのは、三位一体改革との関係、補助金との関係ですけれども、その辺のところで、危惧されることがないのかどうなのかということを具体的に教えていただきたい。","respondent":"市岡企画財政課長","answer":"いずれにしても、国もそうですけれども、この一連の問題については、大都市東京について東京都と区が都市としての責任を分け合って行うべきだというのが、東京都の２３区に対する協力を要請してきたときの知事の説明だったものですから。","voiceIndex":14,"id":"exchange-004"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5558#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=11&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":10243,"voices":23}},{"id":"h16-20041201-16","meetingId":"h16-cm12","date":"2004年12月1日","dateIso":"2004-12-01","committee":"街づくり特別委員会","time":"午前１０時０５分～午後０時４６分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議案審査を議題とします。 第７６号議案 専決処分の承認を求めること","agenda":"議案審査を議題とします。 第７６号議案 専決処分の承認を求めること","exchanges":[{"speaker":"井上委員","kind":"質問","question":"質問なんですけれども、こういった地域の中でどんどん買収をされていく中で、この２件のケースがこういうふうな経過に至った理由、主な大きな点というのはどういったことなんでしょうか。","respondent":"中島街路事業担当課長","answer":"こちらの２件につきまして、最終的に私どもは任意契約ということでこの間ずっと交渉、お願いをさせていただいてきたわけですけれども、こちらの特にお二方につきましては、事業が立ち上がった時期、平成７年に事業を始めたわけですけれども。","voiceIndex":5,"id":"exchange-001"},{"speaker":"井上委員","kind":"質問","question":"一番最初のボタンの掛け違いとか、計画変更みたいなものというのは、当初、ここの２号、３号の方たちはエリアに入っていなかったとか、そういうことなのか、事業移転をするところで、移転をするはずだったところがそういうところがなくなったのか、ボタンのかけ違いというのはどういうことなんですか。","respondent":"中島街路事業担当課長","answer":"ボタンのかけ違いの主な内容ですけれども、平成７年に事業認可をとっていますけれども、その前の段階、平成５年、平成６年の段階から説明会等を行っている中で、案の段階でいろんな案があったんですよね。エリアの部分でのこういう案、ここまでの案、ここまでの案。","voiceIndex":7,"id":"exchange-002"},{"speaker":"西本委員","kind":"質問・要望","question":"長い時間かかって和解までというところまでいろいろ大変なことが多かったと思うんですが、確認したいのが、損失補償ということで金額が書いてあるんですけれども、その算出の方法を簡単にお教えいただきたいということと、それから長年かかっていますから、当然、平成７年とかというと結構時間が経っていると思うので、土地の算定するときの算定基準が変わったりということはどうされているのか。","respondent":"中島街路事業担当課長","answer":"ですから、今回の、１月に裁決申請しましたけれども、こちらにつきましては、１０月に毎年改定していますので、今回は平成１６年の１０月ですが、その時点で評価をしまして、実際に和解した段階では、法定修正率というのがございまして、物価の変動等を見て。","voiceIndex":9,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"損失の補償のところなんですけれども、2)のところの土地に対する損失の補償以外の損失の補償ということで、先ほどのご説明だと、建物の移転、物件にかかわるものだということなんですけれども、この辺で、物件の調査をしましたよね。その物件の調査で、建物の評価以外のものが含まれているのか。含まれているとしたら、どのくらい含まれているのかお聞かせいただきたい。","respondent":"中島街路事業担当課長","answer":"それと営業にかかわる、営業に影響する補償です。基本的にはそのような補償をして、それは当然、事前に調査、これにもありましたけれども、専門の会社が調査をした上でこういった基準に従いまして算出するです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"飯沼委員","kind":"意見","question":"動産の移転にかかわるということなんですけれども、平たく言ったら、移って、またこの２つ、２号も３号も、どちらかといったら、地元で営業したいという意向が強いですよね。","respondent":"中島街路事業担当課長","answer":"ただいま委員が言われた補償につきまして、いわゆる営業補償と言われているところですけれども、営業補償というのはいろいろな算定の仕方があるんですけれども、例えば羊華堂の場合で申し上げますと、仮営業、要するに立ち退きを決められちゃっているような性格になりますので。","voiceIndex":13,"id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問","question":"ということは、実際、ここでずっとお仕事をしたかったけれども、この計画でやむなくここの一等地を明け渡さなくちゃいけない、何とかやっていけるという判断、和解をしたということなんで、そういうことだと思うんですけれども、その辺、１点と、あと、先ほどの土地収用法の明け渡し体系のこれをせざるを得なかった理由のところで先ほどご答弁をいただいて、初めのボタンのかけ違い。","respondent":"中島街路事業担当課長","answer":"１点目の補償でもって今後営業継続といいますか、仮店舗も含めてできる内容かということですけれども、私どもとすれば、十分とはなかなか私からは言えないですけれども、営業継続できていける内容の補償であるという考えです。","voiceIndex":15,"id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問","question":"理解に時間がかかったというところでは、双方向の話し合いができたのかなというところがすごく関心があるんですが、その点が１点と、あと、前回のときに、この２号と３号の線路にかかわる土地と広場のほうの土地の違いがあるのかといったら、両方とも区が買ったというご説明を受けたわけなんですが、きょういただいたこの図面にかかわるクリーム色の全体の、ここが駅前広場事業の広場なんですが。","respondent":"中島街路事業担当課長","answer":"権利者の方との話し合い自体の問題ですけれども、少なくとも今回は収用事件になりますけれども、権利者の方とは和解をしたという、これは私ども、円満に話し合いをして双方が同意して和解をしたですので。","voiceIndex":17,"id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問・要望","question":"和解に関しては本当に長い間かかって、当事者の方もご苦労されたし、区のほうもこの間ずっとご努力をされてきたということは本当に認めていきたいと思いますし、また和解にこぎつけてよかったなと思いますが、本当に時間がかかったということでは、いろいろな問題点があったと思うので、ぜひ、今後ほかの部分でいろいろ収用する、土地の買収など、また起こってくるときに。","respondent":"中島街路事業担当課長","answer":"この間お話ししました鉄道部分のところの負担というんですかね、その関係でいきますと、鉄道敷の部分の約６００m2、６００m2というのは駅前広場の３,８００m2の６分の１につきましては、品川区が高層交差で使用できると。","voiceIndex":19,"id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問","question":"今の東急電鉄から買うというところは、すみません、もう１回、どこの部分を買うんですか。","respondent":"中島街路事業担当課長","answer":"例えば民間の方から買う場合もありますし、鉄道事業者から買う場合もあるです。","voiceIndex":21,"id":"exchange-009"},{"speaker":"飯沼委員","kind":"意見","question":"東急電鉄の持っている土地というのは、具体的に、よくわからないんですが、私、この間、ちょっと引っかかってしまったのが、今回、２号、３号の土地の部分で、東急電鉄にかかっているところがありますよね。ここは上物じゃなくて、本当に鉄道にかかわる部分から品川区の土地ですよね。そこがよくわからない。","respondent":"中島街路事業担当課長","answer":"道路としても使っちゃえるし、線路がそこを横断とか縦断という場合もありますけれども、使ってもいいというような、道路と鉄道との共有な関係がありますので、いわゆる占用できる、双方でお金を払わないで、相互無償使用というんですけれども。","voiceIndex":23,"id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問","question":"わからない質問ばかりですみません。具体的に言うと、例えば現在のところで、２６号線と下の鉄道と重なっていますよね。そういうところの理解と同じでいいんですかね、相互、上と下、道路管理者と鉄道事業者という考え方のとらえ方で無償でしているというとらえ方でよろしいんですかね。","respondent":"中島街路事業担当課長","answer":"今回は地下になりますので、道路あるいは駅前広場、地下を電車が走っているということになりますので、基本的にはそういうようなことになろうかというふうに考えております。","voiceIndex":25,"id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問","question":"最後なんですが、２号と３号のところの、これから線路になる部分の土地というのは、品川区が所有者ですよね。東急電鉄にお貸しをするという理解でよろしいのでしょうか。","respondent":"中島街路事業担当課長","answer":"相互無償使用の考え方でいきます。","voiceIndex":27,"id":"exchange-012"},{"speaker":"塚本委員","kind":"確認","question":"今の飯沼委員の最後の問題を確認しておきたいんですけれども、逆の立場でこっちが無償使用してもいいんじゃないかという、東急電鉄の土地所有のままで運営広場にしてもいいんじゃないという考えも成り立つと思うんだけれども、これは決まりでそうなっているのか。それから、その境目がどういうふうになっているのか。","respondent":"中島街路事業担当課長","answer":"東急電鉄が持っていてそれを品川区が借りるというお話ですけれども、こちらにつきましては、取得するときに、地下を電車が走るわけですから、地上権的なもの、地下権というんですかね、それが当然発生しますので、私ども、ここを買うというお話をさせていただきましたけれども。","voiceIndex":31,"id":"exchange-013"},{"speaker":"塚本委員","kind":"意見","question":"その話はちょっとずれる話で、基本的に所有者がいて、決まった目的で使ってあって、それがたまたま鉄道事業者のほうで地下に入るということなんですが、東急電鉄が使っている土地を何でまた改めて自治体が買わなきゃいけないか、その約束事はきちっとできているのか。","respondent":"中島街路事業担当課長","answer":"そういった中では、連立事業につきましては、東京都、品川区、目黒区、東急電鉄と４者でやっているわけですけれども、この４者で連立事業をやっていく上で、建運協定というものを締結しています。","voiceIndex":33,"id":"exchange-014"},{"speaker":"塚本委員","kind":"質問","question":"今回、その取り決めをしたというのはわかりましたけれども、根拠がなきゃそういう取り決めができないわけでしょう。さっきの建運協定なんかありましたけれども、こういうことを想定しない話ですから、やはりこういうところは上意の考え方があって、それを適用したらこうなりましたよというふうになっておかないと、この情勢は、そうですかという話にはならないんじゃないの。","respondent":"中島街路事業担当課長、中谷まちづくり事業部長","answer":"この鉄道、連立事業に関しましては、先ほどもちょっと出ましたけれども、もとの運輸省と建設省で結びました建運協定というのがございまして、そこに基本的な考え方が載ってございまして。ちょっと基本的なことを私のほうからご説明をします。","voiceIndex":35,"id":"exchange-015"},{"speaker":"塚本委員","kind":"質問","question":"そうすると、これは今の場合はわかりましたけれども、ほかの事業、ほかの鉄道会社だったり、あるいはＪＲ関係だったり、また大きさが違ったりなんかすると、買わなくてもいいという協定もできるという、そういうふうに考えていいわけですか。常に上のものは、それを整備する人が買うというのは原則なのかどうか、そういうことを聞いているの。","respondent":"中島街路事業担当課長","answer":"今、塚本委員が言われたお話ですけれども、今後こういう場合があったときに、あるいはほかの鉄道事業者であったときには、その時点で鉄道会社、あるいは東京都等と取り決めをすることになりますので、理論的にはこういう形じゃない方向もあり得るかもしれないと考えています。","voiceIndex":42,"id":"exchange-016"},{"speaker":"塚本委員","kind":"質問","question":"本来ならば、自治体と鉄道事業者とだけの話し合いで済んだのかどうか、もし少し全国的レベルで、国のほうとの考え方を問い合わせるというような作業も必要だったのじゃないかという気がしないでもないけれども、そこのところはどうなんでしょうか。それから、同種類の、今本当に、まだこれから始まる話だというんですけれども、現実にその前例があるのかないのかということが２点目。","respondent":"中島街路事業担当課長","answer":"連続立体交差事業費は、当然国費も導入されてありますので、実際そういった取り組みをする中では、国土交通省との調整をした上でこういった考え方に立っているです。","voiceIndex":44,"id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"何点かお聞きしたいんですが、１つは、開発のところでの補助金についてなんですけれども、前回質問したときに、要綱で決まっているということで、要綱もとってみたんですけれども、ここの要綱の中では、調査設計計画とか、それから都市整備とか共同施設整備というふうなところで、これに対して３分の２以内ということで算出して補助金が出されるというふうな要綱になっているようなんですけれども。","respondent":"上野都市開発課長","answer":"基本的な考え方については、既にビジョンに示したものに従って、中地区などは、明電舎については開発が進められると決まっておりますけれども、本格的な実施は来年度以降、実施を目指していくという形です。","voiceIndex":50,"id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこら辺のところが具体的に項目に沿って幾らぐらい出されているのかというふうなところを、住宅が増えれば、住宅が増えただけ補助金が増えるというふうなところがあると思うんですけれども、そこら辺のところも、具体的にじゃあどうなっているのかというふうなところが知りたいなというふうに思うんですけれども、今のすぐにはなかなか数字としては出てこないと思うんですけれども。","respondent":"上野都市開発課長","answer":"そのときの段階で、全体の制度がどういう形で１００年後を送る形でつくられているかということもあるでしょうから、そういったものの中で対応されていくのかなというふうに思います。","voiceIndex":52,"id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今は中地区なんかで言えば、８６人の地権者というふうなところですが、今度１,１２０世帯というふうなことで、すごい増えるわけですけれども、今までは一人一人が自分のところをどうしようかということで考えが済んだものが、それがツインタワーですから、１つのマンションで６００人程度の人たちが住むわけですよね。","respondent":"岩野まちづくり事業部次長、上野都市開発課長","answer":"今、中地区の高層マンションの建て替えということでございましたが、それは、今、日本のマンション全体が抱えている問題であるという認識はしております。その中に先ほどの修繕積み立てというものなどを組み込んだ形で決めていく。だから、それは現在の、詳細設計が決まっておりませんので、現段階では数字が出ていないということです。","voiceIndex":54,"id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうふうなところで、ちょっと本を見たら、途中までの部分で６８棟ぐらいが東京都内に６０ｍを超える超高層ビルができて、そのうちの４０棟以上が共同住宅というふうなことが出ていたんですけれども、そこら辺のところはぜひ、全都でどうなっているかというふうなところも把握した上での計画というふうなのが必要なんじゃないかなというふうに思いますので、ぜひ把握していただきたいというふうなことと。","respondent":"岩野まちづくり事業部次長、上野都市開発課長、岩田管理工事課長","answer":"といいますのは、既にもう１,０００万人の人がマンションで住んでおりますから、その建て替えというのは社会的に非常に大きな問題となることは確かですが。ただ、重要と思っていますのは、この地域については、６０ha全体で地域の魅力を上げて、より多くの人たちが集まってくれるような。ちみなに、私ごとですけれども、私が住んでいるところは約五百数十世帯の管理組合なんですが、そこの修繕積立金は月大体１万５,０００円程度。","voiceIndex":57,"id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"でも、今回のところも６００世帯が住む超高層ビルですから、やっぱりそれの修繕積み立てというふうなことを考えると、かなりの超高層と、やっぱり普通のマンションでは違うという部分もあるんじゃないかなというふうに思うんですけれども、オーバルコートでどれくらいかというのがわかったら教えてください。ちょっとオーバルコートの管理費と修繕積み立ては今わからないでしょうか。とりあえず終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-022"},{"speaker":"井上委員","kind":"質問・要望","question":"今のお話を伺っていてなんですけれども、地区計画も含めて、再開発、今建て替え時期を迎えるマンションの高さと、それから技術がすごくなって、１００ｍ級のマンションが建ち続けていくというような状況も生まれてくる中で、できてしまったものの、１００年後に制度をそこに持ってきて直していくということよりも、今そのことが、その先どうなるかということがとても大切なことで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-023"},{"speaker":"西本委員","kind":"質問・要望","question":"例えばその地域の人たち、今進められている地区計画の中で、住民側からもっとここをよくしてほしいよというのがあって、ある程度具体化がされたものを東京都のほうに、品川区ではこうこうという形で認めてできるという形になっているのかどうか。ほぼそういう動きになっていてやっているのか、それと、都市計画を見ても、議会の決定権というのはどういうところにあるのか。","respondent":"上野都市開発課長","answer":"都と区との関係ですけれども、今までの区内で決定してきている地区計画の案件は、いわゆる再開発を促進と定める地区計画となっていますけれども、これは３haを超える規模のものです。","voiceIndex":63,"id":"exchange-024"},{"speaker":"西本委員","kind":"提案","question":"その場合に、住民提案で都市計画がされるようになるということでは、少し軽くなるのかなという。東京都からそのようなことが出てきたときに、かなり決定されているような感じがするんですが、そうでもないんですか。もうちょっと緩やかなものとしてきて、現場サイドの計画がある程度重視されているという状況にあるのかどうか、その辺はいかがでしょうか。","respondent":"上野都市開発課長","answer":"東大崎二丁目第２地区につきましては、きっと３ha欠けるぐらいの施行がされる予定ですので、それは区決定でいく可能性が高いですので、たまたま３haを境に都決定、区決定と分けてありますけれども、都決定案件でいく可能性はあります。","voiceIndex":65,"id":"exchange-025"},{"speaker":"西本委員","kind":"質問","question":"都でやる場合と品川区で、３ha以下になると品川区決定でやってきていると思うんですが、その辺の関係の違いというのはどういうふうになっているものなのでしょうか。","respondent":"上野都市開発課長","answer":"これは３haを超えていますから都決定となっていますけれども、この中で今、中地区がこれから都市決定しようとしていますけれども、それは１.８ha未満ですし、市街地再開発事業として行うわけですけれども、それについては補助要件を満たすということで。","voiceIndex":67,"id":"exchange-026"},{"speaker":"塚本委員","kind":"質問","question":"そういうことを品川の町でも、そういうことが起こりやすい、典型的な例、何丁目の何番地のこの町はこうなりますとやっちゃったらおかしくなりますけれども、典型的な町というのはあるわけですから、それをある程度抽象化したものを、こうなります、お年寄りがこの程度住んでいれば、この程度の死亡の可能性がありますということをある程度目に見えるようにしたり。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-027"},{"speaker":"塚本委員","kind":"意見","question":"地区計画をつくるに当たって、一番のあれが災害、火災に対してどう対応、強い町をどうするかということでしょう。そのための意識づけ、町の人たちがこうだなと本当に思うのは、数字が出てきたり、目に見えるシミュレーションみたいのがあったほうがいいんじゃないかということ、そういう考えはどう思うかと聞いている。","respondent":"中谷まちづくり事業部長","answer":"そういう意味では、先般出されました、一昨年出されました、平成１４年の１２月に出ました地域危険度調査、こちらでもご報告させていただきましたが、こういうものを出すことによって延焼がどういうふうになるということで、後ほど説明があると思いますが。","voiceIndex":71,"id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１００ｍを超えるビルが増えてきつつあるんですが、その辺で、超高層ビルに住む方の立場に立っての研究がどのくらいされているのかなというところで、１つは、今、災害のことが出たんですが、地震に対する強度の問題、特に先般の新潟県の直下型地震とか、その辺に対しての研究とかがどのくらい進んでいるのかが１点と、この超高層にかかわるところなんで、あと。","respondent":"上野都市開発課長、片田建築課長","answer":"建築学会とか土木学会のほうで共同で研究をやっていこうというのがスタートした段階ですけれども、個別具体には、実例の中では一部対応されていまして、例えば東口第３地区は免震構造などを採用して、いわゆる直下型というんですか。ただ、その対策の中でもいろいろな免震構造あるいは耐震構造といったような技術的なことが開発されていますので、一定程度、４秒以上あるいは５秒近い、長周期の地震についても。","voiceIndex":74,"id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問・要望","question":"生活様式が変わってくるということで、子供の発達に影響しているということ。それから、１棟に対して５００世帯も１,０００世帯もあるような超高層のところで例えば地震が起きたときに、どこに避難をするのかという問題も含めて検討がされているのかどうか。だから、その辺についての対応もどうなっているのか、ぜひお聞かせをいただきたいと思います。","respondent":"片田建築課長","answer":"それから防災部分についても、やはり高さが高いものについては、防災計画ということでいろいろな区画とか、それに応じてきちっと建物が機能できるようにということで、通常のエレベーター以外にも非常用のエレベーターとか。","voiceIndex":77,"id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"開発を進めるに当たって、住民との合意というふうなところでお聞かせいただきたいんですけれども、地権者の合意というふうなところももちろんなんですが、そこに住んでいるけれども、借家で営業している方とか、そういう方もたくさんいると思うんですけれども、そういう方の意見や合意といったところはどういうふうに考えられているのかということをお聞かせいただきたいと思います。","respondent":"上野都市開発課長","answer":"実際の再開発事業などについては、そういったところでの借家人の方々の生活体系とかも含めた形で、制度上は救済措置といいましょうか、ありますので、それは基本的には、借家人の方は大家さんとの関係で決められていくのですので。","voiceIndex":80,"id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういうふうな中で、品川区も入って進めているわけですから、そういうところでは、こういうところで進めている、そしてご意見というふうなところも聞く場面というふうなのが必要なんじゃないかと思うんですけれども、そこら辺のところについてはどうでしょうか。","respondent":"上野都市開発課長","answer":"先ほども申し上げましたように、基本的には、借家人は大家との関係で、今の借家契約を継続するのかしないのかということを大家と十分話し合っていただいて、それで方向を定めていただくというのが基本ですので。","voiceIndex":82,"id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"大家に対してそういうふうなところをするようにというのは、そういう指導はされているんでしょうか。多分、実態としてほとんど、そういう場面が与えられていないというふうなのが実態的な状況に対しては、計画がもう決定された時点で権利保障がされて出ていくしかないというふうな、そういうふうなところでやむを得ないというふうに考えているのか、そこら辺のところの考え方はどうなんでしょうか。","respondent":"上野都市開発課長","answer":"先ほど申し上げましたように、制度上はあくまでも権利者の方々の意向がどういうふうになるのか、その権利者の方がどういう意向をするのか、それがまず決まった上で。","voiceIndex":84,"id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"〔「再開発事業じゃないじゃない」「戸建ての家だって借地には変わりない」と呼ぶ者あり〕そこら辺のところはぜひ、そこで長い間生活をし、そして営業しているというような方がたくさんいらっしゃるわけですから、そういう方々への配慮というふうなのもぜひしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-034"}]},{"id":"topic-02","title":"特定事件調査、地域危険度測定調査に関すること","agenda":"特定事件調査、地域危険度測定調査に関すること","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"先ほどの質問はこちらのほうに関係しておりますので、お回ししていただきましてありがたいと思いますけれども、地域危険度の調査ですが、最終的に危険度が出てきて、荏原町がどうだというようなこと、ある意味ではわかりやすいんですけれども、そこに緩和される要素というのはかなり、危険度の観測する要素というのはいろいろなものがありまして、街路の問題ですとか避難地へのアクセスですとか。","respondent":"浜脇住環境整備課長","answer":"私ども、それにはこれ自身は大々的にやっているようでございまして、かなりな熱意やお金もかかっているようでございまして、これを一つの活用することがいいんじゃないかということで使わせていただいて、長期計画とか実施計画を載せながらやらせていただくです。","voiceIndex":93,"id":"exchange-035"},{"speaker":"塚本委員","kind":"確認","question":"人命に関しては、措置等の部分というのが大きくなっていきます。どこにだれがいて、すぐ安否が確認できるということのほうが大切な部分が多くなってきていますので、やはり建物の危険性と人命の危険性というもの、両方に焦点を合わせたような考え方も必要なんではないかというふうに思いますけれども、いかがでしょうか。","respondent":"浜脇住環境整備課長","answer":"『まちづくりニュース』の中を見ていただきますと、２ページなんですけれども、危険度ランクの中でこういった、今委員からお話あったように、３つの要素からなってありますので、その３つの要素の中でこれらをこの地区では測定といいますか、改善が必要だというふうに思って。","voiceIndex":95,"id":"exchange-036"},{"speaker":"原委員","kind":"質問・要望","question":"１点、ちょっと確認させていただきたいんですが、各地区で、今ご説明あった取り組みの中で、まちづくり懇談会なり、まちづくり協議会なりを立ち上げたい、あるいは立ち上げるという話なんですが、１つは、懇談会と協議会、どういう役割分担をされているのかが１つ。","respondent":"浜脇住環境整備課長","answer":"失礼ですけれども、こういうまちづくりをやっていくときというのは、こうやります、ああやりますよと区のほうが説明をそういうふうにやっちゃうというふうに思われている方が大部分ですけれども、いや、本当は皆さんと一緒になって。","voiceIndex":97,"id":"exchange-037"},{"speaker":"原委員","kind":"意見","question":"気になるのは、結局、行政の意思を通じて住民の人たちにどういうふうな話し方をするのか、それからもう一つ、今、計画を立ち上げるとおっしゃったけれども、それが協議会の中で計画を立ち上げるまで育つかどうなのか、要するに話し合いで済んでしまうならば、それは一緒なわけですよ。","respondent":"浜脇住環境整備課長","answer":"そのためには、私どもとすれば、機会あるごとにＰＲ、あるいはそういった会なんかでは、あるいは説明会等を開いて、協議会、懇談会以外の会にも集まるというような会を、説明会もやっておりますけれども、知らせていただいて。","voiceIndex":99,"id":"exchange-038"},{"speaker":"原委員","kind":"質問","question":"せっかくまちづくり協議会等々を立ち上げて、さっきもお話ししたように、いくわけですから、しっかり意思を持った形のものにしてほしいし、それから多分、今、ここで『まちづくりニュース』をつくって、全戸配付していますとおっしゃっていましたけれども、渡せばいいという問題ではないということで、こういった問題についてそれなりの認識を持ってもらわないと物事って進まないんじゃないか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":101,"id":"exchange-039"},{"speaker":"木下委員","kind":"質問","question":"実際、二葉三、四丁目と西大井六丁目地区で１つの協議会をつくろうという際に、二葉は荏原だけれども、西大井六丁目は大井だということで分かれたというような話も聞いているんですが、ですけれども、地元の方々、例えば西大井六丁目の方でも、６－１番地区の方なんかは二葉四丁目町会の方々で、どうなっているんだって役員の方に聞かれたりなんかもしますので、今現状として。","respondent":"浜脇住環境整備課長","answer":"私ども、今までは前回までの地域危険調査というのがマトリックスで、５００掛ける５００の中でやっていたんですけれども、今回は町丁ごとの前提で出ちゃったわけです。ですから、町丁ごと、イコール町会の区割りとか商店街の区割りと必ずしもあっていないというのが事実です。","voiceIndex":102,"id":"exchange-040"},{"speaker":"西本委員","kind":"質問","question":"１つだけ、このニュースなんですが、先ほど全戸、例えば東中延一丁目、二丁目、中延二、三丁目というと、そこの中での全戸になるんですか。それとも、周りは多少ちょっと広げて配付するとかというのはされないんでしょうか。","respondent":"浜脇住環境整備課長","answer":"今、１ページ目にあります範囲の中だけです。周辺のほうにはしておりません。それでもって今、これでいうと２９.４ヘクタールで、約３,０００戸ぐらいに全戸配付をしています。","voiceIndex":104,"id":"exchange-041"},{"speaker":"西本委員","kind":"質問","question":"こういう形でなくてもいいとは思うんですが、非常に地域に密着した内容になっていると思うんですが、興味ある方はたくさんいらっしゃると思いますし、こういう協議会もあるんだということの啓蒙活動にもなると思うので、違う形でもいいので、品川区全域にお知らせできるような、そういう工夫に、広げることはできないものなんでしょうか。","respondent":"浜脇住環境整備課長","answer":"私ども、まちづくりをするときに、先ほど申し上げたように、地域危険度というのが、何丁目何番地ではこういう地域でということで、しっかりしていますので、それ以上の方にやりますと、またほかの方に対しても、こういう地域でこういうのをとどんどん増えてしまうので。","voiceIndex":106,"id":"exchange-042"},{"speaker":"西本委員","kind":"質問・要望","question":"ちょっとこれの運用の仕方をもう少し広げた形で考えていただきたいなと思ったりするんです。これは要望として今後検討していただきたいというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-043"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"旗の台四丁目、中延五丁目地区のまちづくりニュースもいただいていますけれども、この地域は来年度が事業を考えたいというふうなことになっていると思うんですけれども、そういう点では、この地域、それから戸越一、二丁目地区が来年度、荏原北地区は今年度で事業完了予定というふうなことになっていますけれども、本当に区の方が時間外を使いながら地域の方たちと一緒に。","respondent":"浜脇住環境整備課長","answer":"先ほど申しましたように、地域危険度のことでいいますと、前回が平成７年か８年の時の第４回のときには升三つぐらいで５００ｍでやっておりまして、その中の危険度だったんです。","voiceIndex":109,"id":"exchange-044"},{"speaker":"三上委員","kind":"提案","question":"１つ、これは委員長にも提案という形になると思います。課長にとってみたって、過去の話を、ここまでやりましたということをもう少し示していただいて、ここまでやりましたというものがあって、ですからこの地域にあっても、引き続いてきちっとやってきた経過を踏まえてこういうふうに成功に結びつけていきたいんだと。事業年度というものが二葉三、四丁目で平成２６年度完成だと。どう思われますか。","respondent":"浜脇住環境整備課長、菊地委員長","answer":"地元のほうには、実をいいますと、今３地区の新しいところにつきましては、荏原北地区や戸越一、二丁目地区の１０年間の取り組みというので、こういうもので、こういう経過があって、こうなってきたと。今、三上委員からご提案がありました部分は大切な部分だと思います。正副で審議し、また理事者との相談の上で進めてまいりたいと思います。","voiceIndex":111,"id":"exchange-045"},{"speaker":"原委員","kind":"質問・要望","question":"今、三上委員からお話があった続きになってしまいますけれども、１２月で終わりですよね、今年は。来年１月から１、２、３、あと３回か４回しかないわけなんで、特定事件調査をまとめなきゃいけない時期に入ってくると思うので、今後の予定を、次回でも結構なんですが、どういう形にもっていきたいのかを明確に出していただきたい、こういうふうに思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":114,"id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6290#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":47342,"voices":124}}]);
